  /* =========================================================================
     RESPONSIVE BREAKPOINTS (DESKTOP & MOBILE ANDROID OPTIMIZATIONS)
     ========================================================================= */

  @media (max-width: 640px) {
    .comments-hero-header {
      flex-direction: column;
      align-items: stretch;
      gap: 10px;
    }

    .title-with-count {
      display: flex;
      align-items: center;
      justify-content: space-between;
      width: 100%;
    }

    .section-title {
      font-size: 16.5px;
