/* src/lib/components/ParticleBackground.svelte */
.particle-system {
    position: fixed;
    inset: 0;
    width: 100%;
    height: 100%;
    pointer-events: none;
    z-index: 0;
    overflow: hidden;
    contain: strict;
    background: linear-gradient(145deg, #090611 0%, #07050d 48%, #0d0916 100%);
  }

  .ambient-mesh {
    position: absolute;
    inset: 0;
    background:
      radial-gradient(ellipse 52% 38% at 50% 20%, rgba(226, 217, 245, 0.045) 0%, transparent 70%),
      radial-gradient(ellipse 68% 54% at 14% 16%, rgba(103, 51, 168, 0.22) 0%, transparent 65%),
      radial-gradient(ellipse 64% 58% at 86% 24%, rgba(73, 33, 133, 0.24) 0%, transparent 65%),
      radial-gradient(ellipse 75% 60% at 50% 52%, rgba(124, 58, 237, 0.13) 0%, transparent 70%),
      radial-gradient(ellipse 68% 58% at 18% 84%, rgba(92, 43, 154, 0.20) 0%, transparent 65%),
      radial-gradient(ellipse 65% 56% at 85% 88%, rgba(67, 31, 119, 0.20) 0%, transparent 65%);
    pointer-events: none;
  }

  .ambient-glow {
    position: absolute;
    border-radius: 50%;
    opacity: 0.75;
    pointer-events: none;
  }

  .glow-top {
    top: -160px;
    left: 50%;
    transform: translateX(-50%);
    width: min(1000px, 120vw);
    height: 520px;
    background: radial-gradient(ellipse at center, rgba(139, 92, 246, 0.12) 0%, rgba(99, 102, 241, 0.05) 42%, transparent 72%);
  }

  .glow-side {
    top: 28%;
    right: -180px;
    width: 680px;
    height: 680px;
    background: radial-gradient(circle, rgba(147, 51, 234, 0.10) 0%, rgba(79, 70, 229, 0.04) 48%, transparent 74%);
  }

  .glow-bottom-left {
    bottom: -160px;
    left: -140px;
    width: 680px;
    height: 680px;
    background: radial-gradient(circle, rgba(124, 58, 237, 0.10) 0%, rgba(48, 23, 75, 0.05) 52%, transparent 74%);
  }

  .particle-canvas {
    position: absolute;
    inset: 0;
    width: 100%;
    height: 100%;
    display: block;
  }

  .night-vignette {
    position: absolute;
    inset: 0;
    background: radial-gradient(ellipse at center, transparent 54%, rgba(4, 3, 9, 0.52) 100%);
    pointer-events: none;
  }

  :global(html.animations-paused) .particle-canvas {
    display: none;
  }

  @media (prefers-reduced-motion: reduce) {
    .particle-canvas {
      display: none;
    }
  }

/* src/lib/components/Reader.svelte */
/* ==========================================================================
     PROJECT NOX — SIGNATURE READER EXPERIENCE (RECONSTRUCTED)
     ========================================================================== */

  .reader-viewport {
    min-height: 100vh;
    width: 100%;
    position: relative;
    user-select: none;
    -webkit-user-select: none;
    transition: background-color 0.3s ease;
    overflow-x: hidden;
  }

  /* Themes */
  .reader-viewport.theme-dark {
    background-color: #06070c;
    color: #e2e8f0;
  }

  .reader-viewport.theme-oled {
    background-color: #000000;
    color: #e2e8f0;
  }

  .reader-viewport.theme-sepia {
    background-color: #1c1917;
    color: #fef3c7;
  }

  /* --------------------------------------------------------------------------
     1. PREMIER GLASS HEADER
     -------------------------------------------------------------------------- */
  .reader-glass-header {
    position: fixed;
    top: 0;
    left: 0;
    right: 0;
    height: 62px;
    background: rgba(7, 8, 14, 0.88);
    backdrop-filter: blur(24px) saturate(180%);
    -webkit-backdrop-filter: blur(24px) saturate(180%);
    border-bottom: 1px solid rgba(255, 255, 255, 0.09);
    box-shadow: 0 4px 24px rgba(0, 0, 0, 0.55);
    z-index: 80;
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 0 20px;
    padding-top: env(safe-area-inset-top, 0px);
    transition: transform 0.28s cubic-bezier(0.16, 1, 0.3, 1), opacity 0.25s ease;
  }

  .reader-glass-header.ui-hidden {
    transform: translateY(-100%);
    opacity: 0;
    pointer-events: none;
  }

  /* Left: Brand / Work Info */
  .header-left-col {
    display: flex;
    align-items: center;
    gap: 12px;
    max-width: 32%;
    overflow: hidden;
  }

  .btn-glass-back {
    height: 40px;
    padding: 0 12px 0 8px;
    border-radius: 10px;
    background: rgba(255, 255, 255, 0.05);
    border: 1px solid rgba(255, 255, 255, 0.09);
    color: #ffffff;
    display: flex;
    align-items: center;
    gap: 6px;
    text-decoration: none;
    flex-shrink: 0;
    transition: all 0.2s ease;
  }

  .btn-glass-back:hover {
    background: rgba(168, 85, 247, 0.2);
    border-color: rgba(168, 85, 247, 0.4);
    transform: translateX(-1px);
  }

  .btn-back-text {
    font-size: 12px;
    font-weight: 600;
    letter-spacing: -0.01em;
  }

  .header-work-info {
    display: flex;
    flex-direction: column;
    overflow: hidden;
  }

  .header-work-title-link {
    text-decoration: none;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
  }

  .header-work-title {
    font-size: 13.5px;
    font-weight: 700;
    color: #ffffff;
    letter-spacing: -0.01em;
    transition: color 0.18s ease;
  }

  .header-work-title-link:hover .header-work-title {
    color: #c084fc;
  }

  .header-sub-meta {
    display: flex;
    align-items: center;
    gap: 6px;
    margin-top: 1px;
  }

  .header-chapter-badge {
    font-size: 11px;
    font-weight: 600;
    color: #c084fc;
  }

  .preview-tag {
    font-size: 9px;
    font-weight: 800;
    color: #f59e0b;
    background: rgba(245, 158, 11, 0.15);
    padding: 1px 5px;
    border-radius: 4px;
    text-transform: uppercase;
    letter-spacing: 0.04em;
  }

  /* Center: Navigation Shortcuts + Reading Meta */
  .header-center-col {
    display: flex;
    align-items: center;
    gap: 14px;
    justify-content: center;
    flex: 1;
    max-width: 44%;
  }

  .chapter-nav-cluster {
    display: flex;
    align-items: center;
    background: rgba(255, 255, 255, 0.04);
    border: 1px solid rgba(255, 255, 255, 0.08);
    border-radius: 10px;
    padding: 3px;
    gap: 2px;
  }

  .chapter-quick-btn {
    width: 32px;
    height: 32px;
    border-radius: 8px;
    display: flex;
    align-items: center;
    justify-content: center;
    color: #cbd5e1;
    text-decoration: none;
    transition: all 0.18s ease;
  }

  .chapter-quick-btn:hover:not(.disabled) {
    background: rgba(168, 85, 247, 0.2);
    color: #ffffff;
  }

  .chapter-quick-btn.disabled {
    opacity: 0.25;
    pointer-events: none;
  }

  .chapter-selector-pill {
    display: flex;
    align-items: center;
    gap: 6px;
    padding: 0 10px;
    height: 32px;
    border: none;
    background: rgba(255, 255, 255, 0.04);
    border-radius: 7px;
    color: #f1f5f9;
    font-size: 12px;
    font-weight: 700;
    cursor: pointer;
    transition: all 0.18s ease;
  }

  .chapter-selector-pill:hover {
    background: rgba(255, 255, 255, 0.08);
    color: #ffffff;
  }

  .header-meta-divider {
    width: 1px;
    height: 24px;
    background: rgba(255, 255, 255, 0.1);
  }

  .reading-meta-cluster {
    display: flex;
    align-items: center;
    gap: 8px;
  }

  .page-counter-pill {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    height: 32px;
    padding: 0 12px;
    min-width: 58px;
    background: rgba(255, 255, 255, 0.05);
    border: 1px solid rgba(255, 255, 255, 0.1);
    border-radius: 9999px;
    font-size: 12px;
    font-weight: 700;
    color: #f1f5f9;
    letter-spacing: 0.02em;
    font-variant-numeric: tabular-nums;
    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.25);
  }

  .current-page-num {
    color: #ffffff;
    font-weight: 700;
  }

  .page-sep {
    margin: 0 4px;
    color: #64748b;
    font-weight: 500;
  }

  .total-pages-num {
    color: #94a3b8;
    font-weight: 600;
  }

  /* Modal de Exclusão de Download Offline */
  .delete-download-backdrop {
    position: fixed;
    inset: 0;
    background: rgba(0, 0, 0, 0.78);
    backdrop-filter: blur(8px);
    -webkit-backdrop-filter: blur(8px);
    z-index: 1200;
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 16px;
    animation: fadeInModal 0.15s ease-out;
  }

  .delete-download-card {
    width: 100%;
    max-width: 400px;
    background: #111218;
    border: 1px solid rgba(244, 63, 94, 0.3);
    border-radius: 16px;
    padding: 24px;
    box-shadow: 0 20px 50px rgba(0, 0, 0, 0.8), 0 0 30px rgba(244, 63, 94, 0.12);
    display: flex;
    flex-direction: column;
    align-items: center;
    text-align: center;
    animation: scaleInCard 0.18s cubic-bezier(0.16, 1, 0.3, 1);
  }

  @keyframes fadeInModal {
    from { opacity: 0; }
    to { opacity: 1; }
  }

  @keyframes scaleInCard {
    from { opacity: 0; transform: scale(0.95); }
    to { opacity: 1; transform: scale(1); }
  }

  .delete-download-icon-wrap {
    width: 48px;
    height: 48px;
    border-radius: 50%;
    background: rgba(244, 63, 94, 0.12);
    border: 1px solid rgba(244, 63, 94, 0.25);
    display: flex;
    align-items: center;
    justify-content: center;
    margin-bottom: 14px;
  }

  .delete-download-title {
    font-size: 16px;
    font-weight: 700;
    color: #ffffff;
    margin: 0 0 8px 0;
  }

  .delete-download-desc {
    font-size: 13.5px;
    color: #cbd5e1;
    line-height: 1.5;
    margin: 0 0 6px 0;
  }

  .delete-download-subdesc {
    font-size: 12px;
    color: #94a3b8;
    line-height: 1.45;
    margin: 0 0 20px 0;
  }

  .delete-download-actions {
    display: flex;
    align-items: center;
    gap: 10px;
    width: 100%;
  }

  .btn-modal-cancel {
    flex: 1;
    height: 40px;
    border-radius: 10px;
    background: rgba(255, 255, 255, 0.06);
    border: 1px solid rgba(255, 255, 255, 0.12);
    color: #cbd5e1;
    font-size: 13px;
    font-weight: 600;
    cursor: pointer;
    transition: all 0.15s ease;
  }

  .btn-modal-cancel:hover {
    background: rgba(255, 255, 255, 0.1);
    color: #ffffff;
  }

  .btn-modal-confirm-delete {
    flex: 1.2;
    height: 40px;
    border-radius: 10px;
    background: #e11d48;
    border: 1px solid #f43f5e;
    color: #ffffff;
    font-size: 13px;
    font-weight: 600;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 6px;
    cursor: pointer;
    transition: all 0.15s ease;
    box-shadow: 0 4px 14px rgba(225, 29, 72, 0.35);
  }

  .btn-modal-confirm-delete:hover {
    background: #be123c;
    box-shadow: 0 6px 20px rgba(225, 29, 72, 0.5);
  }

  /* Right: Actions */
  .header-right-col {
    display: flex;
    align-items: center;
    gap: 8px;
    justify-content: flex-end;
    max-width: 32%;
  }

  .header-action-btn {
    height: 40px;
    padding: 0 12px;
    border-radius: 10px;
    background: rgba(255, 255, 255, 0.05);
    border: 1px solid rgba(255, 255, 255, 0.09);
    color: #cbd5e1;
    display: flex;
    align-items: center;
    gap: 7px;
    cursor: pointer;
    transition: all 0.2s ease;
  }

  .header-action-btn:hover {
    background: rgba(255, 255, 255, 0.09);
    color: #ffffff;
    border-color: rgba(255, 255, 255, 0.16);
  }

  .action-btn-text {
    font-size: 12px;
    font-weight: 600;
    letter-spacing: -0.01em;
  }

  .header-action-btn.btn-settings.active,
  .header-action-btn.btn-settings:hover {
    background: rgba(168, 85, 247, 0.18);
    border-color: rgba(168, 85, 247, 0.4);
    color: #d8b4fe;
  }

  .header-action-btn.downloaded {
    border-color: rgba(16, 185, 129, 0.4);
    color: #34d399;
  }

  .header-action-btn.btn-fullscreen {
    padding: 0;
    width: 40px;
    justify-content: center;
  }

  .spin-anim {
    animation: spin 1s linear infinite;
  }

  @keyframes spin {
    from { transform: rotate(0deg); }
    to { transform: rotate(360deg); }
  }

  /* Responsive header */
  @media (max-width: 900px) {
    .btn-back-text,
    .action-btn-text,
    .header-meta-divider {
      display: none;
    }

    .btn-glass-back,
    .header-action-btn {
      padding: 0;
      width: 40px;
      justify-content: center;
    }

    .header-center-col {
      gap: 8px;
    }
  }

  @media (max-width: 640px) {
    .reader-glass-header {
      height: 58px;
      padding: 0 12px;
    }

    .header-left-col {
      max-width: 42%;
      gap: 8px;
    }

    .header-work-title {
      font-size: 12px;
    }

    .chapter-nav-cluster {
      display: none;
    }
  }

  /* --------------------------------------------------------------------------
     2. READING CANVAS
     -------------------------------------------------------------------------- */
  .reading-canvas {
    width: 100%;
    display: flex;
    flex-direction: column;
    align-items: center;
    padding-top: 56px;
    min-height: calc(100vh - 56px);
  }

  .webtoon-stack {
    width: 100%;
    margin: 0 auto;
    display: flex;
    flex-direction: column;
    align-items: center;
    transition: max-width 0.2s ease;
  }

  .webtoon-stack.has-gap {
    gap: 12px;
  }

  /* Paginated Stage */
  .paginated-stage {
    width: 100%;
    margin: 0 auto;
    min-height: calc(100vh - 56px);
    display: flex;
    align-items: center;
    justify-content: center;
    position: relative;
  }

  .paginated-page-wrap {
    width: 100%;
  }

  .paginated-nav-overlay {
    position: fixed;
    inset: 56px 0 0 0;
    pointer-events: none;
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 0 16px;
    transition: opacity 0.25s ease;
  }

  .paginated-nav-overlay.ui-hidden {
    opacity: 0;
  }

  .paginated-arrow-btn {
    pointer-events: auto;
    width: 48px;
    height: 48px;
    border-radius: 50%;
    background: rgba(6, 7, 12, 0.7);
    border: 1px solid rgba(255, 255, 255, 0.15);
    color: #ffffff;
    display: flex;
    align-items: center;
    justify-content: center;
    cursor: pointer;
    box-shadow: 0 4px 16px rgba(0, 0, 0, 0.5);
    transition: all 0.2s ease;
  }

  .paginated-arrow-btn:hover {
    background: rgba(168, 85, 247, 0.4);
    border-color: #a855f7;
    transform: scale(1.1);
  }

  /* --------------------------------------------------------------------------
     3. COMPACT RECONSTRUCTED CONCLUSION SECTION
     -------------------------------------------------------------------------- */
  .reader-conclusion-section {
    width: 100%;
    margin: 36px auto 0 auto;
    padding: 0 16px;
    box-sizing: border-box;
    display: flex;
    flex-direction: column;
    gap: 20px;
    transition: max-width 0.2s ease;
  }

  /* Refined Integrated Navigation Console */
  .compact-completion-card {
    position: relative;
    border-radius: 16px;
    background: #090a12;
    border: 1px solid rgba(255, 255, 255, 0.08);
    padding: 16px 20px;
    box-shadow: 0 10px 30px rgba(0, 0, 0, 0.45);
    display: flex;
    flex-direction: column;
    gap: 14px;
  }

  .completion-eyebrow {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 12px;
    flex-wrap: wrap;
    padding-bottom: 2px;
  }

  .completion-status-chip {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    font-size: 11.5px;
    font-weight: 700;
    color: #e2e8f0;
    background: rgba(255, 255, 255, 0.04);
    border: 1px solid rgba(255, 255, 255, 0.06);
    padding: 3px 10px;
    border-radius: 9999px;
  }

  .completion-work-link {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    color: #94a3b8;
    font-size: 12px;
    font-weight: 500;
    text-decoration: none;
    max-width: 260px;
    transition: color 0.15s ease;
  }

  .completion-work-link:hover {
    color: #c084fc;
  }

  /* Main Hero Next Chapter Banner */
  .next-hero-banner {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 16px;
    padding: 14px 18px;
    border-radius: 12px;
    background: linear-gradient(135deg, rgba(124, 58, 237, 0.12) 0%, rgba(168, 85, 247, 0.04) 100%);
    border: 1px solid rgba(168, 85, 247, 0.28);
    transition: all 0.2s ease;
  }

  .next-hero-banner:hover {
    border-color: rgba(168, 85, 247, 0.45);
    box-shadow: 0 4px 20px rgba(168, 85, 247, 0.12);
  }

  .next-hero-left {
    display: flex;
    flex-direction: column;
    gap: 3px;
    min-width: 0;
  }

  .next-eyebrow-tag {
    font-size: 10px;
    font-weight: 800;
    color: #fbbf24;
    letter-spacing: 0.08em;
  }

  .next-title-group {
    display: flex;
    align-items: baseline;
    gap: 8px;
    flex-wrap: wrap;
  }

  .next-chapter-headline {
    font-size: 19px;
    font-weight: 800;
    color: #ffffff;
    margin: 0;
    line-height: 1.2;
  }

  .next-chapter-subhead {
    font-size: 13px;
    font-weight: 500;
    color: #94a3b8;
    max-width: 220px;
  }

  .btn-primary-next-hero {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 8px;
    padding: 11px 22px;
    border-radius: 10px;
    background: linear-gradient(135deg, #7c3aed 0%, #a855f7 100%);
    color: #ffffff;
    font-size: 13.5px;
    font-weight: 800;
    text-decoration: none;
    box-shadow: 0 4px 16px rgba(168, 85, 247, 0.38);
    transition: all 0.2s ease;
    flex-shrink: 0;
    white-space: nowrap;
  }

  .btn-primary-next-hero:hover {
    transform: translateY(-1px);
    box-shadow: 0 6px 24px rgba(168, 85, 247, 0.6);
  }

  .arrow-bounce {
    animation: bounceRight 1.5s ease-in-out infinite;
  }

  @keyframes bounceRight {
    0%, 100% { transform: translateX(0); }
    50% { transform: translateX(4px); }
  }

  /* Caught up celebration banner */
  .caught-up-banner {
    display: flex;
    align-items: center;
    gap: 14px;
    padding: 14px 16px;
    background: rgba(245, 158, 11, 0.07);
    border: 1px solid rgba(245, 158, 11, 0.22);
    border-radius: 12px;
  }

  .caught-up-icon-wrap {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 36px;
    height: 36px;
    border-radius: 8px;
    background: rgba(245, 158, 11, 0.15);
    flex-shrink: 0;
  }

  .caught-up-text {
    display: flex;
    flex-direction: column;
    gap: 2px;
  }

  .caught-up-title {
    font-size: 14px;
    font-weight: 700;
    color: #ffffff;
  }

  .caught-up-desc {
    font-size: 12px;
    color: #94a3b8;
    margin: 0;
    line-height: 1.4;
  }

  /* Structured Secondary Navigation Deck */
  .integrated-nav-deck {
    display: flex;
    align-items: center;
    gap: 8px;
    width: 100%;
  }

  .deck-btn {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 7px;
    flex: 1;
    min-height: 40px;
    padding: 8px 12px;
    background: rgba(255, 255, 255, 0.03);
    border: 1px solid rgba(255, 255, 255, 0.08);
    border-radius: 10px;
