  /* --------------------------------------------------------------------------
     BALANCED SENTIMENT REACTIONS DOCK
     -------------------------------------------------------------------------- */
  .reactions-dock-card {
    background: #090a12;
    border: 1px solid rgba(255, 255, 255, 0.08);
    border-radius: 14px;
    padding: 16px 18px;
    display: flex;
    flex-direction: column;
    gap: 12px;
  }

  .reactions-dock-header {
    display: flex;
    flex-direction: column;
    gap: 2px;
  }

  .reactions-badge {
    font-size: 9.5px;
    font-weight: 800;
    color: #a855f7;
    letter-spacing: 0.08em;
  }

  .reactions-title {
    font-size: 15px;
    font-weight: 700;
    color: #ffffff;
    margin: 0;
  }

  .reactions-capsules-wrap {
    display: flex;
    flex-wrap: wrap;
    justify-content: center;
    gap: 8px;
  }

  .reaction-capsule {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    padding: 8px 14px;
    background: rgba(255, 255, 255, 0.03);
    border: 1px solid rgba(255, 255, 255, 0.08);
    border-radius: 9999px;
    color: #cbd5e1;
    font-size: 12px;
    font-weight: 600;
    cursor: pointer;
    transition: all 0.2s cubic-bezier(0.16, 1, 0.3, 1);
  }

  .reaction-capsule:hover {
    background: rgba(255, 255, 255, 0.06);
    color: #ffffff;
    transform: translateY(-1px);
  }

  .reaction-capsule.active {
    background: rgba(168, 85, 247, 0.15);
    border-color: var(--vibe-accent, #a855f7);
    color: #ffffff;
    box-shadow: 0 0 12px rgba(168, 85, 247, 0.25);
  }

  .reaction-capsule.pop-anim {
    animation: pulsePop 0.35s ease;
  }

  @keyframes pulsePop {
    0% { transform: scale(1); }
    50% { transform: scale(1.12); }
    100% { transform: scale(1); }
  }

  .reaction-emoji {
    font-size: 16px;
    line-height: 1;
  }

  .reaction-name {
    font-size: 12px;
    font-weight: 700;
  }

  .reaction-count {
    font-size: 10.5px;
    font-weight: 700;
    color: #64748b;
    padding-left: 2px;
  }

  .reaction-count.has-votes {
    color: #c084fc;
  }

  .spectrum-bar-wrap {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 12px;
    padding-top: 4px;
  }

  .spectrum-track {
    flex: 1;
    height: 6px;
    border-radius: 9999px;
    overflow: hidden;
    display: flex;
    background: rgba(255, 255, 255, 0.05);
  }

  .spectrum-slice {
    height: 100%;
    transition: width 0.3s ease;
  }

  .spectrum-count-label {
    font-size: 10.5px;
    color: #64748b;
    white-space: nowrap;
  }

  /* --------------------------------------------------------------------------
     HIGH-VISIBILITY COMPACT RED REPORT CARD
     -------------------------------------------------------------------------- */
  .report-problem-card {
    background: rgba(220, 38, 38, 0.09);
    border: 1px solid rgba(239, 68, 68, 0.35);
    border-radius: 12px;
    padding: 12px 16px;
    box-shadow: 0 4px 14px rgba(220, 38, 38, 0.08);
  }

  .report-card-inner {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 14px;
    flex-wrap: wrap;
  }

  .report-left {
    display: flex;
    align-items: center;
    gap: 12px;
    max-width: 65%;
  }

  .report-alert-icon {
    width: 34px;
    height: 34px;
    border-radius: 8px;
    background: rgba(239, 68, 68, 0.15);
