  /* --------------------------------------------------------------------------
     CHAPTERS DRAWER
     -------------------------------------------------------------------------- */
  .drawer-backdrop {
    position: fixed;
    inset: 0;
    background: rgba(0, 0, 0, 0.7);
    backdrop-filter: blur(8px);
    -webkit-backdrop-filter: blur(8px);
    z-index: 90;
  }

  .chapters-drawer-panel {
    position: fixed;
    top: 0;
    right: 0;
    bottom: 0;
    width: min(380px, 90vw);
    background: #090b14;
    border-left: 1px solid rgba(255, 255, 255, 0.1);
    z-index: 95;
    display: flex;
    flex-direction: column;
    animation: drawerIn 0.25s cubic-bezier(0.16, 1, 0.3, 1) forwards;
  }

  @keyframes drawerIn {
    from { transform: translateX(100%); }
    to { transform: translateX(0); }
  }

  .drawer-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 16px 20px;
    border-bottom: 1px solid rgba(255, 255, 255, 0.08);
  }

  .drawer-title-group {
    display: flex;
    align-items: center;
    gap: 10px;
  }

  .drawer-title-group h3 {
    margin: 0;
    font-size: 15px;
    font-weight: 700;
    color: #ffffff;
  }

  .btn-close-drawer {
    background: transparent;
    border: none;
    color: #94a3b8;
    cursor: pointer;
  }

  .drawer-search-bar {
    display: flex;
    align-items: center;
    gap: 8px;
    padding: 10px 16px;
    background: rgba(255, 255, 255, 0.03);
    border-bottom: 1px solid rgba(255, 255, 255, 0.08);
  }

  .search-icon {
    color: #64748b;
  }

  .search-input {
    background: transparent;
    border: none;
    color: #ffffff;
    font-size: 13px;
    width: 100%;
    outline: none;
  }

  .drawer-chapters-list {
    flex: 1;
    overflow-y: auto;
    padding: 10px;
    display: flex;
    flex-direction: column;
    gap: 4px;
  }

  .drawer-chapter-item {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 10px 14px;
    border-radius: 8px;
    color: #cbd5e1;
    text-decoration: none;
    transition: all 0.2s ease;
  }

  .drawer-chapter-item:hover {
    background: rgba(255, 255, 255, 0.06);
    color: #ffffff;
  }

  .drawer-chapter-item.active {
    background: rgba(168, 85, 247, 0.18);
    border: 1px solid rgba(168, 85, 247, 0.35);
    color: #d8b4fe;
  }

  .badge-reading {
    font-size: 10px;
    font-weight: 800;
    color: #a855f7;
    background: rgba(168, 85, 247, 0.2);
    padding: 2px 6px;
    border-radius: 4px;
  }

  /* Notice Toast */
  .notice-toast {
    position: fixed;
    top: 68px;
    left: 50%;
    transform: translateX(-50%);
    background: rgba(14, 11, 22, 0.95);
    border: 1px solid rgba(168, 85, 247, 0.4);
    color: #f1f5f9;
    padding: 8px 18px;
    border-radius: 9999px;
    font-size: 12px;
    font-weight: 600;
    box-shadow: 0 4px 20px rgba(0, 0, 0, 0.6);
    z-index: 100;
  }

  /* Mobile responsiveness */
  @media (max-width: 640px) {
    .reader-glass-header {
      height: 48px;
      padding: 0 10px;
    }

    .header-left-col {
      max-width: 50%;
      gap: 8px;
    }

    .header-work-title {
      font-size: 12px;
    }

    .page-counter-pill {
      font-size: 11px;
      padding: 0 8px;
      height: 28px;
      min-width: 50px;
    }

    .btn-glass-back,
    .header-action-btn {
      width: 32px;
      height: 32px;
    }

    .btn-fullscreen {
      display: none;
    }

    .compact-completion-card {
      padding: 14px 16px;
    }

    .next-chapter-core {
      flex-direction: column;
      align-items: stretch;
      gap: 12px;
    }

    .btn-primary-next {
      width: 100%;
      justify-content: center;
      padding: 12px 18px;
    }

    .secondary-nav-row {
      flex-direction: column;
      width: 100%;
    }

    .nav-sub-btn {
      width: 100%;
      justify-content: center;
    }

    .report-left {
      max-width: 100%;
    }

    .btn-report-red {
      width: 100%;
      justify-content: center;
    }

    .reactions-capsules-wrap {
      gap: 6px;
    }

    .reaction-capsule {
      padding: 7px 11px;
      font-size: 11.5px;
    }
  }

