  }

  .header-right-tools {
    display: flex;
    align-items: center;
    gap: 1.25rem;
  }

  .view-all-link {
    display: inline-flex;
    align-items: center;
    gap: 0.4rem;
    font-size: 0.88rem;
    font-weight: 600;
    color: #94a3b8;
    text-decoration: none;
    transition: all 0.2s ease;
  }

  .view-all-link:hover {
    color: #a78bfa;
  }

  .stale-notice {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    padding: 0.55rem 1rem;
    border-radius: 8px;
    background: rgba(124, 58, 237, 0.1);
