      overflow-y: auto;
      border-bottom: none;
      animation: sheetSlideUp 0.25s cubic-bezier(0.16, 1, 0.3, 1);
    }
  }

  @keyframes sheetSlideUp {
    from {
      transform: translateY(100%);
    }
    to {
      transform: translateY(0);
    }
  }

/* src/lib/components/UserAvatar.svelte */
.user-avatar-root {
    position: relative;
    width: var(--avatar-size, 40px);
    height: var(--avatar-size, 40px);
    border-radius: 50%;
    flex-shrink: 0;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    box-sizing: border-box;
  }

  .avatar-inner {
    width: 100%;
    height: 100%;
    border-radius: 50%;
    overflow: hidden;
    position: relative;
    background: #111422;
    display: flex;
    align-items: center;
    justify-content: center;
  }

  .avatar-image {
    width: 100%;
    height: 100%;
    object-fit: cover;
    object-position: center;
    display: block;
  }

  .avatar-fallback {
    font-weight: 800;
    color: #e6dcfe;
    letter-spacing: 0.05em;
    user-select: none;
  }

  .avatar-frame-overlay {
    position: absolute;
    inset: -22%;
    width: 144%;
    height: 144%;
    pointer-events: none;
    z-index: 2;
    display: flex;
    align-items: center;
    justify-content: center;
  }

  .frame-svg {
    width: 100%;
    height: 100%;
    overflow: visible;
  }

  .avatar-custom-frame-overlay {
    position: absolute;
    top: 50%;
    left: 50%;
    width: 100%;
    height: 100%;
    pointer-events: none;
    z-index: 2;
    overflow: visible;
    display: flex;
    align-items: center;
    justify-content: center;
    transform: translate(calc(-50% + var(--frame-offset-x, 0%)), calc(-50% + var(--frame-offset-y, 0%))) scale(var(--frame-scale, 1.25));
    transform-origin: center center;
  }

  .avatar-custom-frame-asset {
    width: 100%;
    height: 100%;
    max-width: none;
    max-height: none;
    display: block;
    pointer-events: none;
  }

  .avatar-frame-image {
    position: absolute;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
    width: 128%;
    height: 128%;
    object-fit: contain;
    pointer-events: none;
    z-index: 2;
  }



