/* src/lib/components/WorkCard.svelte */
.editorial-card {
    display: flex;
    flex-direction: column;
    position: relative;
    border-radius: 16px;
    background: #0d101a;
    border: 1px solid rgba(255, 255, 255, 0.06);
    overflow: hidden;
    transition: all 0.35s cubic-bezier(0.16, 1, 0.3, 1);
    animation: cardFadeIn 0.5s cubic-bezier(0.16, 1, 0.3, 1) both;
    animation-delay: var(--stagger, 0ms);
  }

  @keyframes cardFadeIn {
    from {
      opacity: 0;
      transform: translateY(12px);
    }
    to {
      opacity: 1;
      transform: translateY(0);
    }
  }

  .editorial-card:hover {
    transform: translateY(-6px);
    border-color: rgba(181, 154, 245, 0.35);
    box-shadow: 0 16px 36px -8px rgba(109, 40, 217, 0.28), 0 0 20px rgba(181, 154, 245, 0.12);
  }

  .card-media {
    position: relative;
