/* src/lib/components/WorkRating.svelte */
.rating-widget {
    display: inline-flex;
    align-items: center;
    gap: 14px;
    min-height: 44px;
    padding: 6px 16px;
    background: rgba(14, 12, 26, 0.45);
    border: 1px solid rgba(181, 154, 245, 0.12);
    border-radius: 10px;
    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.2);
    backdrop-filter: blur(8px);
    margin: 4px 0 10px;
    width: fit-content;
    max-width: 100%;
    flex-wrap: wrap;
    box-sizing: border-box;
    transition: border-color 0.2s ease, background 0.2s ease;
  }

  .rating-widget:hover {
    border-color: rgba(181, 154, 245, 0.22);
    background: rgba(18, 15, 32, 0.55);
  }

  .rating-score-box {
    display: inline-flex;
    align-items: center;
    gap: 8px;
    background: none;
    border: none;
    padding: 0;
    cursor: pointer;
    text-align: left;
    color: inherit;
    border-radius: 6px;
    transition: opacity 0.15s ease;
  }

  .rating-score-box:hover {
    opacity: 0.85;
  }

  .score-star-wrap {
    display: flex;
    align-items: center;
    color: #ffd154;
    filter: drop-shadow(0 0 6px rgba(255, 209, 84, 0.45));
  }

  .rating-number {
    font-size: 1.35rem;
    font-weight: 800;
    line-height: 1;
    color: #ffd154;
    letter-spacing: -0.01em;
    font-variant-numeric: tabular-nums;
  }

  .rating-scale {
    font-size: 0.82rem;
    font-weight: 600;
    color: rgba(226, 232, 240, 0.5);
  }

  .rating-empty-badge {
    font-size: 0.82rem;
    font-weight: 600;
    color: rgba(226, 232, 240, 0.7);
    background: rgba(255, 255, 255, 0.06);
    padding: 3px 9px;
    border-radius: 999px;
  }

  .rating-count {
    font-size: 0.84rem;
    color: rgba(226, 232, 240, 0.65);
    font-weight: 600;
  }

  .btn-breakdown-hint {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 22px;
    height: 22px;
    border-radius: 6px;
    background: rgba(181, 154, 245, 0.08);
    color: rgba(181, 154, 245, 0.65);
    transition: all 0.15s ease;
  }

  .rating-score-box:hover .btn-breakdown-hint {
    background: rgba(181, 154, 245, 0.2);
    color: #c4b5fd;
  }

  .rating-divider {
    width: 1px;
    height: 20px;
    background: rgba(181, 154, 245, 0.14);
  }

  .rating-interactive-row {
    display: inline-flex;
    align-items: center;
    gap: 10px;
    padding-top: 0;
    border-top: none;
    flex-wrap: wrap;
  }

  .rate-prompt {
    font-size: 0.92rem;
    font-weight: 700;
    color: #f1f5f9;
    letter-spacing: -0.01em;
    white-space: nowrap;
  }

  .prompt-text-desktop {
    display: inline;
  }

  .prompt-text-mobile {
    display: none;
  }

  .interactive-stars {
    display: flex;
    align-items: center;
    gap: 3px;
  }

  .star-btn {
    width: 32px;
    height: 32px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    background: none;
    border: none;
    padding: 0;
    color: rgba(181, 154, 245, 0.38);
    cursor: pointer;
    border-radius: 6px;
    touch-action: manipulation;
    transition: transform 0.15s ease, color 0.15s ease;
  }

  .star-btn:hover {
    transform: scale(1.2);
    color: #ffd154;
  }

  .star-btn.is-active {
    color: #ffd154;
    filter: drop-shadow(0 0 6px rgba(255, 209, 84, 0.5));
  }

  .rating-tooltip-label {
    font-size: 0.8rem;
    font-weight: 700;
    color: #ffd154;
    white-space: nowrap;
  }

  .voting-spinner {
    color: #a78bfa;
    margin-left: 2px;
  }

  /* User Vote Chip & Discrete Removal Popover */
  .user-vote-chip-group {
    position: relative;
    display: inline-flex;
    align-items: center;
    gap: 2px;
  }

  .user-score-chip {
    display: inline-flex;
    align-items: center;
    gap: 4px;
    font-size: 0.74rem;
    font-weight: 600;
    color: #c4b5fd;
    background: rgba(167, 139, 250, 0.1);
    border: 1px solid rgba(167, 139, 250, 0.2);
    padding: 2px 7px;
    border-radius: 999px;
  }

  .btn-rating-options {
    width: 22px;
    height: 22px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    background: rgba(255, 255, 255, 0.05);
    border: 1px solid rgba(181, 154, 245, 0.15);
    border-radius: 50%;
    color: rgba(226, 232, 240, 0.6);
    cursor: pointer;
    transition: all 0.15s ease;
  }

  .btn-rating-options:hover {
    color: #ffffff;
    background: rgba(181, 154, 245, 0.15);
  }

  .rating-options-popover {
    position: absolute;
    top: 100%;
    right: 0;
    margin-top: 6px;
    background: #141220;
    border: 1px solid rgba(181, 154, 245, 0.2);
    border-radius: 8px;
    padding: 4px;
    box-shadow: 0 8px 24px rgba(0, 0, 0, 0.6);
    z-index: 50;
    white-space: nowrap;
  }

  .btn-popover-remove {
    display: flex;
    align-items: center;
    gap: 6px;
    width: 100%;
    padding: 6px 10px;
    background: none;
    border: none;
    font-size: 0.78rem;
    font-weight: 600;
    color: #f87171;
    cursor: pointer;
    border-radius: 6px;
    transition: background 0.15s ease;
  }

  .btn-popover-remove:hover {
    background: rgba(248, 113, 113, 0.12);
  }

  /* Mobile Responsive Tweaks: Comfortable Touch Targets (44px min) */
  @media (max-width: 768px) {
    .rating-widget {
      width: 100%;
      justify-content: space-between;
      min-height: 44px;
      padding: 6px 12px;
      gap: 8px;
      margin: 4px 0 8px;
      box-shadow: none;
    }

    .rating-number {
      font-size: 1.2rem;
    }

    .rating-divider {
      display: none;
    }

    .rating-interactive-row {
      gap: 4px;
    }

    .rate-prompt {
      font-size: 0.8rem;
      font-weight: 600;
      color: rgba(226, 232, 240, 0.7);
    }

    .star-btn {
      min-width: 44px;
      min-height: 44px;
      width: 44px;
      height: 44px;
    }

    .star-btn:active {
      transform: scale(1.18);
    }
  }

  /* Distribution / Breakdown Modal */
  .rating-modal-backdrop {
    position: fixed;
    inset: 0;
    background: rgba(4, 5, 10, 0.8);
    backdrop-filter: blur(8px);
    z-index: 9999;
    display: flex;
    align-items: flex-end;
    justify-content: center;
    animation: fadeIn 0.2s ease-out;
  }

  .rating-modal-sheet {
    position: relative;
    width: 100%;
    max-width: 460px;
    background: #0d0f17;
    border: 1px solid rgba(181, 154, 245, 0.22);
    border-radius: 18px 18px 0 0;
    padding: 16px 20px max(28px, calc(16px + env(safe-area-inset-bottom, 0px)));
    box-shadow: 0 -10px 40px rgba(0, 0, 0, 0.7);
    animation: slideUp 0.25s cubic-bezier(0.16, 1, 0.3, 1);
  }

  .sheet-handle {
    width: 36px;
    height: 4px;
    background: rgba(255, 255, 255, 0.2);
    border-radius: 999px;
    margin: 0 auto 12px;
  }

  .sheet-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    margin-bottom: 14px;
  }

  .sheet-header h3 {
    font-size: 1.1rem;
    font-weight: 700;
    color: #f8fafc;
    margin: 0;
  }

  .btn-sheet-close {
    background: rgba(255, 255, 255, 0.08);
    border: none;
    color: #94a3b8;
    width: 30px;
    height: 30px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    cursor: pointer;
  }

  .modal-score-summary {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 12px 14px;
    background: rgba(255, 255, 255, 0.03);
    border: 1px solid rgba(181, 154, 245, 0.1);
    border-radius: 10px;
    margin-bottom: 14px;
    flex-wrap: wrap;
    gap: 10px;
  }

  .modal-score-big {
    display: flex;
    align-items: center;
    gap: 8px;
  }

  .modal-avg {
    font-size: 1.7rem;
    font-weight: 800;
    color: #ffd154;
  }

  .modal-stars-row {
    display: flex;
    align-items: center;
    gap: 2px;
  }

  .modal-total-count {
    font-size: 0.8rem;
    color: rgba(226, 232, 240, 0.6);
  }

  .modal-user-vote-banner {
    display: flex;
    flex-direction: column;
    align-items: flex-end;
    font-size: 0.76rem;
    color: rgba(226, 232, 240, 0.6);
  }

  .modal-user-vote-banner strong {
    color: #c4b5fd;
    font-size: 0.85rem;
  }

  .distribution-bars {
    display: flex;
    flex-direction: column;
    gap: 6px;
    margin-bottom: 14px;
  }

  .dist-row-btn {
    display: flex;
    align-items: center;
    gap: 8px;
    background: rgba(255, 255, 255, 0.02);
    border: 1px solid rgba(181, 154, 245, 0.08);
    border-radius: 8px;
    padding: 7px 10px;
    color: #e2e8f0;
    cursor: pointer;
    touch-action: manipulation;
    transition: all 0.15s ease;
  }

  .dist-row-btn:hover {
    background: rgba(181, 154, 245, 0.08);
    border-color: rgba(181, 154, 245, 0.2);
  }

  .dist-row-btn.is-my-vote {
    background: rgba(167, 139, 250, 0.12);
    border-color: #a78bfa;
  }

  .dist-score-lbl {
    font-size: 0.8rem;
    font-weight: 700;
    min-width: 22px;
    color: #ffd154;
  }

  .dist-track {
    flex: 1;
    height: 7px;
    background: rgba(255, 255, 255, 0.06);
    border-radius: 999px;
    overflow: hidden;
  }

  .dist-bar-fill {
    height: 100%;
    background: linear-gradient(90deg, #7c3aed 0%, #ffd154 100%);
    border-radius: 999px;
    transition: width 0.3s ease;
