    align-items: center;
    justify-content: center;
    padding: 3rem 1.5rem;
    color: #f1f5f9;
  }

  .auth-grid-container {
    max-width: 1160px;
    width: 100%;
    margin: 0 auto;
    display: grid;
    grid-template-columns: 1.15fr 1fr;
    gap: 4.5rem;
    align-items: center;
  }

  /* Left Branding Column */
  .auth-branding-col {
    display: flex;
    flex-direction: column;
  }

  .brand-pill {
    display: inline-flex;
    align-items: center;
    gap: 0.5rem;
    padding: 0.35rem 0.85rem;
    background: rgba(139, 92, 246, 0.15);
    border: 1px solid rgba(139, 92, 246, 0.3);
    border-radius: 9999px;
    color: #c4b5fd;
    font-size: 0.76rem;
    font-weight: 700;
    letter-spacing: 0.05em;
    margin-bottom: 1.25rem;
    width: fit-content;
  }

  .brand-headline {
    font-family: 'Manrope', -apple-system, BlinkMacSystemFont, sans-serif;
    font-size: 3.2rem;
    font-weight: 800;
    line-height: 1.12;
    color: #ffffff;
    margin: 0 0 1.25rem;
    letter-spacing: -0.025em;
  }

  .gradient-text {
    background: linear-gradient(135deg, #a78bfa 0%, #c084fc 50%, #dfc28d 100%);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
  }

  .brand-subtext {
    font-size: 1.05rem;
    color: #94a3b8;
    line-height: 1.6;
    margin: 0 0 2.5rem;
    max-width: 480px;
  }

  .platform-perks-list {
    display: flex;
    flex-direction: column;
    gap: 1.25rem;
  }

  .perk-item {
    display: flex;
    align-items: flex-start;
    gap: 1rem;
  }

  .perk-icon-wrap {
    width: 38px;
    height: 38px;
    border-radius: 10px;
    background: rgba(139, 92, 246, 0.12);
    border: 1px solid rgba(139, 92, 246, 0.25);
    display: flex;
    align-items: center;
    justify-content: center;
    color: #c4b5fd;
    flex-shrink: 0;
  }

  .perk-content {
    display: flex;
    flex-direction: column;
    gap: 0.2rem;
  }

  .perk-title {
    font-size: 0.95rem;
    font-weight: 700;
    color: #f1f5f9;
    margin: 0;
  }

  .perk-desc {
    font-size: 0.82rem;
    color: #64748b;
    line-height: 1.45;
    margin: 0;
  }

  /* Right Glass Card */
  .auth-form-col {
    display: flex;
    justify-content: center;
    width: 100%;
  }

  .auth-card-glass {
    width: 100%;
    max-width: 460px;
    background: rgba(18, 17, 26, 0.92);
    border: 1px solid rgba(255, 255, 255, 0.08);
    border-radius: 20px;
    padding: 2.5rem;
    box-shadow: 0 20px 50px -10px rgba(0, 0, 0, 0.8),
      0 0 0 1px rgba(139, 92, 246, 0.1);
    backdrop-filter: blur(16px);
  }

  .auth-card-header {
    margin-bottom: 1.75rem;
  }

  .auth-card-title {
    font-size: 1.75rem;
    font-weight: 800;
    color: #ffffff;
    margin: 0 0 0.5rem;
    letter-spacing: -0.015em;
  }

  .auth-card-subtitle {
    font-size: 0.88rem;
    color: #94a3b8;
    line-height: 1.5;
    margin: 0;
  }

  /* Alerts */
  .auth-alert {
    display: flex;
    align-items: flex-start;
    gap: 0.75rem;
    padding: 0.85rem 1rem;
    border-radius: 12px;
    font-size: 0.86rem;
    line-height: 1.5;
    margin-bottom: 1.5rem;
  }

  .auth-alert.error {
    background: rgba(239, 68, 68, 0.12);
    border: 1px solid rgba(239, 68, 68, 0.35);
    color: #fca5a5;
  }

  .auth-alert.success {
    background: rgba(16, 185, 129, 0.12);
    border: 1px solid rgba(16, 185, 129, 0.35);
    color: #6ee7b7;
  }

  .confirmation-state {
    display: grid;
    justify-items: center;
    gap: 0.7rem;
    text-align: center;
    padding: 1rem 0 1.25rem;
    margin-bottom: 0.5rem;
    border-bottom: 1px solid rgba(255, 255, 255, 0.07);
  }

  .confirmation-icon {
    width: 48px;
    height: 48px;
    display: grid;
    place-items: center;
    border-radius: 14px;
    color: #c4b5fd;
    background: rgba(139, 92, 246, 0.15);
    border: 1px solid rgba(167, 139, 250, 0.35);
  }

  .confirmation-state h3 {
    margin: 0;
    color: #fff;
    font-size: 1.1rem;
  }

  .confirmation-state p {
    max-width: 34rem;
    margin: 0;
    color: #a1a1aa;
    font-size: 0.87rem;
    line-height: 1.55;
  }

  .confirmation-state strong {
    display: inline-block;
    margin-left: 0.25rem;
    color: #e9d5ff;
    overflow-wrap: anywhere;
  }

  .resend-form {
    width: 100%;
    display: grid;
    justify-items: center;
    margin-top: 0.25rem;
  }

  .btn-secondary-auth {
    width: 100%;
    padding: 0.72rem 1rem;
    border: 1px solid rgba(196, 181, 253, 0.28);
    border-radius: 10px;
    color: #ddd6fe;
    background: rgba(139, 92, 246, 0.08);
    font: inherit;
    font-size: 0.84rem;
    font-weight: 700;
    cursor: pointer;
  }

  .btn-secondary-auth:hover:not(:disabled) {
    background: rgba(139, 92, 246, 0.16);
  }

  .btn-secondary-auth:disabled {
    cursor: not-allowed;
    opacity: 0.55;
  }

  :global(.alert-icon) {
    flex-shrink: 0;
    margin-top: 1px;
  }

  /* Form Elements */
  .auth-form-body {
    display: flex;
    flex-direction: column;
    gap: 1.25rem;
  }

  .form-group {
    display: flex;
    flex-direction: column;
    gap: 0.4rem;
  }

  .label-row {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 0.5rem;
  }

  .input-label {
    display: inline-flex;
    align-items: center;
    gap: 0.45rem;
    font-size: 0.84rem;
    font-weight: 600;
    color: #cbd5e1;
  }

  .status-indicator {
    display: inline-flex;
    align-items: center;
    gap: 0.35rem;
    font-size: 0.75rem;
    font-weight: 600;
  }

  .status-indicator.checking {
    color: #94a3b8;
  }

  .status-indicator.available {
    color: #10b981;
  }

  .status-indicator.error {
    color: #ef4444;
  }

  .caps-warning {
    display: inline-flex;
    align-items: center;
    gap: 0.3rem;
    font-size: 0.72rem;
    font-weight: 600;
    color: #f59e0b;
  }

  .input-wrap {
    position: relative;
    display: flex;
    align-items: center;
  }

  .custom-input {
    width: 100%;
    padding: 0.8rem 1rem;
    background: rgba(255, 255, 255, 0.04);
    border: 1px solid rgba(255, 255, 255, 0.1);
    border-radius: 10px;
    color: #ffffff;
    font-size: 0.92rem;
    transition: all 0.2s ease;
    font-family: inherit;
    outline: none;
  }

  .custom-input:focus {
    border-color: #8b5cf6;
    background: rgba(255, 255, 255, 0.06);
    box-shadow: 0 0 0 3px rgba(139, 92, 246, 0.2);
  }

  .input-wrap.has-prefix .input-prefix {
    position: absolute;
    left: 1rem;
    color: #64748b;
    font-weight: 700;
    font-size: 0.92rem;
    pointer-events: none;
  }

  .custom-input.with-prefix {
    padding-left: 2rem;
  }

  .custom-input.with-suffix {
    padding-right: 2.75rem;
  }

  .custom-input.valid {
    border-color: rgba(16, 185, 129, 0.5);
  }

  .custom-input.invalid {
    border-color: rgba(239, 68, 68, 0.5);
  }

  .btn-toggle-password {
    position: absolute;
    right: 0.75rem;
    background: none;
    border: none;
    color: #64748b;
    padding: 0.4rem;
    cursor: pointer;
    border-radius: 6px;
    display: flex;
    align-items: center;
    justify-content: center;
    transition: color 0.2s;
  }

  .btn-toggle-password:hover {
    color: #cbd5e1;
  }

  .field-hint {
    font-size: 0.75rem;
    color: #64748b;
    line-height: 1.4;
  }

  .forgot-row {
    display: flex;
    justify-content: flex-end;
    margin-top: -0.25rem;
  }

  .forgot-link {
    font-size: 0.8rem;
    color: #c4b5fd;
    text-decoration: none;
    font-weight: 600;
    transition: color 0.2s;
  }

  .forgot-link:hover {
    color: #ffffff;
    text-decoration: underline;
  }

  /* Submit Button */
  .btn-submit-auth {
    width: 100%;
    margin-top: 0.75rem;
    padding: 0.85rem 1.25rem;
    border-radius: 12px;
    background: linear-gradient(135deg, #7c3aed 0%, #6d28d9 100%);
    border: 1px solid rgba(255, 255, 255, 0.12);
    color: #ffffff;
    font-size: 0.95rem;
    font-weight: 700;
    cursor: pointer;
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 0.6rem;
    box-shadow: 0 4px 20px rgba(124, 58, 237, 0.35);
    transition: all 0.2s ease;
  }

  .btn-submit-auth:hover:not(:disabled) {
    background: linear-gradient(135deg, #8b5cf6 0%, #7c3aed 100%);
    box-shadow: 0 6px 25px rgba(124, 58, 237, 0.5);
    transform: translateY(-1px);
  }

  .btn-submit-auth:disabled {
    background: rgba(255, 255, 255, 0.06);
    border-color: rgba(255, 255, 255, 0.05);
    color: #64748b;
    cursor: not-allowed;
    box-shadow: none;
    transform: none;
  }

  .btn-toggle-password:focus-visible,
  .btn-submit-auth:focus-visible,
  .btn-secondary-auth:focus-visible,
  .switch-link:focus-visible,
  .forgot-link:focus-visible {
    outline: 2px solid #c4b5fd;
    outline-offset: 3px;
  }

  /* Footer */
  .auth-card-footer {
    margin-top: 1.75rem;
    padding-top: 1.25rem;
    border-top: 1px solid rgba(255, 255, 255, 0.06);
    text-align: center;
    display: flex;
    flex-direction: column;
    gap: 0.75rem;
  }

  .switch-text {
    font-size: 0.85rem;
    color: #94a3b8;
    margin: 0;
  }

  .switch-link {
    color: #c4b5fd;
    font-weight: 700;
    text-decoration: none;
    transition: color 0.2s;
  }

  .switch-link:hover {
    color: #ffffff;
    text-decoration: underline;
  }

  .privacy-note {
    font-size: 0.74rem;
    color: #475569;
    line-height: 1.5;
    margin: 0;
  }

  .privacy-link {
    color: #64748b;
    text-decoration: none;
  }

  .privacy-link:hover {
    color: #94a3b8;
    text-decoration: underline;
  }

  .spin-icon {
    animation: spin 1s linear infinite;
  }

  @keyframes spin {
    from {
      transform: rotate(0deg);
    }
    to {
      transform: rotate(360deg);
    }
  }

  /* Responsive Breakpoints */
  @media (max-width: 960px) {
    .auth-grid-container {
      grid-template-columns: 1fr;
      gap: 3rem;
    }

    .auth-branding-col {
      text-align: center;
      align-items: center;
    }

    .brand-headline {
      font-size: 2.4rem;
    }

    .platform-perks-list {
      display: none;
    }
  }

  @media (max-width: 500px) {
    .auth-page-wrapper {
      padding: 1.5rem 1rem;
    }

    .auth-card-glass {
      padding: 1.75rem 1.25rem;
    }

    .brand-headline {
      font-size: 2rem;
    }

    .auth-card-header {
      margin-bottom: 1.25rem;
    }

    .auth-card-title {
      font-size: 1.5rem;
    }

    .input-label,
    .custom-input,
    .btn-submit-auth,
    .btn-secondary-auth {
      font-size: 0.9rem;
    }
  }

/* src/routes/admin/+layout.svelte */
.admin-shell {
    display: grid;
    grid-template-columns: 260px minmax(0, 1fr);
    max-width: 1520px;
    margin: 0 auto;
    min-height: calc(100vh - 78px);
    position: relative;
    padding: 0 16px;
    gap: 24px;
  }

  /* Sidebar */
  .admin-sidebar {
    position: sticky;
    top: 86px;
    height: calc(100vh - 102px);
    display: flex;
    flex-direction: column;
    background: rgba(13, 17, 23, 0.75);
    border: 1px solid rgba(255, 255, 255, 0.08);
    border-radius: 16px;
    backdrop-filter: blur(12px);
    overflow: hidden;
    z-index: 100;
  }

  .sidebar-header {
    padding: 18px 18px 14px 18px;
    border-bottom: 1px solid rgba(255, 255, 255, 0.06);
    position: relative;
  }

  .brand-cluster {
    display: flex;
    align-items: center;
    gap: 10px;
    margin-bottom: 14px;
  }

  .sidebar-symbol {
    border-radius: 8px;
  }

  .brand-text {
    display: flex;
    flex-direction: column;
  }

  .brand-editorial {
    font-size: 13.5px;
    font-weight: 850;
    letter-spacing: 0.08em;
    color: #dfc28d;
  }

  .brand-sub {
    font-size: 11px;
    color: #94a3b8;
    font-weight: 550;
  }

  .drawer-close-btn {
    display: none;
    position: absolute;
    top: 16px;
    right: 16px;
    background: rgba(255, 255, 255, 0.06);
    border: 1px solid rgba(255, 255, 255, 0.1);
    color: #94a3b8;
    width: 32px;
    height: 32px;
    border-radius: 8px;
    cursor: pointer;
    align-items: center;
    justify-content: center;
  }

  /* Operator Card */
  .operator-card {
    display: flex;
    align-items: center;
    gap: 10px;
    padding: 10px 12px;
    border-radius: 10px;
    background: rgba(255, 255, 255, 0.03);
    border: 1px solid rgba(255, 255, 255, 0.06);
  }

  .operator-avatar {
    position: relative;
    width: 34px;
    height: 34px;
    flex-shrink: 0;
  }

  .avatar-img {
    width: 100%;
    height: 100%;
    border-radius: 50%;
    object-fit: cover;
  }

  .avatar-fallback {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 100%;
    height: 100%;
    border-radius: 50%;
    background: #1e293b;
    color: #dfc28d;
    font-size: 13px;
    font-weight: 750;
  }

  .operator-status-dot {
    position: absolute;
    bottom: -1px;
    right: -1px;
    width: 8px;
    height: 8px;
    border-radius: 50%;
    background: #22c55e;
    box-shadow: 0 0 6px rgba(34, 197, 94, 0.6);
    border: 1.5px solid #0d1117;
  }

  .operator-meta {
    display: flex;
    flex-direction: column;
    gap: 3px;
    min-width: 0;
  }

  .operator-name {
    font-size: 12.5px;
    font-weight: 700;
    color: #f1f5f9;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
  }

  .operator-badge {
    display: inline-flex;
    align-items: center;
    gap: 4px;
    padding: 2px 6px;
    border-radius: 4px;
    font-size: 10px;
    font-weight: 700;
    letter-spacing: 0.03em;
    width: fit-content;
  }

  .badge-admin {
