  }

  .category-title-group {
    display: inline-flex;
    align-items: center;
    gap: 6px;
  }
  .category-badge {
    padding: 1px 6px;
    border-radius: 999px;
    font-size: 10px;
    font-weight: 800;
    line-height: 1.1;
  }
  .category-badge.alert {
