    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    margin-top: 2px;
  }

  .work-alias-pill {
    display: inline-flex;
    align-items: center;
    gap: 4px;
    font-size: 11px;
    color: #c0a8f8;
    background: rgba(181, 154, 245, 0.12);
    border: 1px solid rgba(181, 154, 245, 0.25);
    padding: 1px 7px;
    border-radius: 4px;
    max-width: 260px;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
  }

  .mobile-alias-sub {
    display: inline-block;
    font-size: 11px;
    color: #c0a8f8;
    background: rgba(181, 154, 245, 0.12);
    border: 1px solid rgba(181, 154, 245, 0.25);
    padding: 1px 6px;
    border-radius: 4px;
    margin-top: 3px;
    max-width: 220px;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
  }

  @media (max-width: 540px) {
    .header-actions {
      flex-direction: column;
    }

    .btn-primary-add,
    .btn-secondary-sync {
      width: 100%;
      box-sizing: border-box;
    }

    .pagination-bar {
      flex-direction: column;
      align-items: center;
      gap: 12px;
    }

    .pagination-controls {
      justify-content: center;
      width: 100%;
    }
  }

