    gap: 24px;
  }

  .panel {
    background: #110d1a;
    border: 1px solid #231b31;
    border-radius: 14px;
    padding: 24px;
  }

  .panel-header {
    display: flex;
    align-items: center;
    gap: 10px;
    margin-bottom: 20px;
  }

  .title-with-icon {
    display: flex;
    align-items: center;
    gap: 8px;
  }

  :global(.panel-icon) {
    color: var(--purple, #a78bfa);
  }

  .panel-header h2 {
    font-size: 18px;
    font-weight: 600;
    color: #f1f5f9;
    margin: 0;
  }

  /* Staff accordion */
  .staff-import-accordion {
    margin-bottom: 20px;
    background: #181224;
    border: 1px solid #2d213f;
    border-radius: 10px;
    overflow: hidden;
  }

  .staff-import-accordion summary {
    padding: 12px 16px;
    font-size: 13px;
    font-weight: 500;
    color: #c4b5fd;
    cursor: pointer;
    user-select: none;
  }

  .staff-import-body {
    padding: 14px 16px 18px;
    border-top: 1px solid #2d213f;
    display: flex;
    flex-direction: column;
    gap: 12px;
  }

  .finals-picker-card {
    background: #181224;
    border: 1px solid #3d2b56;
    border-radius: 10px;
    padding: 16px;
    margin-bottom: 20px;
    display: flex;
    flex-direction: column;
    gap: 12px;
  }

  .finals-picker-controls {
    display: flex;
    gap: 12px;
    flex-wrap: wrap;
  }

  .form-grid {
    display: grid;
    grid-template-columns: 1fr 2fr;
    gap: 18px;
    margin-bottom: 20px;
  }

  @media (max-width: 680px) {
    .form-grid {
      grid-template-columns: 1fr;
    }
  }

  .field {
    display: flex;
    flex-direction: column;
    gap: 8px;
    font-size: 12px;
    font-weight: 600;
    color: #cbd5e1;
  }

  .field input {
    background: #090610;
    border: 1px solid #2a2039;
    color: #f1f5f9;
    padding: 10px 14px;
    border-radius: 8px;
    font-size: 14px;
    transition: border-color 0.15s ease;
  }

  .field input:focus {
    outline: none;
    border-color: #9333ea;
  }

  .field input:disabled {
    opacity: 0.6;
    cursor: not-allowed;
  }

  .col-full {
    grid-column: 1 / -1;
  }

  .field-label {
    font-size: 12px;
    font-weight: 700;
    color: #dfc28d;
  }

  .chapter-scans-chips {
    display: flex;
    flex-wrap: wrap;
    gap: 8px;
    margin-top: 4px;
  }

  .scan-chip-label {
    display: inline-flex;
    align-items: center;
    gap: 7px;
    padding: 6px 12px;
    border-radius: 8px;
    background: rgba(255, 255, 255, 0.04);
    border: 1px solid rgba(255, 255, 255, 0.08);
    font-size: 12px;
    color: #cbd5e1;
    cursor: pointer;
    transition: all 0.2s ease;
  }

  .scan-chip-label:hover {
    background: rgba(255, 255, 255, 0.08);
    color: #ffffff;
  }

  .scan-chip-label.active {
    background: rgba(139, 92, 246, 0.2);
    border-color: rgba(139, 92, 246, 0.5);
    color: #ffffff;
    font-weight: 600;
  }

  .scan-chip-label.is-official {
    border-color: rgba(201, 170, 115, 0.35);
  }

  .scan-chip-label.is-official.active {
    background: rgba(201, 170, 115, 0.2);
    border-color: rgba(201, 170, 115, 0.6);
    color: #fef08a;
  }

  .scan-checkbox {
    accent-color: #8b5cf6;
    cursor: pointer;
  }

  :global(.icon-gold) {
    color: #dfc28d;
  }

  .badge-official-mini {
    font-size: 8.5px;
    font-weight: 800;
    padding: 1px 4px;
    border-radius: 3px;
    background: rgba(201, 170, 115, 0.2);
    color: #dfc28d;
    border: 1px solid rgba(201, 170, 115, 0.4);
    letter-spacing: 0.06em;
  }

  /* Upload dropzone */
  .upload-zone {
    position: relative;
    border: 1px dashed #70518d;
    border-radius: 12px;
    padding: 35px 20px;
    display: flex;
    align-items: center;
    flex-direction: column;
    gap: 12px;
    background: #1b1424;
    cursor: pointer;
    text-align: center;
    transition: all 0.2s ease;
  }

  .upload-zone:hover {
    border-color: #a855f7;
    background: #20172b;
  }

  .upload-zone > span {
    font-size: 30px;
    color: var(--purple);
  }

  .upload-zone strong {
    font-size: 14px;
    color: #f1f5f9;
  }

  .upload-zone small {
    font-size: 11px;
    color: var(--muted);
  }

  .upload-zone input {
    position: absolute;
    inset: 0;
    width: 100%;
    height: 100%;
    opacity: 0;
    cursor: pointer;
  }

  .upload-zone:focus-within {
    outline: 2px solid var(--purple);
    outline-offset: 4px;
  }

  .upload-zone:has(input:disabled) {
    opacity: 0.55;
  }

  .upload-zone .file-choice {
    font-size: 12px;
    font-weight: 650;
    padding: 9px 16px;
    border-radius: 8px;
    background: #352643;
    border: 1px solid #684781;
    color: #e9d5ff;
  }

  /* Progress */
  .progress {
    height: 8px;
    background: #20172e;
    border-radius: 999px;
    position: relative;
    overflow: hidden;
  }

  .progress > span {
    display: block;
    height: 100%;
    background: linear-gradient(90deg, #9333ea, #c084fc);
    transition: width 0.2s ease;
  }

  .chapter-origin-panel {
    border: 1px solid rgba(223, 194, 141, 0.24);
    border-radius: 10px;
    background: rgba(223, 194, 141, 0.06);
  }

  .chapter-origin-panel summary {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 12px;
    padding: 11px 14px;
    cursor: pointer;
    color: #dce2ee;
    font-size: 12px;
  }

  .chapter-origin-panel summary strong {
    color: #f1d59d;
  }

  .chapter-origin-content {
    padding: 0 14px 13px;
    color: #c5ccda;
    font-size: 12px;
  }

  .chapter-origin-content dl {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 8px 16px;
    margin: 0;
  }

  .chapter-origin-content dl > div {
    min-width: 0;
  }

  .chapter-origin-content dt {
    color: #8490a5;
    font-size: 10px;
    font-weight: 750;
    letter-spacing: 0.04em;
    text-transform: uppercase;
  }

  .chapter-origin-content dd {
    margin: 2px 0 0;
    overflow-wrap: anywhere;
  }

  .chapter-origin-content code {
    color: #b6bfd2;
    font-size: 11px;
  }

  .chapter-origin-content a {
    display: inline-flex;
    margin-top: 11px;
    color: #dfc28d;
    font-size: 11px;
    font-weight: 700;
  }

  .chapter-origin-content p {
    margin: 10px 0 0;
    color: #98a2b8;
  }

  @media (max-width: 620px) {
    .chapter-origin-content dl {
      grid-template-columns: 1fr;
    }
  }

  /* Pages gallery */
  .empty-pages-state {
    padding: 48px 24px;
    text-align: center;
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 10px;
  }

  :global(.empty-icon) {
    color: #3b2a52;
  }

  .empty-pages-state h3 {
    margin: 0;
    font-size: 16px;
    color: #cbd5e1;
  }

  .page-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(130px, 1fr));
    gap: 16px;
  }

  .page-tile {
    background: #0e0c14;
    border: 1px solid #302538;
    border-radius: 8px;
    overflow: hidden;
    display: flex;
    flex-direction: column;
    transition: border-color 0.15s ease;
  }

  .page-tile:hover {
    border-color: #553e68;
  }

  .page-tile > img {
    width: 100%;
    height: 180px;
    object-fit: contain;
    background: #18131e;
  }

  .page-tile > div {
    padding: 9px;
    display: flex;
    gap: 8px;
    align-items: center;
  }

  .page-tile strong {
    color: var(--gold);
    font-size: 12px;
  }

  .page-tile span {
    overflow: hidden;
    white-space: nowrap;
    text-overflow: ellipsis;
    font-size: 9px;
    color: var(--muted);
  }

  .page-controls {
    display: flex;
    align-items: center;
    gap: 4px;
    border-top: 1px solid #1f1826;
    background: #0a080f;
  }

  .page-controls button {
    background: #27202e;
    border: 0;
    padding: 6px;
    font-size: 10px;
    border-radius: 4px;
    color: #cbd5e1;
    cursor: pointer;
    transition: background 0.15s ease;
  }

  .page-controls button:hover:not(:disabled) {
    background: #3c2a4f;
    color: #ffffff;
  }

  .page-controls button:last-child {
    margin-left: auto;
  }

  .upload-live-metrics-card {
    background: rgba(223, 194, 141, 0.04);
    border: 1px solid rgba(223, 194, 141, 0.2);
    border-radius: 10px;
    padding: 14px 16px;
    margin: 18px 0;
    display: flex;
    flex-direction: column;
    gap: 8px;
  }

  .metrics-header-row {
    display: flex;
    justify-content: space-between;
    align-items: center;
    font-size: 13px;
    flex-wrap: wrap;
    gap: 8px;
  }

  .metrics-title {
    color: #e2e8f0;
  }

  .metrics-title strong {
    color: #dfc28d;
  }

  .metrics-chips {
    display: flex;
    align-items: center;
    gap: 6px;
  }

  .metric-chip {
    font-size: 11px;
    font-weight: 700;
    padding: 2px 8px;
    border-radius: 6px;
    font-variant-numeric: tabular-nums;
  }

  .metric-chip.speed {
    background: rgba(16, 185, 129, 0.15);
    color: #34d399;
    border: 1px solid rgba(16, 185, 129, 0.3);
  }

  .metric-chip.percent {
    background: rgba(223, 194, 141, 0.15);
    color: #dfc28d;
    border: 1px solid rgba(223, 194, 141, 0.3);
  }

  .cooldown-alert {
    display: flex;
    align-items: center;
    gap: 8px;
    background: rgba(245, 158, 11, 0.12);
    border: 1px solid rgba(245, 158, 11, 0.3);
    color: #fbbf24;
    padding: 6px 12px;
    border-radius: 6px;
    font-size: 11.5px;
    margin-top: 4px;
  }

  .cooldown-alert.transient-alert {
    background: rgba(59, 130, 246, 0.12);
    border: 1px solid rgba(59, 130, 246, 0.3);
    color: #60a5fa;
  }

/* src/routes/admin/rankings/+page.svelte */
.admin-page-container {
    max-width: 1100px;
    margin: 0 auto;
    padding: 24px 20px 80px;
  }

  .admin-page-header {
    display: flex;
    align-items: center;
    gap: 16px;
    margin-bottom: 24px;
  }

  .header-icon-wrap {
    width: 52px;
    height: 52px;
    border-radius: 12px;
    background: linear-gradient(135deg, rgba(168, 85, 247, 0.2), rgba(126, 34, 206, 0.3));
    border: 1px solid rgba(168, 85, 247, 0.4);
    display: flex;
    align-items: center;
    justify-content: center;
    color: #c084fc;
    flex-shrink: 0;
  }

  .admin-title {
    font-size: 24px;
    font-weight: 900;
    color: #f8fafc;
    margin: 0 0 4px;
  }

  .admin-subtitle {
    font-size: 13.5px;
    color: #94a3b8;
    margin: 0;
    line-height: 1.4;
  }

  /* Status Banner */
  .status-banner {
    display: flex;
    align-items: center;
    gap: 10px;
    padding: 12px 16px;
    border-radius: 10px;
    margin-bottom: 20px;
    font-size: 13.5px;
    font-weight: 600;
  }

  .status-banner.success {
    background: rgba(34, 197, 94, 0.15);
    border: 1px solid rgba(34, 197, 94, 0.4);
    color: #4ade80;
  }

  .status-banner.error {
    background: rgba(239, 68, 68, 0.15);
    border: 1px solid rgba(239, 68, 68, 0.4);
    color: #f87171;
  }

  .btn-dismiss-alert {
    margin-left: auto;
    background: transparent;
    border: none;
    color: inherit;
    cursor: pointer;
    opacity: 0.8;
  }

  /* Metrics Grid */
  .metrics-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
    gap: 16px;
    margin-bottom: 24px;
  }

  .metric-card {
    background: linear-gradient(135deg, rgba(20, 10, 36, 0.95), rgba(14, 8, 26, 0.98));
    border: 1px solid rgba(255, 255, 255, 0.08);
    border-radius: 14px;
    padding: 18px 20px;
    box-shadow: 0 6px 20px rgba(0, 0, 0, 0.35);
  }

  .metric-card-top {
    display: flex;
    align-items: center;
    gap: 8px;
    margin-bottom: 8px;
  }

  .metric-badge-live {
    display: inline-flex;
    align-items: center;
    gap: 5px;
    font-size: 10px;
    font-weight: 800;
    background: rgba(34, 197, 94, 0.18);
    color: #4ade80;
    border: 1px solid rgba(34, 197, 94, 0.4);
    padding: 2px 8px;
    border-radius: 9999px;
  }

  .live-dot {
    width: 5px;
    height: 5px;
    border-radius: 50%;
    background: #4ade80;
    box-shadow: 0 0 6px #4ade80;
  }

  .metric-label {
    font-size: 12px;
    font-weight: 700;
    color: #64748b;
    text-transform: uppercase;
    letter-spacing: 0.5px;
  }

  .card-icon-purple {
    color: #c084fc;
  }

  .card-icon-green {
    color: #4ade80;
  }

  .card-icon-red {
    color: #f87171;
  }

  .metric-main-value {
