    justify-content: flex-end;
    gap: 8px;
  }

  /* List column */
  .list-column {
    display: flex;
    flex-direction: column;
    gap: 18px;
  }

  .search-bar-wrap {
    position: relative;
    display: flex;
    align-items: center;
  }

  :global(.search-icon) {
    position: absolute;
    left: 14px;
    color: #64748b;
    pointer-events: none;
  }

  .search-input {
    width: 100%;
    background: #110d1a;
    border: 1px solid #231b31;
    border-radius: 10px;
    padding: 11px 40px 11px 40px;
    color: #f8fafc;
