  /* Modals */
  .modal-backdrop {
    position: fixed;
    inset: 0;
    background: rgba(0, 0, 0, 0.75);
    backdrop-filter: blur(6px);
    z-index: 1000;
  }
  .modal-dialog {
    position: fixed;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
    width: min(500px, calc(100vw - 32px));
    background: #111420;
    border: 1px solid rgba(255, 255, 255, 0.12);
    border-radius: 16px;
    padding: 24px;
    z-index: 1001;
    box-shadow: 0 20px 50px rgba(0, 0, 0, 0.8);
    display: flex;
    flex-direction: column;
    gap: 16px;
  }
  .modal-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
  }
  .modal-header h3 {
    margin: 0;
    font-size: 17px;
    font-weight: 750;
    color: #f8fafc;
  }
  .btn-close {
    background: transparent;
    border: none;
    color: #64748b;
    cursor: pointer;
  }
  .btn-close:hover {
    color: #f1f5f9;
  }
  .modal-desc {
    font-size: 13px;
    color: #94a3b8;
    margin: 0 0 12px 0;
  }
  .modal-form {
    display: flex;
    flex-direction: column;
    gap: 14px;
  }
  .form-group {
    display: flex;
    flex-direction: column;
    gap: 6px;
  }
  .form-group label {
    font-size: 12px;
    font-weight: 650;
    color: #cbd5e1;
  }
  .form-group textarea {
    background: #0d101a;
    border: 1px solid rgba(255, 255, 255, 0.1);
    border-radius: 8px;
    padding: 10px 12px;
    color: #f1f5f9;
    font-size: 13px;
    resize: vertical;
  }
  .modal-actions {
    display: flex;
    align-items: center;
    justify-content: flex-end;
    gap: 8px;
    margin-top: 8px;
  }
  .btn-secondary {
    padding: 8px 16px;
    border-radius: 8px;
    background: rgba(255, 255, 255, 0.05);
    border: 1px solid rgba(255, 255, 255, 0.1);
    color: #cbd5e1;
    font-size: 13px;
    font-weight: 650;
    cursor: pointer;
  }
  .btn-primary {
    padding: 8px 18px;
    border-radius: 8px;
    background: #dfc28d;
    border: 1px solid #dfc28d;
    color: #0b0e14;
    font-size: 13px;
    font-weight: 750;
    cursor: pointer;
  }
  .btn-danger-solid {
    padding: 8px 18px;
    border-radius: 8px;
    background: #ef4444;
    border: 1px solid #ef4444;
    color: #ffffff;
    font-size: 13px;
    font-weight: 750;
    cursor: pointer;
  }

