    border: 1px dashed rgba(245, 158, 11, 0.4);
    border-radius: 12px;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    gap: 8px;
    color: #fde68a;
    font-size: 13px;
    font-weight: 600;
  }

  /* Paginated View */
  .paginated-view {
    position: relative;
    width: 100%;
    height: 100%;
    display: flex;
    align-items: center;
    justify-content: center;
  }

  .page-nav-zone {
    position: absolute;
    top: 0;
    bottom: 0;
    width: 30%;
    background: transparent;
    border: none;
    cursor: pointer;
    z-index: 5;
  }

  .page-nav-zone.prev {
    left: 0;
  }

  .page-nav-zone.next {
    right: 0;
  }

  .single-page-wrapper {
    max-width: 90vw;
    max-height: 85vh;
    display: flex;
    align-items: center;
    justify-content: center;
    z-index: 2;
  }

  .offline-single-img {
    max-width: 100%;
    max-height: 85vh;
    object-fit: contain;
    box-shadow: 0 8px 32px rgba(0, 0, 0, 0.8);
    border-radius: 4px;
    user-select: none;
  }

  /* ----------------------------------------------------
     OFFLINE READER FOOTER
  ---------------------------------------------------- */
  .offline-reader-footer {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 10px 18px;
    background: rgba(11, 13, 23, 0.95);
    border-top: 1px solid rgba(255, 255, 255, 0.1);
    z-index: 10;
  }

  .btn-footer-step {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    padding: 6px 14px;
    border-radius: 8px;
    background: rgba(255, 255, 255, 0.08);
    border: 1px solid rgba(255, 255, 255, 0.12);
    color: #eceaf1;
    font-size: 12px;
    font-weight: 600;
    cursor: pointer;
    transition: background 0.2s ease;
  }

  .btn-footer-step:disabled {
    opacity: 0.35;
    cursor: not-allowed;
  }

  .btn-footer-step:not(:disabled):hover {
    background: rgba(181, 154, 245, 0.2);
    border-color: rgba(181, 154, 245, 0.4);
    color: #f2f0f7;
  }

  .footer-center-tag {
    font-size: 11px;
    color: #9d99ab;
  }

  /* ----------------------------------------------------
     TOAST FLOATING
  ---------------------------------------------------- */
  .toast-floating {
    position: fixed;
    bottom: 24px;
    right: 24px;
    z-index: 9999;
    padding: 12px 20px;
    border-radius: 12px;
    font-size: 13px;
    font-weight: 600;
    box-shadow: 0 8px 32px rgba(0, 0, 0, 0.7);
    animation: toastSlideUp 0.3s cubic-bezier(0.16, 1, 0.3, 1);
  }

  .toast-floating.success {
    background: #064e3b;
    border: 1px solid #10b981;
    color: #ecfdf5;
  }

  .toast-floating.info {
    background: #1e1b4b;
    border: 1px solid #818cf8;
    color: #e0e7ff;
  }

  .toast-floating.error {
    background: #7f1d1d;
    border: 1px solid #ef4444;
    color: #fef2f2;
  }

  @keyframes toastSlideUp {
    from {
      transform: translateY(20px);
      opacity: 0;
    }
    to {
      transform: translateY(0);
      opacity: 1;
    }
  }

  /* ----------------------------------------------------
     LOADING STATE
  ---------------------------------------------------- */
  .loading-state {
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    gap: 16px;
    padding: 80px 20px;
    color: #9d99ab;
    font-size: 14px;
  }

  .spinner {
    width: 36px;
    height: 36px;
    border: 3px solid rgba(181, 154, 245, 0.2);
    border-top-color: #b59af5;
    border-radius: 50%;
    animation: spin 0.8s linear infinite;
  }

  @keyframes spin {
    to {
      transform: rotate(360deg);
    }
  }

