  /* Categories Navigation Bar with Mobile Indicators */
  .categories-nav-wrapper {
    position: relative;
    width: 100%;
    margin-bottom: 0.5rem;
    overflow: hidden;
  }

  .categories-bar {
    display: flex;
    gap: 0.5rem;
    border-bottom: 1px solid rgba(255, 255, 255, 0.08);
    overflow-x: auto;
    padding-bottom: 0.5rem;
    scroll-behavior: smooth;
    -webkit-overflow-scrolling: touch;
    scrollbar-width: none;
  }

  .categories-bar::-webkit-scrollbar {
    display: none;
  }

  .cat-scroll-arrow {
    display: none;
    position: absolute;
    top: calc(50% - 4px);
    transform: translateY(-50%);
    width: 32px;
    height: 32px;
    border-radius: 50%;
    background: rgba(15, 18, 29, 0.95);
    border: 1px solid rgba(139, 92, 246, 0.45);
    color: #c4b5fd;
    align-items: center;
    justify-content: center;
    cursor: pointer;
    z-index: 10;
    box-shadow: 0 4px 14px rgba(0, 0, 0, 0.7);
    opacity: 0;
    pointer-events: none;
    transition: opacity 0.2s ease, transform 0.15s ease, background 0.2s ease;
  }

  .cat-scroll-arrow.left {
    left: 4px;
  }

  .cat-scroll-arrow.right {
    right: 4px;
  }

  .cat-scroll-arrow.visible {
    opacity: 1;
    pointer-events: auto;
  }

  .cat-scroll-arrow:active {
    transform: translateY(-50%) scale(0.92);
  }

  .cat-scroll-arrow:hover {
    background: rgba(139, 92, 246, 0.25);
    color: #ffffff;
  }

  .cat-edge-fade {
    display: none;
    position: absolute;
    top: 0;
    bottom: 0;
    width: 36px;
    pointer-events: none;
    z-index: 5;
    opacity: 0;
    transition: opacity 0.2s ease;
  }

  .cat-edge-fade.left {
    left: 0;
    background: linear-gradient(to right, #0b0e17 30%, transparent);
  }

  .cat-edge-fade.right {
    right: 0;
    background: linear-gradient(to left, #0b0e17 30%, transparent);
  }

  .cat-edge-fade.visible {
    opacity: 1;
  }

  .mobile-swipe-hint {
    display: none;
    align-items: center;
    justify-content: center;
    gap: 8px;
    font-size: 0.73rem;
    font-weight: 600;
    color: #a78bfa;
    margin: 0 0 1.25rem;
    opacity: 0.9;
    letter-spacing: 0.02em;
  }

  .mobile-swipe-hint .swipe-arrow {
    font-size: 0.95rem;
    color: #c4b5fd;
    animation: hintNudge 1.8s ease-in-out infinite;
  }

  @keyframes hintNudge {
    0%, 100% { transform: translateX(0); }
    50% { transform: translateX(3px); }
  }

  .cat-btn {
    display: inline-flex;
    align-items: center;
    gap: 0.5rem;
    padding: 0.75rem 1.25rem;
    background: none;
    border: none;
    border-bottom: 2px solid transparent;
    color: #94a3b8;
    font-size: 0.92rem;
    font-weight: 600;
    cursor: pointer;
    white-space: nowrap;
    transition: all 0.2s ease;
  }

  .cat-btn:hover {
    color: #ffffff;
  }

  .cat-btn.active {
    color: #c4b5fd;
    border-bottom-color: #a78bfa;
  }

  .cat-count {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    padding: 0.15rem 0.55rem;
    border-radius: 9999px;
