  @media (max-width: 1200px) {
    .items-grid {
      grid-template-columns: repeat(3, 1fr);
    }
  }

  @media (max-width: 900px) {
    .shop-hero {
      grid-template-columns: 1fr;
      padding: 2rem 1.5rem;
    }

    .hero-preview-box {
      width: 100%;
    }

    .modal-grid {
      grid-template-columns: 1fr;
    }

    .modal-stage-col {
      border-right: none;
      border-bottom: 1px solid rgba(255, 255, 255, 0.08);
      padding: 2rem 1.5rem;
    }

    .modal-details-col {
      padding: 2rem 1.5rem;
    }
  }

  @media (max-width: 768px) {
    .cat-scroll-arrow {
      display: flex;
    }

    .cat-edge-fade {
      display: block;
    }

    .mobile-swipe-hint {
      display: flex;
    }

    .categories-bar {
      padding-left: 14px;
      padding-right: 14px;
      scroll-padding: 0 36px;
    }

    .cat-btn {
      padding: 0.65rem 1rem;
      font-size: 0.85rem;
    }

    .shop-page {
      padding: 1.5rem 1rem 4rem;
    }

    .items-grid {
      grid-template-columns: repeat(2, 1fr);
      gap: 1rem;
    }

    .controls-bar {
      flex-direction: column;
      align-items: flex-start;
      gap: 0.85rem;
      padding: 0.75rem 1rem;
    }

    .rarity-filters {
      width: 100%;
      overflow-x: auto;
      padding-bottom: 0.35rem;
      flex-wrap: nowrap;
    }

    .rarity-pill-group {
      flex-wrap: nowrap;
    }

    .sort-wrap {
      width: 100%;
      justify-content: space-between;
    }

    .sort-select {
      flex: 1;
      max-width: 200px;
    }
  }

  @media (max-width: 520px) {
    .items-grid {
      grid-template-columns: 1fr;
      gap: 1rem;
    }

    .balance-card {
      width: 100%;
      justify-content: space-between;
      gap: 1rem;
      padding: 0.85rem 1rem;
    }

    .shop-title {
      font-size: 1.85rem;
    }

    .modal-backdrop {
      padding: 0.75rem;
    }

    .modal-card {
      max-height: 90vh;
      overflow-y: auto;
    }

    .modal-stage-col,
    .modal-details-col {
      padding: 1.5rem 1rem;
    }
  }

