  .me-container {
    max-width: 1360px;
    margin: 0 auto;
  }

  /* Identity Strip */
  .me-header-strip {
    display: flex;
    align-items: center;
    gap: 1.5rem;
    background: #0e111d;
    border: 1px solid rgba(255, 255, 255, 0.08);
    border-radius: 18px;
    padding: 1.5rem 2rem;
    margin-bottom: 2rem;
  }

  .header-details-col {
    display: flex;
    flex-direction: column;
    gap: 0.35rem;
  }

  .title-row {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    flex-wrap: wrap;
  }

  .me-display-name {
    font-family: 'Manrope', -apple-system, BlinkMacSystemFont, sans-serif;
    font-size: 1.6rem;
    font-weight: 800;
    color: #ffffff;
    margin: 0;
  }

  .level-pill {
    display: inline-flex;
    align-items: center;
    gap: 0.35rem;
    padding: 0.2rem 0.6rem;
    background: rgba(139, 92, 246, 0.15);
    border: 1px solid rgba(139, 92, 246, 0.3);
    border-radius: 9999px;
    font-size: 0.75rem;
    font-weight: 700;
    color: #c4b5fd;
  }

  .cosmetic-title {
    padding: 0.2rem 0.6rem;
    background: rgba(223, 194, 141, 0.15);
    border: 1px solid rgba(223, 194, 141, 0.4);
    border-radius: 9999px;
    font-size: 0.75rem;
    font-weight: 700;
    color: #dfc28d;
  }

  .meta-row {
    display: flex;
    align-items: center;
    gap: 0.6rem;
    font-size: 0.85rem;
    color: #94a3b8;
  }

  .xp-chip {
    display: inline-flex;
    align-items: center;
    gap: 0.3rem;
    color: #dfc28d;
    font-weight: 700;
  }

  .public-link {
    color: #c4b5fd;
    text-decoration: none;
    transition: color 0.2s ease;
  }

  .public-link:hover {
    color: #ffffff;
  }

  /* Layout */
  .me-layout {
    display: grid;
    grid-template-columns: 240px 1fr;
    gap: 2rem;
  }

  .me-layout > * {
    min-width: 0;
  }

  .me-nav-sidebar {
    display: flex;
    flex-direction: column;
    gap: 0.35rem;
  }

  .me-nav-item {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    padding: 0.75rem 1rem;
    border-radius: 12px;
    background: none;
    border: none;
    color: #94a3b8;
    font-size: 0.9rem;
    font-weight: 600;
    cursor: pointer;
    text-align: left;
    transition: all 0.2s ease;
  }

  .me-nav-item:hover {
    background: rgba(255, 255, 255, 0.05);
    color: #ffffff;
  }

  .me-nav-item.active {
    background: rgba(139, 92, 246, 0.18);
    color: #ffffff;
    font-weight: 700;
  }

  .count-badge {
    margin-left: auto;
    padding: 0.15rem 0.45rem;
    background: rgba(255, 255, 255, 0.08);
    border-radius: 9999px;
    font-size: 0.72rem;
  }

  .count-badge.highlight {
    background: #8b5cf6;
    color: #ffffff;
  }

  .nav-separator {
    height: 1px;
    background: rgba(255, 255, 255, 0.08);
    margin: 0.75rem 0;
  }

