  .me-content-pane {
    background: #0e111d;
    border: 1px solid rgba(255, 255, 255, 0.08);
    border-radius: 20px;
    padding: 2rem;
  }

  .pane-title {
    font-family: 'Manrope', -apple-system, BlinkMacSystemFont, sans-serif;
    font-size: 1.4rem;
    font-weight: 800;
    color: #ffffff;
    margin: 0 0 1.5rem;
  }

  .sub-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    margin-bottom: 1.5rem;
  }

  .overview-stats-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
    gap: 1rem;
    margin-bottom: 2rem;
  }

  .ov-card {
    background: rgba(255, 255, 255, 0.03);
    border: 1px solid rgba(255, 255, 255, 0.06);
    border-radius: 12px;
    padding: 1.25rem;
    display: flex;
    flex-direction: column;
    gap: 0.25rem;
  }

  .ov-num {
    font-size: 1.5rem;
    font-weight: 800;
    color: #ffffff;
  }

  .ov-lbl {
    font-size: 0.8rem;
    color: #94a3b8;
  }

  .filter-pills {
    display: flex;
    gap: 0.4rem;
  }

  .pill-btn {
    padding: 0.35rem 0.8rem;
    background: rgba(255, 255, 255, 0.05);
    border: 1px solid rgba(255, 255, 255, 0.08);
    border-radius: 8px;
    color: #94a3b8;
    font-size: 0.8rem;
    font-weight: 600;
    cursor: pointer;
  }

  .pill-btn.active {
    background: rgba(139, 92, 246, 0.2);
    border-color: #8b5cf6;
    color: #ffffff;
  }

  .works-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(190px, 1fr));
    gap: 1.25rem;
  }

  /* History list */
  .history-item-row {
    display: flex;
    align-items: center;
    gap: 1rem;
    padding: 0.75rem 1rem;
    background: rgba(255, 255, 255, 0.03);
    border-radius: 10px;
    text-decoration: none;
    color: inherit;
    transition: background 0.2s ease;
    margin-bottom: 0.5rem;
  }

  .history-item-row:hover {
    background: rgba(255, 255, 255, 0.06);
  }

  .h-mini-cover {
    width: 38px;
    height: 52px;
    object-fit: cover;
    border-radius: 6px;
  }

  .h-meta {
    display: flex;
    flex-direction: column;
    flex: 1;
  }

  .h-work {
    font-weight: 700;
    color: #ffffff;
  }

  .h-ch {
    font-size: 0.8rem;
    color: #94a3b8;
  }

  .h-time {
    font-size: 0.78rem;
    color: #64748b;
  }

  /* Achievements Pane & Catalog */
  .achievements-pane {
    display: flex;
    flex-direction: column;
    gap: 1.25rem;
  }

  .ach-header-block {
    background: rgba(13, 16, 26, 0.7);
    border: 1px solid rgba(255, 255, 255, 0.08);
    border-radius: 14px;
    padding: 1.25rem 1.5rem;
    display: flex;
    flex-direction: column;
    gap: 1rem;
    backdrop-filter: blur(12px);
  }

  .ach-header-title-row {
    display: flex;
    justify-content: space-between;
    align-items: center;
    gap: 1rem;
    flex-wrap: wrap;
  }

  .ach-header-sub {
    font-size: 0.85rem;
    color: #94a3b8;
    margin: 0.25rem 0 0;
  }

  .ach-header-sub strong {
    color: #dfc28d;
  }

  .ach-progress-pill {
    position: relative;
    width: 140px;
    height: 24px;
    background: rgba(0, 0, 0, 0.4);
    border: 1px solid rgba(255, 255, 255, 0.1);
    border-radius: 12px;
    overflow: hidden;
    display: flex;
    align-items: center;
    justify-content: center;
  }

  .ach-progress-fill {
    position: absolute;
    left: 0;
    top: 0;
    bottom: 0;
    background: linear-gradient(90deg, #8b5cf6, #c084fc);
    border-radius: 12px;
    transition: width 0.4s ease;
  }

  .ach-progress-num {
    position: relative;
    z-index: 2;
    font-size: 0.72rem;
    font-weight: 800;
    color: #ffffff;
    text-shadow: 0 1px 2px rgba(0, 0, 0, 0.8);
