  .ach-rarity-breakdown {
    display: flex;
    gap: 0.5rem;
    flex-wrap: wrap;
    padding-top: 0.5rem;
    border-top: 1px solid rgba(255, 255, 255, 0.05);
  }

  .rarity-stat-chip {
    display: inline-flex;
    align-items: center;
    gap: 0.4rem;
    padding: 0.35rem 0.65rem;
    border-radius: 8px;
    background: rgba(255, 255, 255, 0.03);
    border: 1px solid rgba(255, 255, 255, 0.06);
    font-size: 0.72rem;
  }

  .r-dot {
    width: 6px;
    height: 6px;
    border-radius: 50%;
  }

  .rarity-comum .r-dot { background: #94a3b8; }
  .rarity-incomum .r-dot { background: #34d399; }
  .rarity-rara .r-dot { background: #60a5fa; }
  .rarity-epica .r-dot { background: #c084fc; }
  .rarity-lendaria .r-dot { background: #fbbf24; }
  .rarity-mitica .r-dot { background: #f43f5e; box-shadow: 0 0 6px #f43f5e; }

  .r-name {
    color: #cbd5e1;
    font-weight: 600;
  }

  .r-count {
    color: #8c899e;
    font-weight: 700;
  }

  /* Toolbar */
  .ach-toolbar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    gap: 1rem;
    flex-wrap: wrap;
  }

  .ach-status-chips {
    display: flex;
    gap: 0.4rem;
    flex-wrap: wrap;
  }

  .ach-tab-chip {
    padding: 0.45rem 0.85rem;
    border-radius: 8px;
    background: rgba(255, 255, 255, 0.03);
    border: 1px solid rgba(255, 255, 255, 0.07);
    color: #94a3b8;
    font-size: 0.76rem;
    font-weight: 600;
    cursor: pointer;
    transition: all 0.2s ease;
  }

  .ach-tab-chip:hover {
    background: rgba(255, 255, 255, 0.06);
    color: #ffffff;
  }

  .ach-tab-chip.active {
    background: rgba(139, 92, 246, 0.18);
    border-color: rgba(139, 92, 246, 0.45);
    color: #ffffff;
  }

  .ach-category-select-wrap {
    min-width: 180px;
  }

  .ach-category-select {
    width: 100%;
    padding: 0.45rem 0.85rem;
    border-radius: 8px;
    background: rgba(13, 16, 26, 0.8);
    border: 1px solid rgba(255, 255, 255, 0.08);
    color: #cbd5e1;
    font-size: 0.78rem;
    outline: none;
    cursor: pointer;
  }

  .ach-category-select:focus {
    border-color: #8b5cf6;
  }

  /* Cards Grid */
  .achievements-catalog-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(310px, 1fr));
    gap: 1rem;
  }

  .ach-catalog-card {
    display: flex;
    gap: 1rem;
    padding: 1.1rem;
    background: rgba(13, 16, 26, 0.55);
    border: 1px solid rgba(255, 255, 255, 0.05);
    border-radius: 14px;
    opacity: 0.65;
    transition: all 0.2s ease;
    backdrop-filter: blur(8px);
  }

  .ach-catalog-card:hover {
    opacity: 0.85;
    border-color: rgba(255, 255, 255, 0.12);
    transform: translateY(-2px);
  }

  .ach-catalog-card.unlocked {
    opacity: 1;
    background: rgba(18, 22, 34, 0.85);
  }

