  .empty-title {
    font-size: 1.35rem;
    font-weight: 700;
    color: #f1f5f9;
    margin: 0 0 0.6rem;
  }

  .empty-description {
    font-size: 0.92rem;
    color: #94a3b8;
    max-width: 480px;
    line-height: 1.6;
    margin: 0 0 1.75rem;
  }

  .empty-actions {
