/* Ambient Cinematic Backdrop */
  .work-backdrop {
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    height: 520px;
    overflow: hidden;
    pointer-events: none;
    z-index: 0;
    opacity: 0.35;
    -webkit-mask-image: linear-gradient(to bottom, rgba(0, 0, 0, 0.9) 0%, rgba(0, 0, 0, 0.4) 60%, transparent 100%);
    mask-image: linear-gradient(to bottom, rgba(0, 0, 0, 0.9) 0%, rgba(0, 0, 0, 0.4) 60%, transparent 100%);
  }

  .backdrop-img {
    width: 100%;
    height: 100%;
    object-fit: cover;
    object-position: center 20%;
    filter: blur(60px) brightness(0.35) saturate(1.3);
    transform: scale(1.2);
  }

  .backdrop-gradient {
    position: absolute;
    inset: 0;
    background: linear-gradient(
      to bottom,
      rgba(13, 10, 28, 0.35) 0%,
      rgba(7, 6, 17, 0.55) 60%,
      transparent 100%
    );
  }

  /* Page Root */
  .work-page-root {
    position: relative;
    max-width: 1220px;
    margin: 0 auto;
    padding-top: 1.25rem;
  }

  /* Breadcrumb */
  .work-breadcrumb {
    display: flex;
    align-items: center;
    gap: 8px;
    font-size: 0.88rem;
    color: rgba(226, 232, 240, 0.6);
    margin-bottom: 24px;
    flex-wrap: wrap;
  }

  .work-breadcrumb a {
    color: rgba(226, 232, 240, 0.7);
    text-decoration: none;
    transition: color 0.15s;
  }

  .work-breadcrumb a:hover {
    color: #a78bfa;
  }

  .crumb-separator {
    color: rgba(181, 154, 245, 0.3);
  }

  .crumb-current {
    color: #f1f5f9;
    font-weight: 500;
  }

  /* Hero Section */
  .work-hero-section {
    display: grid;
    grid-template-columns: 280px 1fr;
    gap: 36px;
    align-items: start;
    margin-bottom: 28px;
  }

  /* Cover Column */
  .work-cover-column {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 12px;
    position: sticky;
    top: 90px;
    max-width: 280px;
