    position: relative;
    border-radius: 16px;
    overflow: hidden;
    box-shadow: 0 16px 36px rgba(0, 0, 0, 0.55), 0 0 0 1px rgba(181, 154, 245, 0.18);
    background: #090b14;
    aspect-ratio: 280 / 392;
    width: 100%;
  }

  .work-cover-img {
    width: 100%;
    height: 100%;
    object-fit: cover;
    display: block;
    transition: transform 0.3s ease;
  }

  .work-cover-wrapper:hover .work-cover-img {
    transform: scale(1.025);
  }

