  /* Interactions Row: Height 42px reference, balanced and elegant */
  .work-hero-actions {
    display: flex;
    align-items: center;
    gap: 12px;
    flex-wrap: wrap;
    margin: 4px 0 12px;
  }

  .actions-buttons-cluster {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
  }

  .btn-action-control {
    height: 42px;
    min-height: 42px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 8px;
    padding: 0 14px;
    font-size: 0.88rem;
    font-weight: 600;
    color: #cbd5e1;
    background: rgba(255, 255, 255, 0.04);
    border: 1px solid rgba(181, 154, 245, 0.16);
    border-radius: 10px;
    cursor: pointer;
    transition: all 0.2s ease;
    white-space: nowrap;
    text-decoration: none;
    box-sizing: border-box;
  }

  .btn-action-control:hover:not(:disabled) {
    background: rgba(181, 154, 245, 0.12);
    border-color: rgba(181, 154, 245, 0.35);
    color: #ffffff;
    transform: translateY(-1px);
  }

  .btn-action-control:focus-visible {
    outline: 2px solid #a78bfa;
    outline-offset: 2px;
  }

  .btn-action-control.is-active {
    color: #ffd154;
    background: rgba(255, 209, 84, 0.12);
    border-color: rgba(255, 209, 84, 0.38);
  }

  .btn-action-control.btn-like.is-active {
    color: #fb7185;
    background: rgba(244, 63, 94, 0.12);
    border-color: rgba(244, 63, 94, 0.38);
  }

  .library-dropdown-wrap {
    min-width: 190px;
    flex: 1;
    max-width: 250px;
  }

  .library-select-hero {
    width: 100%;
    height: 42px;
    min-height: 42px;
    padding: 0 14px;
    background: rgba(18, 14, 28, 0.85);
    border: 1px solid rgba(181, 154, 245, 0.18);
    border-radius: 10px;
    color: #e2e8f0;
    font-size: 0.86rem;
    font-weight: 600;
    outline: none;
    cursor: pointer;
    transition: border-color 0.2s, background 0.2s;
    box-sizing: border-box;
  }

  .library-select-hero:hover:not(:disabled) {
    border-color: rgba(181, 154, 245, 0.35);
  }

  .library-select-hero:focus {
    border-color: #a78bfa;
    box-shadow: 0 0 0 2px rgba(167, 139, 250, 0.25);
  }

  /* Inline Essential Metrics (Clean, unbloated, high-contrast) */
  .work-metrics-inline {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    margin: 6px 0 10px;
  }

  .metric-inline-item {
    display: inline-flex;
    align-items: center;
    gap: 5px;
    font-size: 0.84rem;
    color: rgba(226, 232, 240, 0.7);
  }

  .metric-inline-item strong {
    color: #f1f5f9;
    font-weight: 700;
  }

  .metric-inline-item .metric-lbl {
    color: rgba(226, 232, 240, 0.5);
    font-size: 0.78rem;
  }

  .metric-dot {
    color: rgba(181, 154, 245, 0.35);
    font-size: 0.8rem;
  }

  /* Editorial Refined Synopsis */
  .work-synopsis-card {
    background: rgba(13, 11, 24, 0.42);
    border: 1px solid rgba(181, 154, 245, 0.08);
    border-radius: 12px;
    padding: 16px 20px;
    backdrop-filter: blur(6px);
    margin-top: 4px;
    transition: border-color 0.2s ease, background 0.2s ease;
  }

  .work-synopsis-card:hover {
    border-color: rgba(181, 154, 245, 0.16);
    background: rgba(16, 13, 30, 0.52);
  }

  .synopsis-card-header {
    display: flex;
    align-items: center;
    gap: 6px;
    margin-bottom: 8px;
  }

  .synopsis-heading {
    font-size: 0.8rem;
    font-weight: 700;
    color: #a78bfa;
    text-transform: uppercase;
    letter-spacing: 0.06em;
    margin: 0;
  }

  .synopsis-body {
    display: flex;
    flex-direction: column;
  }

  .synopsis-paragraph {
    font-size: 0.96rem;
    line-height: 1.64;
    color: rgba(241, 245, 249, 0.9);
    margin: 0;
    white-space: pre-line;
    font-weight: 400;
    letter-spacing: 0.01em;
  }

  .synopsis-paragraph.clamped {
    display: -webkit-box;
    -webkit-line-clamp: 4;
    -webkit-box-orient: vertical;
    overflow: hidden;
  }

  .btn-expand-synopsis {
    display: inline-flex;
    align-items: center;
    gap: 4px;
    margin-top: 8px;
    align-self: flex-start;
    font-size: 0.82rem;
    font-weight: 600;
    color: #a78bfa;
    background: none;
    border: none;
    padding: 0;
    cursor: pointer;
    transition: color 0.15s ease;
  }

  .btn-expand-synopsis:hover {
    color: #c4b5fd;
    text-decoration: underline;
  }

  /* Notice Bar */
  .work-notice-bar {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 12px 18px;
    background: rgba(124, 58, 237, 0.2);
    border: 1px solid rgba(167, 139, 250, 0.4);
    border-radius: 12px;
    color: #f1f5f9;
    font-size: 0.9rem;
    font-weight: 500;
    margin: 20px 0;
  }

  /* Redesigned Thematic Editorial Ficha Técnica (Balanced 2 Columns on Desktop) */
  .work-specs-section {
    margin: 28px 0 38px;
  }

  .specs-section-header {
    display: flex;
    flex-direction: column;
    gap: 4px;
    margin-bottom: 20px;
    padding-bottom: 12px;
    border-bottom: 1px solid rgba(181, 154, 245, 0.1);
  }

  .specs-heading-wrap {
    display: flex;
    align-items: center;
    gap: 8px;
  }

  :global(.specs-header-icon) {
    color: #a78bfa;
  }

  .specs-main-title {
    font-size: 1.15rem;
    font-weight: 800;
    color: #f8fafc;
    margin: 0;
    letter-spacing: -0.01em;
  }

  .specs-subtext {
    font-size: 0.82rem;
    color: rgba(226, 232, 240, 0.55);
  }

  /* Single Unified Editorial Panel (True 2x2 Symmetric Grid on Desktop) */
  .specs-unified-panel {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 20px;
    background: rgba(11, 13, 24, 0.65);
    border: 1px solid rgba(181, 154, 245, 0.16);
    border-radius: 16px;
    padding: 22px;
    backdrop-filter: blur(10px);
    width: 100%;
    box-sizing: border-box;
    align-items: stretch;
  }

  /* Subpanel: Defined internal identity with symmetric equal height on rows */
  .specs-subpanel {
    display: flex;
    flex-direction: column;
    background: rgba(18, 16, 32, 0.55);
    border: 1px solid rgba(181, 154, 245, 0.12);
    border-radius: 12px;
    padding: 20px 22px;
    min-height: 0;
    height: 100%;
    box-sizing: border-box;
    transition: border-color 0.2s ease, background 0.2s ease;
  }

  .specs-subpanel:hover {
    border-color: rgba(181, 154, 245, 0.24);
    background: rgba(22, 19, 40, 0.65);
  }

  #subpanel-info {
    grid-column: 1;
    grid-row: 1;
  }

  #subpanel-credits {
    grid-column: 2;
    grid-row: 1;
  }

  #subpanel-genres {
    grid-column: 1;
    grid-row: 2;
  }

  #subpanel-aliases {
    grid-column: 2;
    grid-row: 2;
  }

  .subpanel-header {
    display: flex;
    align-items: center;
    gap: 8px;
    margin-bottom: 16px;
    padding-bottom: 10px;
    border-bottom: 1px solid rgba(181, 154, 245, 0.08);
  }

  :global(.subpanel-icon) {
    color: #a78bfa;
    flex-shrink: 0;
  }

  .subpanel-title {
    font-size: 0.88rem;
    font-weight: 700;
    color: #f1f5f9;
    text-transform: uppercase;
    letter-spacing: 0.04em;
    margin: 0;
  }

  .subpanel-count-badge {
    margin-left: auto;
    font-size: 0.72rem;
    font-weight: 700;
    color: #c4b5fd;
    background: rgba(167, 139, 250, 0.15);
    border: 1px solid rgba(167, 139, 250, 0.25);
    padding: 1px 7px;
    border-radius: 999px;
  }

  .unassigned-spec {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    min-width: 22px;
    height: 22px;
    padding: 0 6px;
    font-size: 0.82rem;
    font-weight: 700;
    color: rgba(226, 232, 240, 0.5);
    background: rgba(255, 255, 255, 0.04);
    border: 1px solid rgba(255, 255, 255, 0.08);
    border-radius: 6px;
  }

  .specs-table {
    display: flex;
    flex-direction: column;
    gap: 10px;
    margin: 0;
    flex: 1;
  }

  .specs-row {
    display: flex;
    justify-content: space-between;
    align-items: baseline;
    gap: 12px;
    padding-bottom: 8px;
    border-bottom: 1px dashed rgba(181, 154, 245, 0.08);
  }

  .specs-row:last-child {
    border-bottom: none;
    padding-bottom: 0;
  }

  .specs-row dt {
    font-size: 0.86rem;
    font-weight: 500;
    color: #94a3b8;
    margin: 0;
    white-space: nowrap;
  }

  .specs-row dd {
    font-size: 0.92rem;
    font-weight: 600;
    color: #f1f5f9;
    margin: 0;
    text-align: right;
    display: flex;
    align-items: center;
    gap: 6px;
  }

  .status-indicator-dot {
    width: 8px;
    height: 8px;
    border-radius: 50%;
    background: #34d399;
    box-shadow: 0 0 8px rgba(52, 211, 153, 0.6);
    display: inline-block;
  }

  .status-indicator-dot.is-ongoing {
    background: #60a5fa;
    box-shadow: 0 0 8px rgba(96, 165, 250, 0.6);
  }

  .age-pill {
    font-size: 0.76rem;
    font-weight: 700;
    padding: 2px 8px;
    border-radius: 6px;
    background: rgba(255, 255, 255, 0.08);
    color: #e2e8f0;
  }

  .age-pill.adult {
    background: rgba(239, 68, 68, 0.18);
    color: #fca5a5;
    border: 1px solid rgba(239, 68, 68, 0.35);
  }

  .age-pill.free {
    background: rgba(16, 185, 129, 0.15);
    color: #6ee7b7;
    border: 1px solid rgba(16, 185, 129, 0.3);
  }

  .scans-chips-wrap {
    display: flex;
    align-items: center;
    gap: 6px;
    flex-wrap: wrap;
    justify-content: flex-end;
  }

  .scan-pill-link {
    display: inline-flex;
    align-items: center;
    gap: 5px;
    font-size: 0.8rem;
    font-weight: 600;
    color: #c4b5fd;
    background: rgba(167, 139, 250, 0.12);
    border: 1px solid rgba(167, 139, 250, 0.24);
    padding: 2px 8px;
    border-radius: 6px;
    text-decoration: none;
    transition: all 0.15s ease;
  }

  .scan-pill-link:hover {
    background: rgba(167, 139, 250, 0.22);
    color: #ffffff;
  }

  .muted-spec {
    font-size: 0.84rem;
    color: rgba(226, 232, 240, 0.5);
    font-weight: 400;
  }

  /* Genres Card Body & Balanced Tags Distribution */
  .genres-card-body {
    display: flex;
    flex-direction: column;
    flex: 1;
    min-height: 0;
    justify-content: flex-start;
  }

  .genres-card-body.is-sparse {
    justify-content: center;
  }

  .genres-empty-wrap {
    display: flex;
    align-items: center;
    justify-content: center;
    flex: 1;
  }

  .editorial-tags-wrap {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: 10px;
    margin: 2px 0 0;
  }

  .editorial-tag-pill {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    min-height: 35px;
    height: 35px;
    padding: 0 15px;
    font-size: 0.85rem;
    font-weight: 600;
    line-height: 1;
    color: #e2e8f0;
    background: rgba(255, 255, 255, 0.045);
    border: 1px solid rgba(181, 154, 245, 0.15);
    border-radius: 8px;
    text-decoration: none;
    white-space: nowrap;
    width: auto;
    flex: 0 0 auto;
    box-sizing: border-box;
    transition: all 0.15s ease;
  }

  .editorial-tag-pill:hover {
    color: #ffffff;
    background: rgba(167, 139, 250, 0.2);
    border-color: rgba(167, 139, 250, 0.45);
    transform: translateY(-1px);
  }

  /* Alternative Titles List (Prominent, High Legibility) */
  .aliases-editorial-list {
    display: flex;
    flex-direction: column;
    gap: 8px;
    list-style: none;
    padding: 0;
    margin: 0;
    flex: 1;
  }

  .alias-editorial-row {
    display: flex;
    align-items: baseline;
    gap: 8px;
    padding: 6px 10px;
    background: rgba(255, 255, 255, 0.025);
    border: 1px solid rgba(181, 154, 245, 0.08);
    border-radius: 8px;
  }

  .alias-index-num {
    font-size: 0.72rem;
    font-weight: 700;
    color: #a78bfa;
    font-family: monospace;
    flex-shrink: 0;
  }

  .alias-text {
    font-size: 0.88rem;
    font-weight: 500;
    color: #f1f5f9;
    line-height: 1.45;
    word-break: break-word;
  }

  .btn-toggle-subpanel {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    margin-top: auto;
    padding-top: 12px;
    align-self: flex-start;
    font-size: 0.82rem;
    font-weight: 600;
    color: #a78bfa;
    background: none;
    border: none;
    padding-left: 0;
    padding-right: 0;
    cursor: pointer;
    transition: color 0.15s ease;
  }

  .btn-toggle-subpanel:hover {
    color: #c4b5fd;
  }

  /* Full-width aliases drawer below the 2x2 grid */
  .specs-aliases-drawer {
    grid-column: 1 / -1;
    grid-row: 3;
    background: rgba(16, 14, 30, 0.75);
    border: 1px solid rgba(181, 154, 245, 0.16);
    border-radius: 12px;
    padding: 18px 22px;
    display: flex;
    flex-direction: column;
    gap: 12px;
    animation: drawerFadeIn 0.2s ease-out;
  }

  @keyframes drawerFadeIn {
    from {
      opacity: 0;
      transform: translateY(-4px);
    }
    to {
      opacity: 1;
      transform: translateY(0);
    }
  }

  .drawer-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding-bottom: 10px;
    border-bottom: 1px solid rgba(181, 154, 245, 0.1);
  }

  .drawer-title-wrap {
    display: flex;
    align-items: center;
    gap: 8px;
  }

  :global(.drawer-icon) {
    color: #a78bfa;
    flex-shrink: 0;
  }

  .drawer-title {
    font-size: 0.84rem;
    font-weight: 700;
    color: #c4b5fd;
    text-transform: uppercase;
    letter-spacing: 0.04em;
    margin: 0;
  }

  .btn-drawer-close {
    display: inline-flex;
    align-items: center;
    gap: 4px;
    font-size: 0.78rem;
    font-weight: 600;
    color: #a78bfa;
    background: rgba(167, 139, 250, 0.1);
    border: 1px solid rgba(167, 139, 250, 0.2);
    padding: 4px 10px;
    border-radius: 6px;
    cursor: pointer;
    transition: all 0.15s ease;
  }

  .btn-drawer-close:hover {
    background: rgba(167, 139, 250, 0.2);
    color: #ffffff;
  }

  .drawer-aliases-grid {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 8px 16px;
  }

  @media (min-width: 1200px) {
    .drawer-aliases-grid {
      grid-template-columns: repeat(3, minmax(0, 1fr));
    }
  }

  .drawer-alias-item {
    display: flex;
    align-items: baseline;
    gap: 8px;
    padding: 6px 10px;
    background: rgba(255, 255, 255, 0.025);
    border: 1px solid rgba(181, 154, 245, 0.08);
    border-radius: 8px;
    min-width: 0;
  }

  .empty-spec-text {
    font-size: 0.85rem;
    color: rgba(226, 232, 240, 0.45);
    font-style: italic;
    margin: 0;
  }

  /* Chapters Section (Full Width, Reading Centered) */
  .work-chapters-section {
    width: 100%;
    min-width: 0;
    contain: layout style;
    margin-bottom: 48px;
  }

  .chapters-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    margin-bottom: 16px;
    flex-wrap: wrap;
    gap: 12px;
  }

  .chapters-title-wrap {
    display: flex;
    flex-direction: column;
    gap: 2px;
  }

  .chapters-title {
    font-size: 1.35rem;
    font-weight: 800;
    color: #f8fafc;
    margin: 0 0 4px;
    letter-spacing: -0.01em;
  }

  .chapters-subtitle {
    font-size: 0.82rem;
    color: rgba(226, 232, 240, 0.55);
    margin: 0;
  }

  .btn-read-primary {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 10px;
    min-height: 44px;
    padding: 10px 22px;
    background: linear-gradient(135deg, #7c3aed 0%, #6d28d9 100%);
    color: #ffffff;
    font-weight: 700;
    font-size: 0.95rem;
    border-radius: 12px;
    text-decoration: none;
    box-shadow: 0 8px 24px rgba(124, 58, 237, 0.35);
    transition: all 0.2s ease;
    white-space: nowrap;
    box-sizing: border-box;
  }

  .btn-read-primary:hover {
    background: linear-gradient(135deg, #8b5cf6 0%, #7c3aed 100%);
    box-shadow: 0 10px 28px rgba(124, 58, 237, 0.48);
    transform: translateY(-1px);
  }

  /* Chapters Toolbar */
  .chapters-toolbar {
    display: flex;
    gap: 10px;
    margin-bottom: 16px;
    flex-wrap: wrap;
  }

  .search-input-wrap {
    flex: 1;
    min-width: 220px;
    position: relative;
    display: flex;
    align-items: center;
  }

  :global(.search-icon) {
    position: absolute;
    left: 12px;
    color: rgba(226, 232, 240, 0.4);
    pointer-events: none;
  }

  .chapters-search-input {
    width: 100%;
    min-height: 42px;
    padding: 8px 36px 8px 36px;
    background: rgba(18, 14, 28, 0.8);
    border: 1px solid rgba(181, 154, 245, 0.16);
    border-radius: 10px;
    color: #f1f5f9;
    font-size: 0.88rem;
    outline: none;
    transition: border-color 0.2s;
  }

  .chapters-search-input:focus {
    border-color: #a78bfa;
  }

  .btn-clear-search {
    position: absolute;
    right: 10px;
    background: none;
    border: none;
    color: rgba(255, 255, 255, 0.6);
    font-size: 1.2rem;
    cursor: pointer;
    line-height: 1;
  }

  .toolbar-buttons {
    display: flex;
    gap: 8px;
  }

  .btn-toolbar {
    min-height: 42px;
    display: inline-flex;
    align-items: center;
    gap: 6px;
    padding: 8px 14px;
    background: rgba(255, 255, 255, 0.04);
    border: 1px solid rgba(181, 154, 245, 0.14);
    border-radius: 10px;
    color: #cbd5e1;
    font-size: 0.82rem;
    font-weight: 600;
    cursor: pointer;
    transition: all 0.15s;
    white-space: nowrap;
  }

  .btn-toolbar:hover {
    background: rgba(181, 154, 245, 0.12);
    color: #ffffff;
  }

  .btn-toolbar.download-batch-btn.is-busy {
    color: #fbbf24;
    background: rgba(251, 191, 36, 0.14);
    border-color: rgba(251, 191, 36, 0.35);
    cursor: pointer;
  }

  .btn-toolbar.download-batch-btn.is-busy:hover {
    color: #f87171;
    background: rgba(239, 68, 68, 0.16);
    border-color: rgba(239, 68, 68, 0.45);
  }

  .batch-cancel-x {
    display: none;
    margin-left: 2px;
  }

  .btn-toolbar.download-batch-btn.is-busy:hover .batch-spinner {
    display: none;
  }

  .btn-toolbar.download-batch-btn.is-busy:hover .batch-cancel-x {
    display: inline-block;
  }

  /* Chapter Cards */
  .chapter-list-wrap {
    display: flex;
    flex-direction: column;
    gap: 6px;
  }

  .chapter-card {
    min-height: 54px;
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 8px 14px;
    background: rgba(14, 16, 26, 0.6);
    border: 1px solid rgba(181, 154, 245, 0.1);
    border-radius: 12px;
    transition: all 0.15s ease;
  }

  .chapter-card:hover {
    background: rgba(22, 25, 40, 0.8);
    border-color: rgba(167, 139, 250, 0.25);
    transform: translateX(2px);
  }

  .chapter-card.is-read {
    opacity: 0.72;
    background: rgba(10, 11, 18, 0.4);
  }

  .chapter-card-link {
    flex: 1;
    display: flex;
    align-items: center;
    gap: 12px;
    text-decoration: none;
    min-width: 0;
  }

  .chapter-number-badge {
    min-width: 44px;
    height: 34px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    font-size: 0.85rem;
    font-weight: 800;
    color: #a78bfa;
    background: rgba(167, 139, 250, 0.12);
    border-radius: 8px;
    padding: 0 8px;
    flex-shrink: 0;
  }

  .chapter-info-col {
    display: flex;
    flex-direction: column;
    gap: 2px;
    min-width: 0;
  }

  .chapter-name-line {
    display: flex;
    align-items: center;
    gap: 8px;
