  .podium-box {
    display: flex;
    flex-direction: column;
    align-items: center;
    padding: 24px 16px 20px;
    background: linear-gradient(180deg, rgba(28, 24, 56, 0.7) 0%, rgba(15, 12, 30, 0.9) 100%);
    border-radius: 16px;
    border: 1px solid rgba(139, 92, 246, 0.2);
    text-decoration: none;
    position: relative;
    transition: transform 0.25s ease, box-shadow 0.25s ease;
  }

  .podium-box:hover {
    transform: translateY(-4px);
  }

  .silver-tier {
    border-color: rgba(148, 163, 184, 0.35);
    box-shadow: 0 8px 24px rgba(148, 163, 184, 0.08);
  }

  .gold-tier {
    background: linear-gradient(180deg, rgba(42, 32, 70, 0.85) 0%, rgba(20, 15, 42, 0.95) 100%);
    border-color: rgba(250, 204, 21, 0.4);
    box-shadow: 0 12px 36px rgba(250, 204, 21, 0.12);
    padding-top: 28px;
    padding-bottom: 24px;
  }

  .bronze-tier {
    border-color: rgba(217, 119, 6, 0.35);
    box-shadow: 0 8px 24px rgba(217, 119, 6, 0.08);
  }

  /* Desktop Olympic Positioning: 2º (col 1), 1º (col 2), 3º (col 3) */
  @media (min-width: 769px) {
    .silver-tier {
      grid-column: 1;
      grid-row: 1;
    }
    .gold-tier {
      grid-column: 2;
      grid-row: 1;
    }
    .bronze-tier {
      grid-column: 3;
      grid-row: 1;
    }
  }

  /* Cap headers for Crown and Medals */
  .podium-crown-cap,
  .podium-medal-cap {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 4px;
    margin-bottom: 12px;
    z-index: 5;
  }

  .crown-emoji,
  .medal-emoji {
    font-size: 1.8rem;
    line-height: 1;
    filter: drop-shadow(0 4px 10px rgba(0, 0, 0, 0.5));
  }

  .crown-tag {
    display: inline-flex;
    align-items: center;
    gap: 5px;
    padding: 3px 10px;
    border-radius: 999px;
    font-size: 0.72rem;
    font-weight: 800;
    letter-spacing: 0.06em;
  }

  .gold-tag {
    background: rgba(250, 204, 21, 0.18);
    border: 1px solid rgba(250, 204, 21, 0.45);
    color: #facc15;
  }

  .medal-tag {
    padding: 3px 10px;
    border-radius: 999px;
    font-size: 0.72rem;
    font-weight: 800;
    letter-spacing: 0.06em;
  }

  .silver-tag {
    background: rgba(148, 163, 184, 0.15);
    border: 1px solid rgba(148, 163, 184, 0.35);
    color: #cbd5e1;
  }

  .bronze-tag {
    background: rgba(217, 119, 6, 0.15);
    border: 1px solid rgba(217, 119, 6, 0.35);
    color: #fb923c;
  }

  /* Staged Avatar */
  .podium-avatar-stage {
    padding: 24px 14px 14px;
    display: flex;
    justify-content: center;
    align-items: center;
    position: relative;
    min-height: 104px;
  }

  .gold-stage {
    min-height: 118px;
    padding-top: 28px;
  }

  .podium-name {
    font-size: 1.05rem;
    font-weight: 700;
    color: #f8fafc;
    text-align: center;
    margin-top: 6px;
    margin-bottom: 2px;
  }

  .gold-name {
    font-size: 1.2rem;
    color: #fef08a;
    text-shadow: 0 0 14px rgba(250, 204, 21, 0.3);
  }

  .podium-handle {
    font-size: 0.78rem;
    color: #64748b;
    margin-bottom: 10px;
  }

  /* Unified Trio Row: Title | Level | Season XP */
  .podium-trio-row {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 6px;
    flex-wrap: wrap;
    margin-top: 6px;
    margin-bottom: 2px;
    width: 100%;
    max-width: 96%;
  }

  .podium-trio-badge {
    display: inline-flex;
    align-items: center;
    gap: 4px;
    font-size: 0.74rem;
    font-weight: 700;
    padding: 3px 8px;
    border-radius: 6px;
    line-height: 1.25;
    white-space: nowrap;
    transition: all 0.2s ease;
  }

  /* Gold Trio Badges (1º Lugar) */
  .gold-title {
    background: rgba(250, 204, 21, 0.15);
    border: 1px solid rgba(250, 204, 21, 0.45);
    color: #fef08a;
  }

  .gold-level {
    background: rgba(245, 158, 11, 0.18);
    border: 1px solid rgba(245, 158, 11, 0.4);
    color: #fbbf24;
  }

  .gold-xp {
    background: rgba(250, 204, 21, 0.12);
    border: 1px solid rgba(250, 204, 21, 0.35);
    color: #fef9c3;
  }

  .gold-xp strong {
    font-weight: 800;
    color: #ffffff;
  }

  .gold-xp small {
    font-size: 0.64rem;
    color: #fde047;
    font-weight: 700;
  }

  /* Silver Trio Badges (2º Lugar) */
  .silver-title {
    background: rgba(148, 163, 184, 0.14);
    border: 1px solid rgba(203, 213, 225, 0.35);
    color: #e2e8f0;
  }

  .silver-level {
    background: rgba(56, 189, 248, 0.14);
    border: 1px solid rgba(56, 189, 248, 0.35);
    color: #38bdf8;
  }

  .silver-xp {
    background: rgba(226, 232, 240, 0.1);
    border: 1px solid rgba(203, 213, 225, 0.3);
    color: #f8fafc;
  }

  .silver-xp strong {
    font-weight: 800;
    color: #ffffff;
  }

  .silver-xp small {
    font-size: 0.64rem;
    color: #cbd5e1;
    font-weight: 700;
  }

  /* Bronze Trio Badges (3º Lugar) */
  .bronze-title {
    background: rgba(217, 119, 6, 0.14);
    border: 1px solid rgba(251, 146, 60, 0.35);
    color: #fed7aa;
  }

  .bronze-level {
    background: rgba(249, 115, 22, 0.14);
    border: 1px solid rgba(249, 115, 22, 0.35);
    color: #fb923c;
  }

  .bronze-xp {
    background: rgba(217, 119, 6, 0.1);
    border: 1px solid rgba(251, 146, 60, 0.3);
    color: #ffedd5;
  }

  .bronze-xp strong {
    font-weight: 800;
    color: #ffffff;
  }

  .bronze-xp small {
    font-size: 0.64rem;
    color: #fdba74;
    font-weight: 700;
  }

  .podium-box:hover .podium-trio-badge {
    transform: translateY(-1px);
  }

  @media (prefers-reduced-motion: reduce) {
    .podium-box:hover .podium-trio-badge {
      transform: none;
    }
  }

  /* Search Bar */
  .ranking-search-bar {
    position: relative;
    margin-bottom: 28px;
  }

  .search-input-box {
    display: flex;
    align-items: center;
    gap: 10px;
    background: rgba(24, 20, 50, 0.65);
    border: 1px solid rgba(139, 92, 246, 0.25);
    border-radius: 12px;
    padding: 10px 16px;
    transition: all 0.2s;
  }

  .search-input-box:focus-within {
    border-color: rgba(167, 139, 250, 0.6);
    box-shadow: 0 0 16px rgba(139, 92, 246, 0.25);
    background: rgba(28, 22, 60, 0.85);
  }

  .search-icon {
    color: #94a3b8;
  }

  .search-input {
    flex: 1;
    background: none;
    border: none;
    color: #f8fafc;
    font-size: 0.9rem;
    outline: none;
  }

  .search-input::placeholder {
    color: #64748b;
  }

  .btn-clear-search {
    background: none;
    border: none;
    color: #94a3b8;
    cursor: pointer;
    padding: 4px;
    display: flex;
    align-items: center;
    justify-content: center;
  }

  .btn-clear-search:hover {
    color: #ffffff;
  }

  /* Search Dropdown */
  .search-dropdown-panel {
    position: absolute;
    top: calc(100% + 6px);
    left: 0;
    right: 0;
    background: rgba(20, 16, 45, 0.96);
    border: 1px solid rgba(139, 92, 246, 0.35);
    border-radius: 12px;
    box-shadow: 0 12px 32px rgba(0, 0, 0, 0.6);
    backdrop-filter: blur(14px);
    z-index: 50;
    overflow: hidden;
  }

  .dropdown-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 10px 16px;
    border-bottom: 1px solid rgba(139, 92, 246, 0.15);
    font-size: 0.78rem;
    color: #94a3b8;
  }

  .dropdown-list {
    max-height: 320px;
    overflow-y: auto;
  }

  .dropdown-item {
    display: flex;
    align-items: center;
    gap: 12px;
    padding: 10px 16px;
    border-bottom: 1px solid rgba(139, 92, 246, 0.08);
    text-decoration: none;
    color: inherit;
    transition: background 0.15s;
  }

  .dropdown-item:hover {
    background: rgba(139, 92, 246, 0.15);
  }

  .dropdown-rank {
    font-size: 0.95rem;
    font-weight: 800;
    color: #facc15;
    min-width: 38px;
  }

  .dropdown-info {
    flex: 1;
    display: flex;
    flex-direction: column;
  }

  .dropdown-info strong {
    font-size: 0.88rem;
    color: #f8fafc;
  }

  .dropdown-handle {
    font-size: 0.76rem;
    color: #64748b;
  }

  .dropdown-achievement {
    display: flex;
    align-items: center;
    gap: 6px;
  }

  .chip-title-mini {
    font-size: 0.72rem;
    font-weight: 700;
    padding: 2px 6px;
    background: rgba(139, 92, 246, 0.2);
    border: 1px solid rgba(167, 139, 250, 0.3);
    border-radius: 4px;
    color: #c4b5fd;
  }

  .chip-level-mini {
    font-size: 0.72rem;
    font-weight: 700;
    padding: 2px 5px;
    background: rgba(56, 189, 248, 0.15);
    border-radius: 4px;
    color: #38bdf8;
  }

  .dropdown-xp {
    text-align: right;
  }

  .dropdown-xp strong {
    font-size: 0.92rem;
    color: #ffffff;
  }

  .dropdown-xp small {
    display: block;
    font-size: 0.68rem;
    color: #94a3b8;
  }

  .dropdown-empty {
    padding: 20px;
    text-align: center;
    color: #94a3b8;
    font-size: 0.86rem;
  }

  /* Leaderboard Section */
  .leaderboard-section {
    margin-bottom: 40px;
  }

  .leaderboard-header-row {
    display: flex;
    justify-content: space-between;
    align-items: baseline;
    flex-wrap: wrap;
    gap: 12px;
    margin-bottom: 16px;
  }

  .leaderboard-title-group {
    display: flex;
    align-items: center;
    gap: 8px;
  }

  .leaderboard-heading {
    margin: 0;
    font-size: 1.25rem;
    font-weight: 800;
    color: #f8fafc;
  }

  .leaderboard-count {
    font-size: 0.82rem;
    color: #94a3b8;
  }

  .leaderboard-legend small {
    font-size: 0.78rem;
    color: #a78bfa;
  }

  /* Leaderboard Table (Desktop) */
  .leaderboard-card {
    background: linear-gradient(180deg, rgba(24, 20, 50, 0.7) 0%, rgba(16, 13, 34, 0.85) 100%);
    border: 1px solid rgba(139, 92, 246, 0.22);
    border-radius: 14px;
    overflow: hidden;
    box-shadow: 0 8px 30px rgba(0, 0, 0, 0.35);
  }

  .leaderboard-table {
    width: 100%;
    border-collapse: collapse;
  }

  .leaderboard-table th {
    padding: 14px 18px;
    font-size: 0.75rem;
    font-weight: 700;
    color: #94a3b8;
    text-transform: uppercase;
    letter-spacing: 0.06em;
    border-bottom: 1px solid rgba(139, 92, 246, 0.18);
    background: rgba(15, 12, 32, 0.6);
  }

  .leaderboard-row {
    border-bottom: 1px solid rgba(139, 92, 246, 0.08);
    transition: background 0.15s ease;
  }

  .leaderboard-row:hover {
    background: rgba(139, 92, 246, 0.08);
  }

  .leaderboard-row.is-me {
    background: rgba(139, 92, 246, 0.16);
    box-shadow: inset 3px 0 0 #a78bfa;
  }

  .leaderboard-table td {
    padding: 12px 18px;
    vertical-align: middle;
  }

  /* Rank Badge */
  .rank-badge {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 32px;
    height: 32px;
    border-radius: 8px;
    font-size: 0.88rem;
    font-weight: 800;
  }

  .rank-badge.gold {
    background: rgba(250, 204, 21, 0.2);
    border: 1px solid rgba(250, 204, 21, 0.45);
    color: #facc15;
  }

  .rank-badge.silver {
    background: rgba(148, 163, 184, 0.2);
    border: 1px solid rgba(148, 163, 184, 0.4);
    color: #cbd5e1;
  }

  .rank-badge.bronze {
    background: rgba(217, 119, 6, 0.2);
    border: 1px solid rgba(217, 119, 6, 0.4);
    color: #fb923c;
  }

  .rank-badge.standard {
    background: rgba(30, 27, 75, 0.4);
    border: 1px solid rgba(139, 92, 246, 0.15);
    color: #94a3b8;
  }

  /* User Cell */
  .user-inline {
    display: flex;
    align-items: center;
    gap: 12px;
  }

  .user-inline-details {
    display: flex;
    flex-direction: column;
    gap: 2px;
  }

  .user-name-line {
    display: flex;
    align-items: center;
    gap: 8px;
  }

  .user-link {
    text-decoration: none;
    color: inherit;
  }

  .user-link strong {
    font-size: 0.92rem;
    color: #f8fafc;
    transition: color 0.15s;
  }

  .user-link:hover strong {
    color: #c4b5fd;
  }

  .user-sub-handle {
    font-size: 0.76rem;
    color: #64748b;
  }

  .badge-you {
    padding: 1px 7px;
    background: #7c3aed;
    color: #ffffff;
    border-radius: 4px;
    font-size: 0.68rem;
    font-weight: 700;
    text-transform: uppercase;
  }

  /* Achievement Title Chip in Table */
  .achievement-table-chip {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    padding: 4px 10px;
    background: rgba(139, 92, 246, 0.14);
    border: 1px solid rgba(167, 139, 250, 0.28);
    border-radius: 6px;
    font-size: 0.8rem;
    font-weight: 700;
    color: #e9d5ff;
  }

  .chip-sparkle {
    color: #c084fc;
  }

  .level-indicator-pill {
    display: inline-flex;
    padding: 3px 9px;
    border-radius: 6px;
    background: rgba(56, 189, 248, 0.12);
    border: 1px solid rgba(56, 189, 248, 0.28);
    font-size: 0.8rem;
    font-weight: 700;
    color: #38bdf8;
  }

  .level-indicator-pill.is-max {
    background: rgba(250, 204, 21, 0.15);
    border-color: rgba(250, 204, 21, 0.35);
    color: #facc15;
  }

  .xp-val {
    font-size: 1rem;
    color: #ffffff;
  }

  .xp-label {
    font-size: 0.72rem;
    color: #94a3b8;
    margin-left: 2px;
  }

  /* Mobile Leaderboard */
  .leaderboard-mobile {
    display: flex;
    flex-direction: column;
    gap: 10px;
  }

  .mobile-rank-card {
    display: flex;
    align-items: center;
    gap: 12px;
    padding: 12px 14px;
    background: rgba(24, 20, 50, 0.65);
    border: 1px solid rgba(139, 92, 246, 0.18);
    border-radius: 12px;
    text-decoration: none;
    color: inherit;
    transition: background 0.15s;
  }

  .mobile-rank-card.is-me {
    background: rgba(139, 92, 246, 0.18);
    border-color: rgba(167, 139, 250, 0.4);
  }

  .mobile-rank-col {
    min-width: 32px;
  }

  .mobile-info-col {
    flex: 1;
    display: flex;
    flex-direction: column;
    gap: 3px;
    min-width: 0;
  }

  .mobile-name-row {
    display: flex;
    align-items: center;
    gap: 6px;
  }

  .mobile-name-row strong {
    font-size: 0.9rem;
    color: #f8fafc;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
  }

  .badge-you-mobile {
    padding: 1px 6px;
    background: #7c3aed;
    color: #ffffff;
    border-radius: 4px;
    font-size: 0.65rem;
    font-weight: 700;
  }

  .mobile-achievement-row {
    display: flex;
    align-items: center;
    gap: 6px;
    flex-wrap: wrap;
  }

  .mobile-title-tag {
    font-size: 0.72rem;
    font-weight: 700;
    color: #c4b5fd;
    background: rgba(139, 92, 246, 0.2);
    padding: 1px 6px;
    border-radius: 4px;
  }

  .mobile-level-tag {
    font-size: 0.72rem;
    font-weight: 700;
    color: #38bdf8;
    background: rgba(56, 189, 248, 0.15);
    padding: 1px 5px;
    border-radius: 4px;
  }

  .mobile-xp-col {
    text-align: right;
    white-space: nowrap;
  }

  .mobile-xp-col strong {
    font-size: 0.95rem;
    color: #ffffff;
  }

  .mobile-xp-col small {
    display: block;
    font-size: 0.66rem;
    color: #94a3b8;
  }

  /* Real Backend Pagination Controls */
  .pagination-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    flex-wrap: wrap;
    gap: 16px;
    margin-top: 24px;
    padding-top: 16px;
    border-top: 1px solid rgba(139, 92, 246, 0.15);
  }

  .pagination-info {
    font-size: 0.84rem;
    color: #94a3b8;
  }

  .pagination-info strong {
    color: #e2e8f0;
  }

  .pagination-controls {
    display: flex;
    align-items: center;
    gap: 8px;
  }

  .btn-page-nav {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    padding: 8px 14px;
    background: rgba(30, 26, 65, 0.6);
    border: 1px solid rgba(139, 92, 246, 0.25);
    border-radius: 8px;
    color: #e2e8f0;
    font-size: 0.82rem;
    font-weight: 600;
    text-decoration: none;
    transition: all 0.2s;
  }

  .btn-page-nav:not(.disabled):hover {
    background: rgba(139, 92, 246, 0.25);
    border-color: rgba(167, 139, 250, 0.45);
    color: #ffffff;
  }

  .btn-page-nav.disabled {
    opacity: 0.4;
    cursor: not-allowed;
    pointer-events: none;
  }

  .page-pills {
    display: flex;
    align-items: center;
    gap: 6px;
  }

  .page-num-pill {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    min-width: 34px;
    height: 34px;
    padding: 0 6px;
    background: rgba(30, 26, 65, 0.45);
    border: 1px solid rgba(139, 92, 246, 0.18);
    border-radius: 8px;
    color: #cbd5e1;
    font-size: 0.82rem;
    font-weight: 600;
    text-decoration: none;
    transition: all 0.15s;
  }

  .page-num-pill:hover {
    background: rgba(139, 92, 246, 0.2);
    color: #ffffff;
  }

  .page-num-pill.active {
    background: #7c3aed;
    border-color: #a78bfa;
    color: #ffffff;
    font-weight: 700;
    box-shadow: 0 0 12px rgba(124, 58, 237, 0.4);
  }

  .page-ellipsis {
    color: #64748b;
    padding: 0 4px;
  }

  /* Modal Styles */
  .modal-backdrop {
    position: fixed;
    inset: 0;
    background: rgba(0, 0, 0, 0.75);
    backdrop-filter: blur(8px);
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 16px;
    z-index: 100;
  }

  .modal-box {
    background: linear-gradient(135deg, rgba(28, 24, 56, 0.98) 0%, rgba(16, 13, 36, 0.98) 100%);
    border: 1px solid rgba(139, 92, 246, 0.35);
    border-radius: 16px;
    width: 100%;
    max-width: 720px;
    max-height: 85vh;
    display: flex;
    flex-direction: column;
    box-shadow: 0 20px 50px rgba(0, 0, 0, 0.6);
    overflow: hidden;
  }

  .modal-header {
    display: flex;
    justify-content: space-between;
    align-items: flex-start;
    padding: 20px 24px;
    border-bottom: 1px solid rgba(139, 92, 246, 0.18);
  }

  .modal-header-titles {
    display: flex;
    align-items: flex-start;
    gap: 12px;
  }

  .modal-header-titles h3 {
    margin: 0 0 4px;
    font-size: 1.15rem;
    font-weight: 800;
    color: #f8fafc;
  }

  .modal-header-titles p {
    margin: 0;
    font-size: 0.82rem;
    color: #94a3b8;
  }

  .btn-close-modal {
    background: none;
    border: none;
    color: #94a3b8;
    cursor: pointer;
    padding: 4px;
    display: flex;
    align-items: center;
    justify-content: center;
  }

  .btn-close-modal:hover {
    color: #ffffff;
  }

  .modal-body {
    padding: 20px 24px;
    overflow-y: auto;
    display: flex;
    flex-direction: column;
    gap: 20px;
  }

  .titles-roadmap {
    display: flex;
    flex-direction: column;
    gap: 8px;
  }

  .roadmap-row {
    display: flex;
    align-items: center;
    gap: 14px;
    padding: 10px 14px;
    background: rgba(20, 16, 42, 0.5);
    border: 1px solid rgba(139, 92, 246, 0.12);
    border-radius: 10px;
    transition: all 0.15s;
  }

  .roadmap-row.is-unlocked {
    background: rgba(30, 24, 60, 0.65);
