  .workspace-mobile-topbar {
    display: none;
    align-items: center;
    justify-content: space-between;
    height: 44px;
    padding: 0 10px;
    background: rgba(10, 11, 18, 0.96);
    backdrop-filter: blur(12px);
    -webkit-backdrop-filter: blur(12px);
    border-bottom: 1px solid rgba(255, 255, 255, 0.06);
    position: sticky;
    top: 0;
    z-index: 30;
    gap: 8px;
    box-sizing: border-box;
  }

  @media (max-width: 1024px) {
    .workspace-app-shell,
    .workspace-main-area {
      touch-action: manipulation;
      -webkit-overflow-scrolling: touch;
    }

    .workspace-mobile-topbar {
      display: flex;
    }
  }

  .btn-hamburger,
  .btn-search-mobile {
    width: 34px;
    height: 34px;
    flex-shrink: 0;
    display: flex;
    align-items: center;
    justify-content: center;
    background: rgba(255, 255, 255, 0.04);
    border: 1px solid rgba(255, 255, 255, 0.07);
    border-radius: 7px;
    color: #cbd5e1;
    cursor: pointer;
    transition: all 0.15s ease;
  }

  .btn-hamburger:hover,
  .btn-search-mobile:hover {
    background: rgba(255, 255, 255, 0.08);
    color: #ffffff;
  }

  .mobile-scan-brand {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 6px;
    font-size: 0.84rem;
    font-weight: 600;
    min-width: 0;
    flex: 1;
    overflow: hidden;
  }

  .mobile-context-prefix {
    color: #94a3b8;
    font-weight: 500;
    white-space: nowrap;
    flex-shrink: 0;
  }

  .mobile-context-sep {
    color: rgba(255, 255, 255, 0.25);
    flex-shrink: 0;
  }

  .mobile-scan-title {
    color: #f8fafc;
    font-weight: 700;
    letter-spacing: -0.01em;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
    min-width: 0;
  }

  @media (max-width: 340px) {
    .mobile-context-prefix,
    .mobile-context-sep {
      display: none;
    }
  }

  .mobile-scan-role {
    display: none;
  }

  .workspace-view-content {
    flex: 1;
    min-width: 0;
    padding: 24px 32px 32px 28px;
  }

  @media (max-width: 1024px) {
    .workspace-view-content {
      padding: 8px 10px calc(100px + env(safe-area-inset-bottom, 24px)) 10px;
    }
  }

  /* Dedicated Contextual Mobile Bottom Nav */
  .scan-mobile-bottom-bar {
    display: none;
    position: fixed;
    bottom: 0;
    left: 0;
    right: 0;
    height: calc(56px + env(safe-area-inset-bottom, 0px));
    padding-bottom: env(safe-area-inset-bottom, 0px);
    background: rgba(8, 9, 15, 0.96);
    backdrop-filter: blur(16px);
    -webkit-backdrop-filter: blur(16px);
    border-top: 1px solid rgba(255, 255, 255, 0.08);
    z-index: 45;
    justify-content: space-around;
    align-items: center;
    box-shadow: 0 -4px 20px rgba(0, 0, 0, 0.5);
  }

  @media (max-width: 1024px) {
    .scan-mobile-bottom-bar {
      display: flex;
    }
  }

  .scan-nav-item {
    all: unset;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    gap: 3px;
    color: #94a3b8;
    font-size: 0.68rem;
    font-weight: 500;
    cursor: pointer;
    padding: 6px 8px;
    border-radius: 8px;
    transition: color 0.15s ease, transform 0.1s ease;
    min-width: 52px;
    position: relative;
  }

  .scan-nav-item:active {
    transform: scale(0.92);
  }

  .scan-nav-item.active {
    color: #c084fc;
    font-weight: 700;
  }

  .nav-item-icon-wrap {
    position: relative;
    display: inline-flex;
    align-items: center;
    justify-content: center;
  }

  .active-nav-dot {
    position: absolute;
    bottom: -6px;
    left: 50%;
    transform: translateX(-50%);
    width: 4px;
    height: 4px;
    border-radius: 9999px;
    background: #c084fc;
    box-shadow: 0 0 6px rgba(192, 132, 252, 0.8);
  }

  .nav-item-badge {
    position: absolute;
    top: -4px;
    right: -8px;
    min-width: 14px;
    height: 14px;
    padding: 0 3px;
    font-size: 0.58rem;
    font-weight: 700;
    background: #f59e0b;
    color: #000000;
    border-radius: 9999px;
    display: flex;
    align-items: center;
    justify-content: center;
    line-height: 1;
  }

  /* Unauthenticated */
  .onboarding-hero {
    display: flex;
    flex-direction: column;
    align-items: center;
    text-align: center;
    padding: 6rem 2rem;
    background: radial-gradient(circle at top, rgba(139, 92, 246, 0.15), transparent 70%), #0e111d;
    border: 1px solid rgba(255, 255, 255, 0.08);
    border-radius: 24px;
  }

  .hero-icon-ring {
    width: 90px;
    height: 90px;
    border-radius: 50%;
    background: rgba(139, 92, 246, 0.15);
    border: 1px solid rgba(139, 92, 246, 0.3);
    display: flex;
    align-items: center;
    justify-content: center;
    color: #c4b5fd;
    margin-bottom: 1.5rem;
  }

  .onboarding-title {
    font-family: 'Manrope', -apple-system, BlinkMacSystemFont, sans-serif;
    font-size: 2.4rem;
    font-weight: 800;
    color: #ffffff;
    margin: 0 0 0.75rem;
  }

  .onboarding-sub {
    font-size: 1.05rem;
    color: #94a3b8;
    max-width: 580px;
    line-height: 1.6;
    margin: 0 0 2rem;
  }

  .onboarding-actions {
    display: flex;
    gap: 1rem;
  }

  /* Infrastructure temporary error (State 3) */
  .infra-error-state {
    display: flex;
    flex-direction: column;
    align-items: center;
    text-align: center;
    padding: 5rem 2rem;
    background: radial-gradient(circle at top, rgba(245, 158, 11, 0.12), transparent 70%), #0e111d;
    border: 1px solid rgba(245, 158, 11, 0.25);
    border-radius: 20px;
    margin: 2rem 0;
  }

  .infra-error-icon-ring {
    width: 80px;
    height: 80px;
    border-radius: 50%;
    background: rgba(245, 158, 11, 0.12);
    border: 1px solid rgba(245, 158, 11, 0.3);
    display: flex;
    align-items: center;
    justify-content: center;
    margin-bottom: 1.5rem;
  }

  .infra-error-title {
    font-family: 'Manrope', -apple-system, BlinkMacSystemFont, sans-serif;
    font-size: 2rem;
    font-weight: 800;
    color: #f1f5f9;
    margin: 0 0 0.75rem;
  }

  .infra-error-sub {
    font-size: 1.05rem;
    color: #94a3b8;
    max-width: 540px;
    line-height: 1.6;
    margin: 0 0 2rem;
  }

  .infra-error-actions {
    display: flex;
    gap: 1rem;
  }

  .btn-retry-infra {
    display: inline-flex;
    align-items: center;
    gap: 8px;
    background: linear-gradient(135deg, #d97706 0%, #b45309 100%);
    border: 1px solid rgba(245, 158, 11, 0.5);
    color: #ffffff;
    font-weight: 700;
    cursor: pointer;
    box-shadow: 0 4px 14px rgba(245, 158, 11, 0.25);
    transition: all 0.15s ease;
  }

  .btn-retry-infra:hover {
    background: linear-gradient(135deg, #f59e0b 0%, #d97706 100%);
    box-shadow: 0 6px 20px rgba(245, 158, 11, 0.35);
    transform: translateY(-1px);
  }

  .btn-primary {
    padding: 0.85rem 2rem;
    background: #8b5cf6;
    color: #ffffff;
    border-radius: 12px;
    font-weight: 700;
    text-decoration: none;
    transition: all 0.2s ease;
  }

  .btn-primary:hover {
    background: #7c3aed;
    box-shadow: 0 4px 20px rgba(139, 92, 246, 0.4);
  }

  .btn-secondary {
    padding: 0.85rem 2rem;
    background: rgba(255, 255, 255, 0.06);
    border: 1px solid rgba(255, 255, 255, 0.1);
    color: #e2e8f0;
    border-radius: 12px;
    font-weight: 600;
    text-decoration: none;
    transition: all 0.2s ease;
  }

  .btn-secondary:hover {
    background: rgba(255, 255, 255, 0.1);
    color: #ffffff;
  }

  /* Partnership Portal */
  .partnership-portal {
    display: flex;
    flex-direction: column;
    gap: 2.5rem;
  }

  .portal-header {
    text-align: center;
    max-width: 800px;
    margin: 0 auto;
  }

  .badge-partnership {
    display: inline-flex;
    align-items: center;
    gap: 0.4rem;
    padding: 0.35rem 0.85rem;
    background: rgba(223, 194, 141, 0.15);
    border: 1px solid rgba(223, 194, 141, 0.35);
    border-radius: 9999px;
    color: #dfc28d;
    font-size: 0.82rem;
    font-weight: 700;
    margin-bottom: 1rem;
  }

  .portal-title {
    font-family: 'Manrope', -apple-system, BlinkMacSystemFont, sans-serif;
    font-size: 2.4rem;
    font-weight: 800;
    color: #ffffff;
    margin: 0 0 1rem;
    letter-spacing: -0.02em;
  }

  .portal-sub {
    font-size: 1.05rem;
    color: #94a3b8;
    line-height: 1.6;
    margin: 0;
  }

  .perks-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
    gap: 1.5rem;
  }

  .perk-card {
    background: #0e111d;
    border: 1px solid rgba(255, 255, 255, 0.07);
    border-radius: 16px;
    padding: 1.75rem;
    display: flex;
    flex-direction: column;
    gap: 0.75rem;
  }

  .perk-icon {
    width: 44px;
    height: 44px;
    border-radius: 12px;
    background: rgba(139, 92, 246, 0.15);
    display: flex;
    align-items: center;
    justify-content: center;
    color: #c4b5fd;
    margin-bottom: 0.25rem;
  }

  .perk-card h3 {
    font-size: 1.15rem;
    font-weight: 700;
    color: #ffffff;
    margin: 0;
  }

  .perk-card p {
    font-size: 0.9rem;
    color: #94a3b8;
    line-height: 1.5;
    margin: 0;
  }

  .cta-box {
    background: radial-gradient(circle at top center, rgba(139, 92, 246, 0.2), transparent 70%), #0e111d;
    border: 1px solid rgba(139, 92, 246, 0.3);
    border-radius: 20px;
    padding: 3rem 2rem;
    text-align: center;
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 1rem;
  }

  .cta-box h2 {
    font-size: 1.8rem;
    font-weight: 800;
    color: #ffffff;
    margin: 0;
  }

  .cta-box p {
    font-size: 1rem;
    color: #cbd5e1;
    max-width: 600px;
    line-height: 1.6;
    margin: 0 0 0.5rem;
  }

  .btn-discord-cta {
    display: inline-flex;
    align-items: center;
    gap: 0.6rem;
    padding: 0.9rem 2.2rem;
    background: #5865f2;
    color: #ffffff;
    border-radius: 12px;
    font-weight: 700;
    font-size: 0.95rem;
    text-decoration: none;
    transition: all 0.2s ease;
  }

  .btn-discord-cta:hover {
    background: #4752c4;
    box-shadow: 0 6px 24px rgba(88, 101, 242, 0.45);
    transform: translateY(-2px);
  }

  /* Active Dashboard */
  .dash-header {
    display: flex;
    align-items: flex-end;
    justify-content: space-between;
    gap: 1.5rem;
    margin-bottom: 2rem;
    padding-bottom: 1.5rem;
    border-bottom: 1px solid rgba(255, 255, 255, 0.08);
    flex-wrap: wrap;
  }

  .header-tag {
    display: inline-flex;
    align-items: center;
    gap: 0.35rem;
    color: #dfc28d;
    font-size: 0.8rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.05em;
    margin-bottom: 0.4rem;
  }

  .dash-main-title {
    font-family: 'Manrope', -apple-system, BlinkMacSystemFont, sans-serif;
    font-size: 2.2rem;
    font-weight: 800;
    color: #ffffff;
    margin: 0 0 0.5rem;
  }

  .dash-role-row {
    display: flex;
    align-items: center;
    gap: 1rem;
  }

  .role-badge {
    padding: 0.25rem 0.65rem;
    background: rgba(139, 92, 246, 0.2);
    border: 1px solid rgba(139, 92, 246, 0.35);
    border-radius: 6px;
    color: #c4b5fd;
    font-size: 0.8rem;
    font-weight: 700;
  }

  .link-public-profile {
    font-size: 0.85rem;
    color: #94a3b8;
    text-decoration: none;
    transition: color 0.2s ease;
  }

  .link-public-profile:hover {
    color: #dfc28d;
  }

  .scan-switcher {
    display: flex;
    align-items: center;
    gap: 0.6rem;
  }

  .scan-switcher select {
    padding: 0.5rem 1rem;
    background: #0e111d;
    border: 1px solid rgba(255, 255, 255, 0.15);
    border-radius: 8px;
    color: #ffffff;
    font-size: 0.88rem;
    outline: none;
  }

  /* Stats overview */
  .stats-overview {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
    gap: 1.25rem;
    margin-bottom: 2.5rem;
  }

  .stat-card {
    background: #0e111d;
    border: 1px solid rgba(255, 255, 255, 0.07);
    border-radius: 14px;
    padding: 1.25rem 1.5rem;
    display: flex;
    align-items: center;
    gap: 1.25rem;
  }

  :global(.stat-icon) {
    color: #dfc28d;
  }

  .stat-meta {
    display: flex;
    flex-direction: column;
  }

  .stat-num {
    font-size: 1.6rem;
    font-weight: 800;
    color: #ffffff;
    line-height: 1.1;
  }

  .stat-desc {
    font-size: 0.8rem;
    color: #94a3b8;
    margin-top: 0.2rem;
  }

  /* Columns */
  .dash-columns {
    display: grid;
    grid-template-columns: 1fr 1.25fr;
    gap: 2rem;
  }

  .dash-col-left,
  .dash-col-right {
    display: flex;
    flex-direction: column;
    gap: 2rem;
  }

  .card-section {
    background: #0e111d;
    border: 1px solid rgba(255, 255, 255, 0.07);
    border-radius: 16px;
    padding: 1.5rem;
  }

  .section-top {
    display: flex;
    align-items: center;
    gap: 0.6rem;
    margin-bottom: 1.25rem;
    color: #dfc28d;
  }

  .section-top h2 {
    font-size: 1.15rem;
    font-weight: 700;
    color: #ffffff;
    margin: 0;
  }

  .settings-form {
    display: flex;
    flex-direction: column;
    gap: 1rem;
  }

  .form-field {
    display: flex;
    flex-direction: column;
    gap: 0.4rem;
  }

  .form-field label {
    font-size: 0.85rem;
    color: #cbd5e1;
    font-weight: 600;
  }

  .form-field input:not(.smart-search-input),
  .form-field textarea {
    padding: 0.75rem 1rem;
    background: rgba(255, 255, 255, 0.04);
    border: 1px solid rgba(255, 255, 255, 0.1);
    border-radius: 10px;
    color: #ffffff;
    font-size: 0.9rem;
    outline: none;
    transition: border-color 0.2s ease;
  }

  .form-field input:not(.smart-search-input):focus,
  .form-field textarea:focus {
    border-color: #8b5cf6;
  }

  .btn-save {
    padding: 0.75rem 1.5rem;
    background: #8b5cf6;
    color: #ffffff;
    border: none;
    border-radius: 10px;
    font-weight: 700;
    font-size: 0.9rem;
    cursor: pointer;
    transition: all 0.2s ease;
    align-self: flex-start;
    margin-top: 0.5rem;
  }

  .btn-save:hover {
    background: #7c3aed;
  }

  .success-banner {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    padding: 0.75rem 1rem;
    background: rgba(16, 185, 129, 0.15);
    border: 1px solid rgba(16, 185, 129, 0.3);
    border-radius: 8px;
    color: #6ee7b7;
    font-size: 0.88rem;
    margin-bottom: 1rem;
  }

  .error-banner {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    padding: 0.75rem 1rem;
    background: rgba(239, 68, 68, 0.15);
    border: 1px solid rgba(239, 68, 68, 0.3);
    border-radius: 8px;
    color: #fca5a5;
    font-size: 0.88rem;
    margin-bottom: 1rem;
  }

  /* Team */
  .team-list {
    display: flex;
    flex-direction: column;
    gap: 0.75rem;
  }

  .team-member-item {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    padding: 0.65rem 0.85rem;
    background: rgba(255, 255, 255, 0.03);
    border-radius: 10px;
  }

  .member-text {
    display: flex;
    flex-direction: column;
    flex: 1;
  }

  .member-display {
    font-size: 0.9rem;
    font-weight: 700;
    color: #ffffff;
  }

  .member-user {
    font-size: 0.75rem;
    color: #64748b;
  }

  .role-pill {
    padding: 0.2rem 0.5rem;
    background: rgba(255, 255, 255, 0.06);
    border-radius: 4px;
    font-size: 0.72rem;
    color: #cbd5e1;
  }

  /* Works List */
  .works-list {
    display: flex;
    flex-direction: column;
    gap: 0.6rem;
  }

  .dash-work-item {
    display: flex;
    align-items: center;
    gap: 0.85rem;
    padding: 0.6rem 0.85rem;
    background: rgba(255, 255, 255, 0.03);
    border-radius: 10px;
    text-decoration: none;
    color: inherit;
    transition: all 0.2s ease;
  }

  .dash-work-item:hover {
    background: rgba(255, 255, 255, 0.07);
    transform: translateX(3px);
  }

  .work-mini-cover {
    width: 36px;
    height: 50px;
    border-radius: 6px;
    object-fit: cover;
  }

  .work-mini-placeholder {
    width: 36px;
    height: 50px;
    border-radius: 6px;
    background: #1e1b4b;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 0.7rem;
    font-weight: 700;
    color: #c4b5fd;
  }

  .work-mini-info {
    display: flex;
    flex-direction: column;
    flex: 1;
    min-width: 0;
    gap: 0.2rem;
  }

  .work-mini-title {
    font-size: 0.92rem;
    font-weight: 700;
    color: #ffffff;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
  }

  .work-mini-views {
    display: inline-flex;
    align-items: center;
    gap: 0.35rem;
    font-size: 0.75rem;
    color: #94a3b8;
  }

  :global(.work-arrow) {
    color: #64748b;
  }

  /* Recent Chapters */
  .recent-chapters-list {
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
  }

  .dash-ch-item {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 0.75rem 1rem;
    background: rgba(255, 255, 255, 0.03);
    border-radius: 8px;
    text-decoration: none;
    color: inherit;
    transition: background 0.2s ease;
  }

  .dash-ch-item:hover {
    background: rgba(255, 255, 255, 0.07);
  }

  .ch-left {
    display: flex;
    align-items: center;
    gap: 0.75rem;
  }

  .ch-work {
    font-weight: 700;
    color: #ffffff;
    font-size: 0.9rem;
  }

  .ch-num {
    padding: 0.15rem 0.45rem;
    background: rgba(139, 92, 246, 0.15);
    border-radius: 4px;
    font-size: 0.75rem;
    font-weight: 700;
    color: #c4b5fd;
  }

  .ch-right {
    display: flex;
    align-items: center;
    gap: 1rem;
    font-size: 0.78rem;
    color: #64748b;
  }

  .ch-views-count {
    display: inline-flex;
    align-items: center;
    gap: 0.3rem;
  }

  .empty-text {
    font-size: 0.88rem;
    color: #64748b;
    margin: 0;
  }

  .font-mono {
    font-family: monospace;
  }

  .text-green {
    color: #34d399 !important;
  }

  .text-red {
    color: #f87171 !important;
  }

  /* Non-member Request Tracking */
  .my-partner-requests-card {
    background: #0e111d;
    border: 1px solid rgba(255, 255, 255, 0.08);
    border-radius: 18px;
    padding: 1.75rem;
    display: flex;
    flex-direction: column;
    gap: 1.25rem;
  }

  .requests-card-header {
    display: flex;
    align-items: center;
    gap: 0.6rem;
    color: #dfc28d;
  }

  .requests-card-header h2 {
    font-size: 1.2rem;
    font-weight: 700;
    color: #ffffff;
    margin: 0;
  }

  .requests-track-list {
    display: flex;
    flex-direction: column;
    gap: 0.85rem;
  }

  .track-item {
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
    padding: 1rem 1.25rem;
    background: rgba(255, 255, 255, 0.03);
    border: 1px solid rgba(255, 255, 255, 0.06);
    border-radius: 12px;
  }

  .track-item.status-pending {
    border-color: rgba(139, 92, 246, 0.3);
  }

  .track-item.status-approved {
    border-color: rgba(16, 185, 129, 0.3);
  }

  .track-item.status-rejected {
