  .applications-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(360px, 1fr));
    gap: 1.25rem;
    margin-top: 1rem;
  }

  .app-card {
    background: rgba(255, 255, 255, 0.02);
    border: 1px solid rgba(255, 255, 255, 0.07);
    border-radius: 16px;
    padding: 1.5rem;
    display: flex;
    flex-direction: column;
    gap: 1rem;
    transition: all 0.2s ease;
  }

  .app-card:hover {
    border-color: rgba(139, 92, 246, 0.3);
    background: rgba(255, 255, 255, 0.035);
  }

  .app-card-header {
    display: flex;
    align-items: flex-start;
    justify-content: space-between;
    gap: 0.5rem;
  }

  .applicant-profile-row {
    display: flex;
    align-items: center;
    gap: 0.75rem;
  }

  .applicant-names {
    display: flex;
    flex-direction: column;
    gap: 0.15rem;
  }

  .applicant-link {
    text-decoration: none;
    color: inherit;
  }

  .applicant-link strong {
    font-size: 0.95rem;
    color: #f8fafc;
  }

  .applicant-user {
    font-size: 0.8rem;
    color: #64748b;
    display: block;
  }

  .app-timestamp {
    font-size: 0.72rem;
    color: #475569;
  }

  .app-status-badge-wrap {
    display: flex;
    flex-direction: column;
    align-items: flex-end;
    gap: 0.35rem;
  }

  .app-pos-tag {
    font-size: 0.75rem;
    font-weight: 700;
    padding: 0.2rem 0.55rem;
    border-radius: 6px;
    background: rgba(139, 92, 246, 0.15);
    color: #c4b5fd;
    border: 1px solid rgba(139, 92, 246, 0.3);
  }

  .app-opening-ref {
    font-size: 0.8rem;
    color: #94a3b8;
    padding-bottom: 0.5rem;
    border-bottom: 1px solid rgba(255, 255, 255, 0.04);
  }

  .app-opening-ref strong {
    color: #cbd5e1;
  }

  .app-card-body {
    display: flex;
    flex-direction: column;
    gap: 0.75rem;
  }

  .app-field-item {
    display: flex;
    flex-direction: column;
    gap: 0.2rem;
  }

  .app-field-label {
    font-size: 0.72rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.05em;
    color: #64748b;
  }

  .app-field-val {
    font-size: 0.86rem;
    color: #cbd5e1;
    line-height: 1.5;
    margin: 0;
  }

  .portfolio-link-btn {
    display: inline-flex;
    align-items: center;
    gap: 0.4rem;
    padding: 0.4rem 0.8rem;
    font-size: 0.82rem;
    font-weight: 600;
    color: #dfc28d;
    background: rgba(223, 194, 141, 0.1);
    border: 1px solid rgba(223, 194, 141, 0.25);
    border-radius: 8px;
    text-decoration: none;
    transition: all 0.2s ease;
  }

  .portfolio-link-btn:hover {
    background: rgba(223, 194, 141, 0.2);
    color: #ffffff;
  }

  .app-internal-notes-box {
    background: rgba(0, 0, 0, 0.25);
    border-radius: 10px;
    padding: 0.75rem 1rem;
    border: 1px solid rgba(255, 255, 255, 0.05);
  }

  .app-internal-notes-box strong {
    display: block;
    font-size: 0.72rem;
    color: #94a3b8;
    text-transform: uppercase;
    letter-spacing: 0.05em;
    margin-bottom: 0.25rem;
  }

  .app-internal-notes-box p {
    font-size: 0.84rem;
    color: #e2e8f0;
    margin: 0;
  }

  .app-qa-answers-box,
  .review-qa-answers-box {
    background: rgba(139, 92, 246, 0.06);
    border: 1px solid rgba(139, 92, 246, 0.2);
    border-radius: 8px;
    padding: 0.75rem 0.9rem;
    display: flex;
    flex-direction: column;
    gap: 0.4rem;
  }

  .app-qa-title {
    font-size: 0.75rem;
    font-weight: 700;
    color: #c084fc;
    letter-spacing: 0.03em;
    text-transform: uppercase;
  }

  .app-qa-list,
  .review-qa-list {
    display: flex;
    flex-direction: column;
    gap: 0.4rem;
  }

  .app-qa-entry,
  .review-qa-entry {
    display: flex;
    flex-direction: column;
    gap: 0.15rem;
  }

  .app-qa-question,
  .qa-q-text {
    font-size: 0.75rem;
    font-weight: 600;
    color: #94a3b8;
  }

  .app-qa-answer,
  .qa-a-text {
    font-size: 0.84rem;
    color: #f1f5f9;
    background: rgba(0, 0, 0, 0.25);
    padding: 0.3rem 0.6rem;
    border-radius: 4px;
  }

  .app-card-footer {
    padding-top: 0.75rem;
    border-top: 1px solid rgba(255, 255, 255, 0.05);
    margin-top: auto;
  }

  .btn-review-action {
    width: 100%;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 0.4rem;
    padding: 0.6rem 1rem;
    font-size: 0.86rem;
    font-weight: 700;
    border-radius: 8px;
    background: linear-gradient(135deg, rgba(139, 92, 246, 0.25), rgba(99, 102, 241, 0.25));
    border: 1px solid rgba(139, 92, 246, 0.4);
    color: #e9d5ff;
    cursor: pointer;
    transition: all 0.2s ease;
  }

  .btn-review-action:hover {
    background: linear-gradient(135deg, rgba(139, 92, 246, 0.4), rgba(99, 102, 241, 0.4));
    color: #ffffff;
  }

  /* Positions Management Grid */
  .callout-info-box {
    display: flex;
    align-items: flex-start;
    gap: 0.85rem;
    padding: 1rem 1.25rem;
    background: rgba(139, 92, 246, 0.08);
    border: 1px solid rgba(139, 92, 246, 0.25);
    border-radius: 12px;
    margin-bottom: 1.5rem;
    font-size: 0.88rem;
    line-height: 1.5;
    color: #cbd5e1;
  }

  .callout-info-box strong {
    display: block;
    color: #f1f5f9;
    font-size: 0.95rem;
    margin-bottom: 0.25rem;
  }

  .positions-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
    gap: 1.25rem;
  }

  .pos-management-card {
    background: rgba(255, 255, 255, 0.02);
    border: 1px solid rgba(255, 255, 255, 0.06);
    border-radius: 14px;
    padding: 1.25rem;
    display: flex;
    flex-direction: column;
    gap: 0.75rem;
    transition: all 0.2s ease;
  }

  .pos-management-card:hover {
    border-color: rgba(255, 255, 255, 0.12);
    background: rgba(255, 255, 255, 0.035);
  }

  .pos-card-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 0.5rem;
  }

  .pos-card-title-group {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    flex-wrap: wrap;
  }

  .pos-name-tag {
    font-size: 0.95rem;
    font-weight: 700;
    color: #f8fafc;
  }

  .pos-preset-pill {
    font-size: 0.7rem;
    font-weight: 600;
    padding: 0.15rem 0.45rem;
    border-radius: 6px;
    background: rgba(255, 255, 255, 0.06);
    color: #94a3b8;
  }

  .pos-card-desc {
    font-size: 0.84rem;
    color: #94a3b8;
    line-height: 1.5;
    margin: 0;
  }

  .pos-card-footer {
    display: flex;
    align-items: center;
    padding-top: 0.5rem;
    border-top: 1px solid rgba(255, 255, 255, 0.04);
    margin-top: auto;
  }

  .pos-members-count {
    display: inline-flex;
    align-items: center;
    gap: 0.35rem;
    font-size: 0.76rem;
    color: #64748b;
  }

  /* Activity Timeline */
  .activity-timeline {
    display: flex;
    flex-direction: column;
    gap: 1rem;
    margin-top: 1rem;
  }

  .timeline-entry {
    display: flex;
    align-items: flex-start;
    gap: 1rem;
    padding: 1rem 1.25rem;
    background: rgba(255, 255, 255, 0.02);
    border: 1px solid rgba(255, 255, 255, 0.05);
    border-radius: 12px;
  }

  .timeline-icon-wrap {
    width: 36px;
    height: 36px;
    border-radius: 10px;
    display: flex;
    align-items: center;
    justify-content: center;
    flex-shrink: 0;
    background: rgba(139, 92, 246, 0.15);
    color: #c4b5fd;
    border: 1px solid rgba(139, 92, 246, 0.25);
  }

  .timeline-icon-wrap.action-application_received {
    background: rgba(245, 158, 11, 0.15);
    color: #fcd34d;
    border-color: rgba(245, 158, 11, 0.3);
  }

  .timeline-icon-wrap.action-member_added {
    background: rgba(16, 185, 129, 0.15);
    color: #6ee7b7;
    border-color: rgba(16, 185, 129, 0.3);
  }

  .timeline-content {
    flex: 1;
    min-width: 0;
  }

  .timeline-text {
    font-size: 0.88rem;
    color: #cbd5e1;
    line-height: 1.5;
    margin: 0 0 0.25rem;
  }

  .timeline-text strong {
    color: #f8fafc;
  }

  .timeline-time {
    font-size: 0.74rem;
    color: #64748b;
  }

  .status-inline {
    font-weight: 700;
    padding: 0.1rem 0.35rem;
    border-radius: 4px;
  }

  .status-inline.status-approved {
    background: rgba(16, 185, 129, 0.2);
    color: #6ee7b7;
  }

  .status-inline.status-rejected {
    background: rgba(239, 68, 68, 0.2);
    color: #fca5a5;
  }

  /* Preposition Live Preview */
  .prep-live-preview {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    margin-top: 0.5rem;
    padding: 0.6rem 0.85rem;
    background: rgba(223, 194, 141, 0.08);
    border: 1px solid rgba(223, 194, 141, 0.2);
    border-radius: 8px;
    font-size: 0.82rem;
    color: #cbd5e1;
  }

  .prep-live-preview strong {
    color: #dfc28d;
    font-weight: 700;
  }

  /* Modals: Decision Radios & Review */
  .decision-radios {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 0.6rem;
    margin-top: 0.4rem;
  }

  .decision-radio-label {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 0.4rem;
    padding: 0.75rem 0.5rem;
    border-radius: 10px;
    font-size: 0.82rem;
    font-weight: 700;
    border: 1px solid rgba(255, 255, 255, 0.1);
    background: rgba(255, 255, 255, 0.03);
    color: #94a3b8;
    cursor: pointer;
    transition: all 0.2s ease;
  }

  .decision-radio-label input {
    display: none;
  }

  .decision-radio-label.approve.active {
    background: rgba(16, 185, 129, 0.15);
    border-color: rgba(16, 185, 129, 0.4);
    color: #6ee7b7;
  }

  .decision-radio-label.under-review.active {
    background: rgba(245, 158, 11, 0.15);
    border-color: rgba(245, 158, 11, 0.4);
    color: #fcd34d;
  }

  .decision-radio-label.reject.active {
    background: rgba(239, 68, 68, 0.15);
    border-color: rgba(239, 68, 68, 0.4);
    color: #fca5a5;
  }

  .approve-options-box {
    background: rgba(16, 185, 129, 0.06);
    border: 1px solid rgba(16, 185, 129, 0.2);
    border-radius: 10px;
    padding: 1rem;
  }

  .review-candidate-summary {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 1rem 1.25rem;
    background: rgba(255, 255, 255, 0.03);
    border: 1px solid rgba(255, 255, 255, 0.06);
    border-radius: 12px;
    margin-bottom: 1.25rem;
  }

  .review-candidate-profile {
    display: flex;
    align-items: center;
    gap: 0.75rem;
  }

  .review-candidate-profile strong {
    display: block;
    color: #f8fafc;
    font-size: 0.95rem;
  }

  .review-candidate-profile .user-handle {
    font-size: 0.8rem;
    color: #64748b;
  }

  .review-vac-badge {
    text-align: right;
  }

  .review-vac-badge span {
    font-size: 0.72rem;
    color: #64748b;
    display: block;
  }

  .review-vac-badge strong {
    color: #c4b5fd;
    font-size: 0.9rem;
  }

  .review-app-body {
    display: flex;
    flex-direction: column;
    gap: 0.75rem;
    max-height: 250px;
    overflow-y: auto;
    padding: 1rem;
    background: rgba(0, 0, 0, 0.25);
    border-radius: 10px;
    border: 1px solid rgba(255, 255, 255, 0.04);
    margin-bottom: 1.25rem;
  }

  .review-info-item {
    display: flex;
    flex-direction: column;
    gap: 0.2rem;
  }

  .review-info-item .item-label {
    font-size: 0.72rem;
    font-weight: 700;
    text-transform: uppercase;
    color: #64748b;
    letter-spacing: 0.05em;
  }

  .review-info-item p {
    font-size: 0.85rem;
    color: #cbd5e1;
    line-height: 1.45;
    margin: 0;
  }

  /* Assign Member Modal */
  .current-pos-list {
    display: flex;
    flex-direction: column;
    gap: 0.4rem;
    margin-top: 0.5rem;
  }

  .current-pos-item {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 0.5rem 0.75rem;
    background: rgba(255, 255, 255, 0.03);
    border: 1px solid rgba(255, 255, 255, 0.06);
    border-radius: 8px;
  }

  .pos-item-actions {
    display: flex;
    align-items: center;
    gap: 0.5rem;
  }

  .btn-text-action {
    background: transparent;
    border: none;
    color: #dfc28d;
    font-size: 0.76rem;
    font-weight: 600;
    cursor: pointer;
    padding: 0.2rem 0.4rem;
  }

  .btn-text-action:hover {
    text-decoration: underline;
  }

  .btn-icon-del-pos {
    background: transparent;
    border: none;
    color: #ef4444;
    cursor: pointer;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    padding: 0.25rem;
    border-radius: 4px;
  }

  .btn-icon-del-pos:hover {
    background: rgba(239, 68, 68, 0.15);
  }

  .empty-mini-text {
    font-size: 0.82rem;
    color: #64748b;
    font-style: italic;
    margin: 0.5rem 0 0;
  }

  .checkbox-container {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    cursor: pointer;
    margin: 0.75rem 0;
  }

  .checkbox-label {
    font-size: 0.84rem;
    color: #cbd5e1;
  }

  /* Staff Notes / Mural */
  .staff-isolation-pill {
    display: inline-flex;
    align-items: center;
    gap: 0.4rem;
    padding: 0.35rem 0.85rem;
    background: rgba(16, 185, 129, 0.12);
    border: 1px solid rgba(16, 185, 129, 0.35);
    color: #34d399;
    border-radius: 999px;
    font-size: 0.8rem;
    font-weight: 700;
  }

  .section-sub-desc {
    font-size: 0.88rem;
    color: #94a3b8;
    margin: 0.35rem 0 1.5rem;
    line-height: 1.5;
  }

  .staff-note-composer {
    background: rgba(13, 16, 26, 0.85);
    border: 1px solid rgba(181, 154, 245, 0.2);
    border-radius: 16px;
    padding: 1.25rem;
    margin-bottom: 2rem;
  }

  .composer-body-area {
    margin-bottom: 0.85rem;
  }

  .composer-controls-row {
    display: flex;
    justify-content: space-between;
    align-items: center;
    flex-wrap: wrap;
    gap: 0.75rem;
    padding-top: 0.85rem;
    border-top: 1px solid rgba(255, 255, 255, 0.06);
  }

  .pin-checkbox-label {
    display: inline-flex;
    align-items: center;
    gap: 0.5rem;
    font-size: 0.85rem;
    color: #dfc28d;
    font-weight: 600;
    cursor: pointer;
  }

  .composer-note-hint {
    font-size: 0.8rem;
    color: #64748b;
  }

  .staff-notes-list {
    display: flex;
    flex-direction: column;
    gap: 1.25rem;
  }

  .staff-note-card {
    background: rgba(18, 22, 34, 0.75);
    border: 1px solid rgba(255, 255, 255, 0.08);
    border-radius: 14px;
    padding: 1.25rem;
    transition: border-color 0.2s ease;
  }

  .staff-note-card.is-pinned {
    border-color: rgba(223, 194, 141, 0.5);
    background: rgba(223, 194, 141, 0.04);
  }

  .staff-pinned-badge {
    display: inline-flex;
    align-items: center;
    gap: 0.35rem;
    font-size: 0.74rem;
    font-weight: 800;
    color: #dfc28d;
    background: rgba(223, 194, 141, 0.15);
    padding: 0.2rem 0.6rem;
    border-radius: 6px;
    margin-bottom: 0.85rem;
    text-transform: uppercase;
    letter-spacing: 0.04em;
  }

  .staff-note-header {
    display: flex;
    justify-content: space-between;
    align-items: flex-start;
    margin-bottom: 0.75rem;
    gap: 0.75rem;
  }

  .note-author-group {
    display: flex;
    align-items: center;
    gap: 0.75rem;
  }

  .note-author-info {
    display: flex;
    flex-direction: column;
  }

  .note-author-name {
    font-size: 0.92rem;
    color: #f1f5f9;
    font-weight: 700;
  }

  .note-meta-line {
    font-size: 0.78rem;
    color: #64748b;
  }

  .btn-delete-note {
    background: transparent;
    border: none;
    color: #64748b;
    padding: 0.35rem;
    border-radius: 6px;
    cursor: pointer;
    transition: all 0.15s ease;
  }

  .btn-delete-note:hover {
    color: #ef4444;
    background: rgba(239, 68, 68, 0.12);
  }

  .staff-note-content {
    margin: 0;
    font-size: 0.92rem;
    color: #cbd5e1;
    line-height: 1.6;
    white-space: pre-wrap;
    word-break: break-word;
  }

  /* Member Visibility in Team Tab */
  .member-card-visibility {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 0.5rem;
    padding: 0.65rem 0;
    margin: 0.65rem 0;
    border-top: 1px solid rgba(255, 255, 255, 0.05);
    border-bottom: 1px solid rgba(255, 255, 255, 0.05);
    flex-wrap: wrap;
  }

  .vis-status-row {
    display: inline-flex;
    align-items: center;
    gap: 0.4rem;
  }

  .vis-label {
    font-size: 0.78rem;
    color: #64748b;
    font-weight: 600;
  }

  .badge-vis-status {
    font-size: 0.72rem;
    font-weight: 700;
    padding: 0.15rem 0.5rem;
    border-radius: 4px;
    text-transform: uppercase;
    letter-spacing: 0.03em;
  }

  .badge-vis-status.public {
    background: rgba(16, 185, 129, 0.12);
    color: #34d399;
    border: 1px solid rgba(16, 185, 129, 0.3);
  }

  .badge-vis-status.private {
    background: rgba(245, 158, 11, 0.12);
    color: #fbbf24;
    border: 1px solid rgba(245, 158, 11, 0.3);
  }

  .badge-vis-status.hidden-admin {
    background: rgba(239, 68, 68, 0.12);
    color: #f87171;
    border: 1px solid rgba(239, 68, 68, 0.3);
  }

  .vis-toggle-form {
    display: inline-flex;
    margin: 0;
  }

  .btn-vis-toggle {
    background: rgba(255, 255, 255, 0.06);
    border: 1px solid rgba(255, 255, 255, 0.12);
    color: #cbd5e1;
    padding: 0.25rem 0.65rem;
    border-radius: 6px;
    font-size: 0.74rem;
    font-weight: 600;
    cursor: pointer;
    transition: all 0.15s ease;
  }

  .btn-vis-toggle:hover {
    background: rgba(255, 255, 255, 0.12);
    color: #fff;
  }

  @media (max-width: 900px) {
    .dash-columns {
      grid-template-columns: 1fr;
    }
    .transfer-alert-card {
      flex-direction: column;
      align-items: flex-start;
    }
    .decision-radios {
      grid-template-columns: 1fr;
    }
    .openings-dash-grid,
    .applications-grid,
    .team-detailed-grid {
      grid-template-columns: 1fr;
    }
  }

  .emergency-banner-alert {
    display: flex;
    align-items: flex-start;
    gap: 12px;
    background: rgba(244, 63, 94, 0.12);
    border: 1px solid rgba(244, 63, 94, 0.3);
    border-radius: 12px;
    padding: 14px 18px;
    margin-bottom: 1.5rem;
    color: #fecdd3;
  }

  .emergency-banner-alert strong {
    display: block;
    color: #fda4af;
    font-size: 0.93rem;
  }

  .emergency-banner-alert p {
    margin: 4px 0 0;
    font-size: 0.85rem;
    color: #cbd5e1;
  }

  .pause-banner-alert {
    display: flex;
    align-items: center;
    gap: 10px;
    background: rgba(245, 158, 11, 0.12);
    border: 1px solid rgba(245, 158, 11, 0.3);
    border-radius: 12px;
    padding: 12px 16px;
    margin-bottom: 1.5rem;
    color: #fde68a;
    font-size: 0.88rem;
    font-weight: 500;
  }

  .dash-category-selector {
    display: flex;
    align-items: center;
    gap: 8px;
    background: rgba(15, 23, 42, 0.6);
    border: 1px solid rgba(255, 255, 255, 0.08);
    border-radius: 14px;
