    align-items: center;
    gap: 3px;
    font-size: 0.66rem;
    font-weight: 700;
    padding: 1px 5px;
    border-radius: 4px;
    background: rgba(139, 92, 246, 0.25);
    color: #e9d5ff;
  }

  .comment-badge-important {
    font-size: 0.66rem;
    font-weight: 700;
    padding: 1px 5px;
    border-radius: 4px;
    background: rgba(245, 158, 11, 0.2);
    color: #fcd34d;
  }

  .comment-badge-pending {
    font-size: 0.66rem;
    font-weight: 700;
    padding: 1px 5px;
    border-radius: 4px;
