  /* --------------------------------------------------------------------------
     BOTTOM COMPOSER DOCK
     -------------------------------------------------------------------------- */
  .comment-composer-dock {
    margin-top: 10px;
    padding: 16px 20px;
    background: #14141e;
    border: 1px solid rgba(139, 92, 246, 0.25);
    border-radius: 12px;
    box-shadow: 0 4px 20px rgba(0, 0, 0, 0.35);
  }

  .chapter-note-form {
    display: flex;
    flex-direction: column;
    gap: 10px;
    margin: 0;
  }

  .composer-top-controls {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 10px;
  }

  .composer-label {
    font-size: 0.85rem;
    font-weight: 600;
    color: #f1f5f9;
  }

  .kind-select {
    padding: 4px 10px;
    background: #1f1f2e;
    border: 1px solid rgba(255, 255, 255, 0.12);
    border-radius: 6px;
    color: #e2e8f0;
    font-size: 0.78rem;
    cursor: pointer;
  }

  .composer-input-row {
    width: 100%;
  }

  .composer-textarea {
    width: 100%;
    min-height: 80px;
    padding: 10px 14px;
    background: #0d0d14;
    border: 1px solid rgba(255, 255, 255, 0.1);
    border-radius: 8px;
    color: #fff;
    font-size: 0.88rem;
    font-family: inherit;
    line-height: 1.45;
    box-sizing: border-box;
    resize: vertical;
    transition: border-color 0.2s ease;
  }

  .composer-textarea:focus {
    outline: none;
    border-color: #8b5cf6;
    box-shadow: 0 0 0 2px rgba(139, 92, 246, 0.25);
  }

  .composer-bottom-row {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 12px;
    flex-wrap: wrap;
  }

  .composer-hint {
    font-size: 0.75rem;
    color: #64748b;
  }

  .btn-send-note {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    padding: 8px 18px;
    background: #8b5cf6;
    border: 1px solid #7c3aed;
    border-radius: 8px;
    color: #fff;
    font-size: 0.85rem;
    font-weight: 600;
    cursor: pointer;
    transition: all 0.2s ease;
  }

  .btn-send-note:hover:not(:disabled) {
    background: #7c3aed;
    box-shadow: 0 2px 10px rgba(139, 92, 246, 0.4);
  }

  .btn-send-note:disabled {
    opacity: 0.45;
    cursor: not-allowed;
  }

  .spinner-xs {
    width: 12px;
    height: 12px;
    border: 2px solid rgba(255, 255, 255, 0.3);
    border-top-color: #fff;
    border-radius: 50%;
    animation: spin 0.7s linear infinite;
  }

  @keyframes spin {
    to { transform: rotate(360deg); }
  }

  /* --------------------------------------------------------------------------
     RESPONSIVE BREAKPOINTS (ANDROID & MOBILE VIEWPORTS)
     -------------------------------------------------------------------------- */
  @media (max-width: 900px) {
    .chapter-details-root {
      padding: 10px 12px calc(110px + env(safe-area-inset-bottom, 24px)) 12px;
      gap: 10px;
    }

    .desktop-pipeline-flow {
      display: none;
    }

    .mobile-vertical-timeline {
      display: flex;
    }

    .hero-series-title {
      font-size: 0.72rem;
      margin-bottom: 1px;
    }

    .hero-chapter-title {
      font-size: 1.05rem;
      line-height: 1.25;
    }

    .chapter-hero-card {
      padding: 10px 12px;
      gap: 10px;
      border-radius: 10px;
    }

    .hero-cover-wrap {
      width: 44px;
      height: 62px;
      border-radius: 6px;
    }

    .hero-badges-row {
      gap: 4px;
      margin-top: 4px;
    }

    .badge-item {
      font-size: 0.7rem;
      padding: 2px 6px;
      border-radius: 4px;
    }

    .chapter-details-tabs {
      width: 100%;
      justify-content: space-between;
      padding: 3px;
      gap: 4px;
      border-radius: 8px;
      margin-top: 2px;
    }

    .details-tab-btn {
      flex: 1;
      justify-content: center;
      padding: 7px 6px;
      font-size: 0.78rem;
      min-height: 38px;
    }

    .tab-label-full {
      display: none;
    }

    .tab-label-short {
      display: inline;
    }

    .tab-pane-comments {
      padding-bottom: calc(110px + env(safe-area-inset-bottom, 24px)); /* Virtual keyboard clearance & safe area */
    }

    .comment-composer-dock {
      /* Android keyboard safety clearance */
      padding-bottom: calc(16px + env(safe-area-inset-bottom, 0px));
    }
  }

  @media (max-width: 640px) {
    .header-breadcrumbs {
      display: none;
    }

    .btn-back-text-full {
      display: none;
    }

    .btn-back-text-short {
      display: inline;
    }

    .btn-preview-text-full {
      display: none;
    }

    .btn-preview-text-short {
      display: inline;
    }

    .icon-preview-external {
      display: none;
    }

    .btn-back-stage,
    .btn-action-preview {
      min-height: 38px;
      padding: 6px 12px;
      font-size: 0.82rem;
    }

    .hero-badges-row {
      gap: 4px;
    }

    .badge-item {
      font-size: 0.7rem;
      padding: 2px 6px;
    }

    .deliverables-list-grid {
      grid-template-columns: 1fr;
    }

    .team-roles-grid {
      grid-template-columns: 1fr;
    }
  }

/* src/routes/scan/components/ChapterWorkspaceModal.svelte */
.modal-backdrop {
    position: fixed;
    inset: 0;
    background: rgba(0, 0, 0, 0.8);
    display: flex;
    align-items: center;
    justify-content: center;
    z-index: 120;
    backdrop-filter: blur(5px);
    padding: 1.5rem;
  }

  .chapter-workspace-card {
    background: #111115;
    border: 1px solid #27272a;
    border-radius: 14px;
    width: 100%;
    max-width: 860px;
    height: 640px;
    max-height: 90vh;
    display: flex;
    flex-direction: column;
    overflow: hidden;
    box-shadow: 0 20px 40px rgba(0, 0, 0, 0.6);
