  .lineage-label {
    font-size: 11.5px;
    color: #94a3b8;
    font-weight: 600;
  }

  .lineage-tags-strip {
    display: flex;
    align-items: center;
    gap: 6px;
    flex-wrap: wrap;
  }

  .lineage-tag {
    background: rgba(255, 255, 255, 0.04);
    border: 1px solid rgba(255, 255, 255, 0.08);
    padding: 2px 6px;
    border-radius: 4px;
    font-size: 11px;
    color: #cbd5e1;
  }

  /* History Timeline */
  .timeline-feed {
    display: flex;
    flex-direction: column;
    position: relative;
  }

  .timeline-row {
    display: flex;
    gap: 14px;
  }

  .timeline-dot-connector {
    display: flex;
    flex-direction: column;
    align-items: center;
    width: 20px;
  }

  .timeline-dot {
    width: 10px;
    height: 10px;
    border-radius: 50%;
    background: #8b5cf6;
    margin-top: 4px;
  }

  .timeline-line {
    flex: 1;
    width: 2px;
    background: rgba(255, 255, 255, 0.08);
    margin: 4px 0;
  }

  .timeline-content-card {
    flex: 1;
    background: #0b0816;
    border: 1px solid rgba(255, 255, 255, 0.05);
    border-radius: 8px;
    padding: 10px 14px;
    margin-bottom: 12px;
    display: flex;
    flex-direction: column;
    gap: 4px;
  }

  .timeline-top {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
  }

  .timeline-event-name {
    font-size: 12.5px;
    font-weight: 800;
    color: #f1f5f9;
  }

  .timeline-stage-tag {
    font-size: 10.5px;
    font-weight: 700;
    color: #c4b5fd;
    background: rgba(139, 92, 246, 0.15);
    padding: 1px 5px;
    border-radius: 3px;
  }

  .timeline-time {
    font-size: 11px;
    color: #64748b;
