    padding-top: 4px;
    border-top: 1px solid rgba(255, 255, 255, 0.04);
    font-size: 12px;
    color: #cbd5e1;
  }

  .timeline-details-snippet p {
    margin: 2px 0;
  }

  /* QC Panel */
  .btn-create-qc-primary {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    background: #8b5cf6;
    color: #ffffff;
    border: none;
    border-radius: 6px;
    font-size: 12px;
    font-weight: 700;
    padding: 6px 12px;
    cursor: pointer;
  }

  .qc-issues-grid {
    display: flex;
    flex-direction: column;
    gap: 10px;
  }

  .qc-card {
    background: #0b0816;
    border: 1px solid rgba(255, 255, 255, 0.06);
    border-radius: 8px;
    padding: 12px 14px;
    display: flex;
    flex-direction: column;
    gap: 6px;
  }

  .qc-card.resolved {
    opacity: 0.6;
  }

  .qc-card-top {
    display: flex;
    align-items: center;
    gap: 8px;
  }

  .qc-page-pill {
    font-size: 11px;
    font-weight: 800;
    color: #dfc28d;
    background: rgba(223, 194, 141, 0.15);
    padding: 1px 6px;
    border-radius: 3px;
  }

  .qc-type-pill {
    font-size: 11px;
    font-weight: 700;
    color: #c4b5fd;
    background: rgba(139, 92, 246, 0.15);
    padding: 1px 6px;
    border-radius: 3px;
  }

  .qc-status-badge {
    font-size: 10.5px;
    font-weight: 800;
    padding: 1px 6px;
    border-radius: 3px;
    margin-left: auto;
  }

  .qc-status-badge.status-open {
    background: rgba(239, 68, 68, 0.2);
    color: #f87171;
  }

  .qc-desc-text {
    font-size: 13px;
    color: #cbd5e1;
    margin: 0;
  }

  .qc-card-footer {
    font-size: 11px;
    color: #64748b;
  }

  /* Modals */
  .modal-backdrop {
    position: fixed;
    inset: 0;
    background: rgba(0, 0, 0, 0.7);
    display: flex;
    align-items: center;
    justify-content: center;
    z-index: 1000;
    padding: 16px;
  }

  .modal-card {
    width: 100%;
    max-width: 440px;
    background: #0f0b1e;
    border: 1px solid rgba(255, 255, 255, 0.1);
    border-radius: 12px;
    padding: 20px;
    display: flex;
    flex-direction: column;
    gap: 16px;
  }

  .modal-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
  }

  .modal-title {
    font-size: 16px;
    font-weight: 800;
    color: #f8fafc;
    margin: 0;
  }

  .btn-close-modal {
    background: transparent;
    border: none;
    color: #94a3b8;
    cursor: pointer;
  }

  .modal-body {
    display: flex;
    flex-direction: column;
    gap: 14px;
  }

  .form-group {
    display: flex;
    flex-direction: column;
    gap: 6px;
  }

  .form-label {
    font-size: 12px;
    font-weight: 700;
    color: #cbd5e1;
  }

  .form-select,
  .form-textarea {
    background: #090712;
    border: 1px solid rgba(255, 255, 255, 0.1);
    border-radius: 6px;
    padding: 8px 12px;
    color: #f1f5f9;
    font-size: 13px;
    outline: none;
  }

  .modal-actions {
    display: flex;
    align-items: center;
    justify-content: flex-end;
    gap: 10px;
    margin-top: 6px;
  }

  .btn-cancel {
    background: transparent;
    border: 1px solid rgba(255, 255, 255, 0.1);
    color: #94a3b8;
    padding: 7px 14px;
    border-radius: 6px;
    font-size: 12.5px;
    font-weight: 600;
    cursor: pointer;
  }

  .btn-confirm-return {
    background: #ef4444;
    border: none;
    color: #ffffff;
    padding: 7px 14px;
    border-radius: 6px;
    font-size: 12.5px;
    font-weight: 700;
    cursor: pointer;
  }

  .btn-confirm-return:disabled {
    opacity: 0.4;
    cursor: not-allowed;
  }

  .empty-tab-box,
  .empty-stage-state,
  .notes-placeholder-box {
    padding: 40px 20px;
    text-align: center;
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 10px;
    background: #090712;
    border: 1px dashed rgba(255, 255, 255, 0.08);
    border-radius: 10px;
    color: #94a3b8;
    font-size: 13px;
  }

  .chapter-notes-panel {
    display: grid;
    gap: 1rem;
  }

  .chapter-notes-panel .panel-section-header {
    display: flex;
    align-items: flex-start;
    justify-content: space-between;
    gap: 1rem;
  }

  .note-count-badge,
  .chapter-note-stage,
  .chapter-note-pin {
    display: inline-flex;
    align-items: center;
    gap: 0.25rem;
    white-space: nowrap;
    border-radius: 999px;
    border: 1px solid rgba(167, 139, 250, 0.28);
    background: rgba(124, 58, 237, 0.12);
    color: #ddd6fe;
    font-size: 0.72rem;
    font-weight: 700;
    padding: 0.22rem 0.5rem;
  }

  .chapter-note-highlights,
  .chapter-note-composer,
  .chapter-notes-thread {
    min-width: 0;
    box-sizing: border-box;
  }

  .chapter-note-highlights {
    border: 1px solid rgba(245, 158, 11, 0.25);
    border-radius: 12px;
    background: linear-gradient(135deg, rgba(245, 158, 11, 0.09), rgba(124, 58, 237, 0.06));
    padding: 0.875rem;
  }

  .note-highlight-heading {
    display: flex;
    align-items: center;
    gap: 0.45rem;
    color: #fde68a;
    font-size: 0.78rem;
    font-weight: 800;
    letter-spacing: 0.04em;
    text-transform: uppercase;
    margin-bottom: 0.625rem;
  }

  .note-highlight-list {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(14rem, 1fr));
    gap: 0.5rem;
  }

  .note-highlight-item {
    min-width: 0;
    text-align: left;
    display: grid;
    gap: 0.2rem;
    border: 1px solid rgba(255, 255, 255, 0.08);
    background: rgba(7, 8, 18, 0.58);
    border-radius: 8px;
    padding: 0.6rem 0.7rem;
    color: #e5e7eb;
    cursor: pointer;
  }

  .note-highlight-item:hover { border-color: rgba(251, 191, 36, 0.5); }
  .note-highlight-item span { color: #fbbf24; font-size: 0.72rem; font-weight: 800; text-transform: uppercase; }
  .note-highlight-item strong { overflow-wrap: anywhere; font-size: 0.8rem; line-height: 1.4; }

  .chapter-note-composer {
    border: 1px solid rgba(148, 163, 184, 0.16);
    border-radius: 12px;
    background: rgba(9, 7, 18, 0.72);
    padding: 0.9rem;
    display: grid;
    gap: 0.65rem;
  }

  .note-composer-topline,
  .note-composer-footer,
  .chapter-note-meta,
  .chapter-note-actions {
    display: flex;
    align-items: center;
    gap: 0.55rem;
  }

  .note-composer-topline { justify-content: space-between; }
  .note-composer-topline label { color: #e2e8f0; font-size: 0.84rem; font-weight: 750; }
  .note-composer-topline select,
  .chapter-note-edit-form select {
    color: #e2e8f0;
    background: #0d0c18;
    border: 1px solid rgba(148, 163, 184, 0.22);
    border-radius: 7px;
    padding: 0.36rem 0.5rem;
  }

  .chapter-note-composer textarea,
  .chapter-note-edit-form textarea {
    width: 100%;
    min-height: 5.25rem;
    resize: vertical;
    box-sizing: border-box;
    color: #e5e7eb;
    background: #080711;
    border: 1px solid rgba(148, 163, 184, 0.2);
    border-radius: 8px;
    padding: 0.7rem;
    font: inherit;
    line-height: 1.5;
  }

  .chapter-note-composer textarea:focus,
  .chapter-note-edit-form textarea:focus { outline: 2px solid rgba(139, 92, 246, 0.72); outline-offset: 1px; }
  .note-composer-footer { justify-content: space-between; color: #94a3b8; font-size: 0.76rem; }

  .btn-send-chapter-note,
  .btn-note-inline-save,
  .btn-note-inline-cancel {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 0.35rem;
    min-height: 2.25rem;
    border-radius: 7px;
    padding: 0.45rem 0.72rem;
    border: 1px solid transparent;
    cursor: pointer;
    font: inherit;
    font-size: 0.8rem;
    font-weight: 750;
  }

  .btn-send-chapter-note,
  .btn-note-inline-save { background: #6d28d9; color: white; }
  .btn-send-chapter-note:hover,
  .btn-note-inline-save:hover { background: #7c3aed; }
  .btn-note-inline-cancel { background: transparent; border-color: rgba(148, 163, 184, 0.25); color: #cbd5e1; margin-left: 0.45rem; }

  .chapter-notes-thread { display: grid; gap: 0.65rem; }
  .chapter-note-message {
    display: flex;
    align-items: flex-start;
    gap: 0.7rem;
    min-width: 0;
    padding: 0.85rem;
    border: 1px solid rgba(148, 163, 184, 0.13);
    border-radius: 10px;
    background: rgba(10, 10, 20, 0.7);
  }

  .chapter-note-message.kind-important { border-left: 3px solid #f59e0b; }
  .chapter-note-message.kind-pending { border-left: 3px solid #60a5fa; }
  .chapter-note-message.is-pinned { box-shadow: inset 0 0 0 1px rgba(251, 191, 36, 0.18); }
  .chapter-note-content { flex: 1; min-width: 0; }
  .chapter-note-meta { flex-wrap: wrap; color: #94a3b8; font-size: 0.75rem; }
  .chapter-note-meta strong { color: #f1f5f9; font-size: 0.84rem; }
  .chapter-note-meta time { margin-left: auto; white-space: nowrap; }
  .chapter-note-pin { color: #fde68a; border-color: rgba(245, 158, 11, 0.3); background: rgba(245, 158, 11, 0.1); }
  .chapter-note-body { margin: 0.42rem 0; color: #dbe4f0; line-height: 1.55; overflow-wrap: anywhere; white-space: pre-wrap; }
  .chapter-note-actions { flex-wrap: wrap; margin-top: 0.35rem; }
  .chapter-note-actions form { margin: 0; }
  .chapter-note-actions button { display: inline-flex; align-items: center; gap: 0.25rem; border: 0; padding: 0.2rem 0; background: transparent; color: #a5b4fc; font: inherit; font-size: 0.75rem; cursor: pointer; }
  .chapter-note-actions button:hover { color: #ddd6fe; }
  .chapter-note-actions .note-delete { color: #fda4af; }
  .chapter-note-edit-form { display: grid; gap: 0.45rem; margin: 0.5rem 0; }

  @media (max-width: 640px) {
    .chapter-notes-panel .panel-section-header,
    .note-composer-topline,
    .note-composer-footer { align-items: stretch; flex-direction: column; }
    .note-composer-footer { gap: 0.55rem; }
    .btn-send-chapter-note { width: 100%; }
    .chapter-note-meta time { width: 100%; margin-left: 0; }
    .note-highlight-list { grid-template-columns: 1fr; }
  }

  @media (max-width: 640px) {
    .workspace-nav-bar {
      padding: 10px 14px;
    }
    .workspace-hero {
      padding: 16px 14px;
    }
    .workspace-tab-viewport {
      padding: 14px;
    }
    .stage-hero-bar {
      flex-direction: column;
      align-items: stretch;
    }
    .stage-hero-actions {
      justify-content: space-between;
    }
  }

/* src/routes/scan/components/ChatTab.svelte */
