  }

  .claim-form-full {
    flex: 1;
    min-width: 0;
  }

  .btn-editorial-claim {
    width: 100%;
    height: 42px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 8px;
    background: linear-gradient(135deg, #7c3aed 0%, #6366f1 100%);
    border: 1px solid rgba(255, 255, 255, 0.15);
    border-radius: 8px;
    color: #ffffff;
    font-size: 13px;
    font-weight: 600;
    cursor: pointer;
    transition: all 0.15s ease;
    box-shadow: 0 2px 8px rgba(124, 58, 237, 0.25);
  }

  .btn-editorial-claim:hover:not(:disabled) {
    background: linear-gradient(135deg, #8b5cf6 0%, #4f46e5 100%);
    box-shadow: 0 4px 12px rgba(124, 58, 237, 0.35);
    transform: translateY(-1px);
  }

  .btn-editorial-claim.btn-disabled,
  .btn-editorial-claim:disabled {
    background: rgba(255, 255, 255, 0.05);
    border-color: rgba(255, 255, 255, 0.08);
    color: #64748b;
    cursor: not-allowed;
    box-shadow: none;
    transform: none;
  }

  .btn-icon-zap {
    color: #fbbf24;
  }

  .my-card-actions-row {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    margin-top: 6px;
  }

  .secondary-actions-row {
    display: inline-flex;
    align-items: center;
    gap: 8px;
  }

  /* State A: Complete form takes primary focus */
  .complete-form-primary {
    display: inline-flex;
  }

  .btn-action-complete-prominent {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    height: 38px;
    padding: 0 16px;
    border-radius: 7px;
    font-size: 13px;
    font-weight: 600;
    background: linear-gradient(135deg, #059669 0%, #10b981 100%);
    border: 1px solid rgba(255, 255, 255, 0.15);
    color: #ffffff;
    cursor: pointer;
    transition: all 0.15s ease;
    box-shadow: 0 2px 8px rgba(16, 185, 129, 0.25);
  }

  .btn-action-complete-prominent:hover:not(:disabled) {
    background: linear-gradient(135deg, #047857 0%, #059669 100%);
    box-shadow: 0 4px 12px rgba(16, 185, 129, 0.35);
  }

  .btn-action-complete-prominent:disabled {
    background: rgba(255, 255, 255, 0.05);
    border-color: rgba(255, 255, 255, 0.08);
    color: #64748b;
    cursor: not-allowed;
    box-shadow: none;
  }

  /* State B: Open work takes primary purple focus */
  .btn-action-open-work {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    height: 38px;
    padding: 0 14px;
    border-radius: 7px;
    font-size: 13px;
    font-weight: 600;
    background: linear-gradient(135deg, #7c3aed 0%, #6366f1 100%);
    border: 1px solid rgba(255, 255, 255, 0.15);
    color: #ffffff;
    cursor: pointer;
    transition: all 0.15s ease;
    box-shadow: 0 2px 8px rgba(124, 58, 237, 0.25);
  }

  .btn-action-open-work:hover {
    background: linear-gradient(135deg, #8b5cf6 0%, #4f46e5 100%);
    box-shadow: 0 4px 12px rgba(124, 58, 237, 0.35);
  }

  .btn-action-open-work.active {
    background: rgba(124, 58, 237, 0.25);
    border-color: rgba(124, 58, 237, 0.5);
    color: #d8b4fe;
    box-shadow: none;
  }

  .btn-action-secondary {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    height: 38px;
    padding: 0 12px;
    border-radius: 7px;
    font-size: 12.5px;
    font-weight: 500;
    background: rgba(255, 255, 255, 0.05);
    border: 1px solid rgba(255, 255, 255, 0.1);
    color: #cbd5e1;
    cursor: pointer;
    transition: all 0.15s ease;
  }

  .btn-action-secondary:hover {
    background: rgba(255, 255, 255, 0.08);
    color: #ffffff;
    border-color: rgba(255, 255, 255, 0.2);
  }

  .btn-action-secondary.active {
    background: rgba(255, 255, 255, 0.12);
    color: #ffffff;
  }

  .btn-action-view-details {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    height: 38px;
    padding: 0 12px;
    border-radius: 7px;
    font-size: 12.5px;
    font-weight: 500;
    background: rgba(139, 92, 246, 0.08);
    border: 1px solid rgba(139, 92, 246, 0.25);
    color: #c4b5fd;
    cursor: pointer;
    transition: all 0.15s ease;
    white-space: nowrap;
    text-decoration: none;
  }

  .btn-action-view-details:hover {
    background: rgba(139, 92, 246, 0.2);
    border-color: rgba(139, 92, 246, 0.45);
    color: #ffffff;
  }

  .btn-action-view-details.available-details {
    height: 42px;
  }

  /* --------------------------------------------------------------------------
     4. INTEGRATED EXPANDED WORKSPACE ACCORDION
     -------------------------------------------------------------------------- */
  .editorial-expanded-workspace {
    display: flex;
    flex-direction: column;
    gap: 12px;
    padding-top: 12px;
    border-top: 1px solid rgba(255, 255, 255, 0.08);
    width: 100%;
    animation: fade-in-panel 0.15s ease;
  }

  @keyframes fade-in-panel {
    from { opacity: 0; transform: translateY(-4px); }
    to { opacity: 1; transform: translateY(0); }
  }

  .workspace-subpanel {
    display: flex;
    flex-direction: column;
    background: rgba(10, 13, 24, 0.7);
    border: 1px solid rgba(255, 255, 255, 0.06);
    border-radius: 9px;
    overflow: hidden;
  }

  .subpanel-header-toggle {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 10px 14px;
    background: rgba(255, 255, 255, 0.02);
    border: none;
    width: 100%;
    cursor: pointer;
    color: #f1f5f9;
    transition: background-color 0.15s ease;
  }

  .subpanel-header-toggle:hover {
    background: rgba(255, 255, 255, 0.04);
  }

  .subpanel-title-lockup {
    display: flex;
    align-items: center;
    gap: 8px;
  }

  .subpanel-title {
    font-size: 13px;
    font-weight: 600;
    color: #ffffff;
  }

  .subpanel-count-tag {
    font-size: 11px;
    padding: 1px 6px;
    border-radius: 9999px;
    background: rgba(255, 255, 255, 0.06);
    color: #cbd5e1;
  }

  .subpanel-count-tag.mine {
    background: rgba(168, 85, 247, 0.15);
    color: #d8b4fe;
  }

  .subpanel-chevron {
    color: #94a3b8;
  }

  .subpanel-body {
    padding: 12px 14px;
    border-top: 1px solid rgba(255, 255, 255, 0.04);
    display: flex;
    flex-direction: column;
    gap: 10px;
  }

  /* Typeset Dual Grid */
  .typeset-dual-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 10px;
    width: 100%;
  }

  .dual-input-card {
    display: flex;
    flex-direction: column;
    gap: 8px;
    padding: 10px;
    border-radius: 8px;
    background: rgba(15, 19, 32, 0.6);
    border: 1px solid rgba(255, 255, 255, 0.06);
    box-sizing: border-box;
    width: 100%;
    min-width: 0;
  }

  .dual-input-card.clean-box {
    border-color: rgba(236, 72, 153, 0.2);
  }

  .dual-input-card.trad-box {
    border-color: rgba(59, 130, 246, 0.2);
  }

  .dual-box-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 8px;
    width: 100%;
    box-sizing: border-box;
    min-width: 0;
  }

  .dual-box-title-wrap {
    display: flex;
    align-items: center;
    gap: 6px;
    min-width: 0;
    flex: 1;
  }

  .dual-dot {
    width: 6px;
    height: 6px;
    border-radius: 50%;
    flex-shrink: 0;
  }

  .dual-dot.pink { background: #ec4899; }
  .dual-dot.blue { background: #3b82f6; }

  .dual-box-title {
    font-size: 12px;
    font-weight: 600;
    color: #e2e8f0;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
    min-width: 0;
  }

  .dual-badge {
    font-size: 10.5px;
    padding: 1px 6px;
    border-radius: 4px;
    font-weight: 600;
    flex-shrink: 0;
    white-space: nowrap;
  }

  .dual-badge.pink {
    background: rgba(236, 72, 153, 0.15);
    color: #f472b6;
  }

  .dual-badge.blue {
    background: rgba(59, 130, 246, 0.15);
    color: #60a5fa;
  }

  .files-pill-list {
    display: flex;
    flex-direction: column;
    gap: 6px;
    width: 100%;
    box-sizing: border-box;
  }

  .file-download-item {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 8px;
    padding: 8px 10px;
    background: rgba(255, 255, 255, 0.03);
    border: 1px solid rgba(255, 255, 255, 0.06);
    border-radius: 6px;
    box-sizing: border-box;
    width: 100%;
    min-width: 0;
  }

  .file-main-row {
    display: flex;
    align-items: center;
    gap: 8px;
    min-width: 0;
    flex: 1;
  }

  .file-item-info {
    display: flex;
    flex-direction: column;
    flex: 1;
    min-width: 0;
  }

  .file-item-name {
    font-size: 12px;
    color: #f1f5f9;
    font-weight: 500;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
    display: block;
    max-width: 100%;
  }

  .file-item-sub {
    font-size: 10.5px;
    color: #94a3b8;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
  }

  .btn-file-download {
    display: inline-flex;
    align-items: center;
    gap: 5px;
    padding: 5px 9px;
    border-radius: 5px;
    font-size: 11.5px;
    font-weight: 600;
    text-decoration: none;
    flex-shrink: 0;
    transition: all 0.15s ease;
  }

  .btn-file-download.pink {
    background: rgba(236, 72, 153, 0.15);
    border: 1px solid rgba(236, 72, 153, 0.3);
    color: #f472b6;
  }

  .btn-file-download.blue {
    background: rgba(59, 130, 246, 0.15);
    border: 1px solid rgba(59, 130, 246, 0.3);
    color: #60a5fa;
  }

  .btn-file-download.purple {
    background: rgba(168, 85, 247, 0.15);
    border: 1px solid rgba(168, 85, 247, 0.3);
    color: #d8b4fe;
  }

  .btn-file-download:hover {
    filter: brightness(1.15);
  }

  .dep-waiting-box {
    display: flex;
    align-items: center;
    gap: 7px;
    padding: 8px 10px;
    background: rgba(255, 255, 255, 0.02);
    border: 1px dashed rgba(255, 255, 255, 0.08);
    border-radius: 6px;
    font-size: 11.5px;
    color: #94a3b8;
  }

  .upload-guidance-bar {
    display: flex;
    flex-direction: column;
    gap: 2px;
    margin-bottom: 4px;
  }

  .upload-format-label {
    font-size: 12px;
    font-weight: 600;
    color: #cbd5e1;
  }

  .upload-step-hint {
    font-size: 11.5px;
    color: #94a3b8;
  }

  .upload-component-embed {
    width: 100%;
  }

  .workspace-actions-footer {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 12px;
    padding-top: 8px;
  }

  .btn-release-queue {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    padding: 7px 12px;
    border-radius: 7px;
    font-size: 12px;
    font-weight: 500;
    background: transparent;
    border: 1px solid rgba(255, 255, 255, 0.08);
    color: #94a3b8;
    cursor: pointer;
    transition: all 0.15s ease;
  }

  .btn-release-queue:hover {
    background: rgba(239, 68, 68, 0.1);
    border-color: rgba(239, 68, 68, 0.25);
    color: #fca5a5;
  }

  .btn-concluir-workspace {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    padding: 8px 16px;
    border-radius: 7px;
    font-size: 13px;
    font-weight: 600;
    background: linear-gradient(135deg, #059669 0%, #10b981 100%);
    border: 1px solid rgba(255, 255, 255, 0.15);
    color: #ffffff;
    cursor: pointer;
    transition: all 0.15s ease;
    box-shadow: 0 2px 8px rgba(16, 185, 129, 0.25);
  }

  .btn-concluir-workspace:hover:not(:disabled) {
    background: linear-gradient(135deg, #047857 0%, #059669 100%);
    box-shadow: 0 4px 12px rgba(16, 185, 129, 0.35);
  }

  .btn-concluir-workspace:disabled {
    background: rgba(255, 255, 255, 0.05);
    border-color: rgba(255, 255, 255, 0.08);
    color: #64748b;
    cursor: not-allowed;
    box-shadow: none;
  }

  /* --------------------------------------------------------------------------
     5. CONTEXTUAL COMPACT EMPTY STATES (140–159px)
     -------------------------------------------------------------------------- */
  .editorial-empty-card {
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    text-align: center;
    padding: 24px 20px;
    background: rgba(14, 17, 29, 0.6);
    border: 1px dashed rgba(255, 255, 255, 0.1);
    border-radius: 12px;
    min-height: 140px;
    max-height: 160px;
    gap: 8px;
    box-sizing: border-box;
    width: 100%;
    max-width: 680px;
  }

  .empty-icon-halo {
    width: 36px;
    height: 36px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    background: rgba(255, 255, 255, 0.04);
    box-shadow: 0 0 16px var(--halo-glow, rgba(168, 85, 247, 0.2));
  }

  .empty-icon-halo.neutral {
    box-shadow: 0 0 12px rgba(148, 163, 184, 0.15);
  }

  .empty-text-group {
    display: flex;
    flex-direction: column;
    gap: 3px;
  }

  .empty-card-heading {
    font-size: 14.5px;
    font-weight: 700;
    color: #f1f5f9;
  }

  .empty-card-subtext {
    font-size: 12.5px;
    color: #94a3b8;
    margin: 0;
    max-width: 380px;
  }

  .btn-empty-switch {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    padding: 6px 12px;
    border-radius: 7px;
    font-size: 12px;
    font-weight: 600;
    background: rgba(255, 255, 255, 0.05);
    border: 1px solid rgba(255, 255, 255, 0.1);
    color: #e2e8f0;
    cursor: pointer;
    margin-top: 4px;
    transition: all 0.15s ease;
  }

  .btn-empty-switch.accent {
    background: rgba(255, 255, 255, 0.08);
    border-color: var(--accent-color, #c084fc);
    color: #ffffff;
  }

  .btn-empty-switch:hover {
    background: rgba(255, 255, 255, 0.12);
  }

  /* --------------------------------------------------------------------------
     6. SIDE-BY-SIDE DESKTOP WORKSPACE (WHEN "AMBOS" SELECTED)
     -------------------------------------------------------------------------- */
  .editorial-side-by-side {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 16px;
    width: 100%;
    align-items: start;
  }

  .editorial-side-by-side .editorial-cards-grid {
    grid-template-columns: 1fr;
  }

  .editorial-side-by-side .editorial-cards-grid > :only-child {
    max-width: 100%;
  }

  .side-pool-column {
    display: flex;
    flex-direction: column;
    gap: 10px;
    width: 100%;
  }

  .side-column-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 6px 4px;
  }

  .side-column-title-wrap {
    display: flex;
    align-items: center;
    gap: 8px;
  }

  .side-column-heading {
    font-size: 14px;
    font-weight: 700;
    color: #f1f5f9;
    margin: 0;
  }

  /* Alert Banners */
  .editorial-alert-banner {
    display: flex;
    align-items: center;
    gap: 8px;
    padding: 10px 14px;
    border-radius: 8px;
    font-size: 12.5px;
    margin-bottom: 8px;
  }

  .editorial-alert-banner.error {
    background: rgba(239, 68, 68, 0.12);
    border: 1px solid rgba(239, 68, 68, 0.3);
    color: #fca5a5;
  }

  .editorial-alert-banner.success {
    background: rgba(16, 185, 129, 0.12);
    border: 1px solid rgba(16, 185, 129, 0.3);
    color: #6ee7b7;
  }

  .btn-close-alert {
    margin-left: auto;
    background: transparent;
    border: none;
    color: inherit;
    cursor: pointer;
    padding: 2px;
  }

  /* Spinner */
  .spinner-editorial-xs {
    width: 14px;
    height: 14px;
    border: 2px solid rgba(255, 255, 255, 0.25);
    border-top-color: #ffffff;
    border-radius: 50%;
    animation: spin 0.6s linear infinite;
  }

  @keyframes spin {
    to { transform: rotate(360deg); }
  }

  /* ==========================================================================
     MOBILE RESPONSIVENESS & BREAKPOINTS (ANDROID FIRST)
     ========================================================================== */
  @media (max-width: 1024px) {
    .editorial-cards-grid {
      grid-template-columns: 1fr;
    }

    .editorial-side-by-side {
      grid-template-columns: 1fr;
    }
  }

  @media (max-width: 768px) {
    .editorial-workspace-root {
      gap: 12px;
      padding-bottom: calc(110px + env(safe-area-inset-bottom, 24px)); /* Clearance for fixed mobile bottom navigation */
    }

    .editorial-header {
      padding: 11px 14px;
      gap: 8px;
      min-height: auto;
    }

    .editorial-title {
      font-size: 18px;
    }

    .editorial-subtitle.desktop-sub {
      display: none;
    }

    .editorial-subtitle.mobile-sub {
      display: block;
      font-size: 12px;
    }

    .stage-pill-badge {
      font-size: 10px;
      padding: 2px 7px;
    }

    .editorial-header-meta {
      display: none; /* Hide quick stats on mobile to keep header ultra-compact */
    }

    .editorial-nav-bar {
      flex-direction: column;
      align-items: stretch;
      gap: 10px;
      padding: 8px 10px;
    }

    .segmented-control {
      width: 100%;
      display: grid;
      grid-template-columns: 1fr 1fr;
      box-sizing: border-box;
    }

    .segment-btn {
      justify-content: center;
      padding: 9px 8px;
      font-size: 12.5px;
      min-height: 44px; /* Touch target */
    }

    .desktop-only {
      display: none !important;
    }

    .editorial-filters-toolbar {
      width: 100%;
      flex-direction: column;
      align-items: stretch;
      gap: 6px;
    }

    .mini-search-box {
      width: 100% !important;
    }

    .mini-search-box:focus-within {
      width: 100% !important;
    }

    .mini-search-input {
      width: 100%;
      box-sizing: border-box;
      min-height: 44px;
      font-size: 14px;
    }

    .mini-search-input:focus {
      width: 100%;
    }

    .mini-work-select {
      width: 100%;
      max-width: 100%;
      box-sizing: border-box;
      min-height: 44px;
    }

    .editorial-cards-grid {
      grid-template-columns: 1fr;
      gap: 12px;
    }

    .editorial-card {
      padding: 13px;
      gap: 10px;
      width: 100%;
      max-width: 100% !important;
      box-sizing: border-box;
      min-width: 0;
    }

    .editorial-card.is-expanded {
      max-width: 100% !important;
      width: 100%;
      box-sizing: border-box;
      min-width: 0;
    }

    .card-cover-container {
      width: 52px;
      height: 70px;
    }

    .card-work-title {
      font-size: 15px;
      white-space: normal;
      display: -webkit-box;
      -webkit-line-clamp: 2;
      -webkit-box-orient: vertical;
      line-height: 1.3;
    }

    .typeset-dual-grid {
      grid-template-columns: 1fr;
      gap: 8px;
    }

    .my-card-actions-row {
      width: 100%;
      display: flex;
      flex-direction: column;
      gap: 8px;
    }

    .primary-row-btn {
      width: 100%;
      justify-content: center;
      min-height: 44px;
    }

    .complete-form-primary {
      width: 100%;
    }

    .btn-action-complete-prominent {
      width: 100%;
      justify-content: center;
      min-height: 44px;
    }

    .secondary-actions-row {
      width: 100%;
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 8px;
    }

    .secondary-actions-row.is-single {
      grid-template-columns: 1fr;
    }

    .secondary-actions-row .btn-action-open-work,
    .secondary-actions-row .btn-action-secondary,
    .secondary-actions-row .btn-action-view-details {
      width: 100%;
      justify-content: center;
      min-height: 44px;
    }

    .btn-editorial-claim {
      min-height: 44px; /* Touch friendly on mobile */
    }

    .workspace-actions-footer {
      flex-direction: column;
      align-items: stretch;
      gap: 8px;
    }

    .footer-actions-left,
    .footer-actions-right {
      width: 100%;
    }

    .btn-release-queue,
    .btn-concluir-workspace {
      width: 100%;
      justify-content: center;
      min-height: 44px;
    }
  }

  @media (max-width: 480px) {
    .editorial-header {
      padding: 10px 12px;
    }

    .editorial-title {
      font-size: 17px;
    }

    .editorial-card {
      padding: 11px;
    }

    .card-cover-container {
      width: 50px;
      height: 68px;
    }
  }

  /* ==========================================================================
     REVISOR (QC) SPECIFIC STYLES & INTERACTIVE MODALS
     ========================================================================== */

  .btn-action-secondary.qc-reader-btn {
    border-color: rgba(168, 85, 247, 0.35);
    color: #c084fc;
