/* src/routes/scan/components/PipelineTab.svelte */
.pipeline-view-root {
    padding: 24px;
    display: flex;
    flex-direction: column;
    gap: 20px;
    width: 100%;
    box-sizing: border-box;
  }

  /* Header */
  .pipeline-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 20px;
    flex-wrap: wrap;
    border-bottom: 1px solid rgba(255, 255, 255, 0.06);
    padding-bottom: 18px;
  }

  .title-lockup {
    display: flex;
    align-items: center;
    gap: 14px;
  }

  .icon-bubble {
    width: 44px;
    height: 44px;
    border-radius: 12px;
    background: rgba(139, 92, 246, 0.12);
    border: 1px solid rgba(139, 92, 246, 0.25);
    display: flex;
    align-items: center;
    justify-content: center;
    flex-shrink: 0;
  }

  .page-title {
    font-size: 20px;
    font-weight: 800;
    color: #f8fafc;
    margin: 0;
    letter-spacing: -0.02em;
  }

  .page-subtitle {
    font-size: 13px;
    color: #94a3b8;
    margin: 4px 0 0;
  }

  /* Stats Chips */
  .pipeline-stats-chips {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
  }

  .stat-chip {
    background: rgba(255, 255, 255, 0.03);
    border: 1px solid rgba(255, 255, 255, 0.08);
    border-radius: 8px;
    padding: 6px 12px;
    display: flex;
    align-items: baseline;
    gap: 6px;
    cursor: pointer;
    transition: all 0.15s ease;
  }

  .stat-chip:hover {
    background: rgba(255, 255, 255, 0.06);
    border-color: rgba(255, 255, 255, 0.15);
  }

  .stat-chip.active {
    background: rgba(139, 92, 246, 0.15);
    border-color: rgba(139, 92, 246, 0.4);
  }

  .stat-num {
    font-size: 14px;
    font-weight: 800;
    color: #f1f5f9;
  }

  .stat-lbl {
    font-size: 11.5px;
    color: #94a3b8;
    font-weight: 600;
  }

  /* Controls Bar */
  .pipeline-controls-bar {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 12px;
    flex-wrap: wrap;
  }

  .search-box {
    position: relative;
    display: flex;
    align-items: center;
    flex: 1;
    min-width: 260px;
    max-width: 480px;
  }

  .search-icon {
    position: absolute;
    left: 12px;
    color: #64748b;
    pointer-events: none;
  }

  .search-field {
    width: 100%;
    background: #0d0a18;
    border: 1px solid rgba(255, 255, 255, 0.08);
    border-radius: 8px;
    padding: 8px 32px 8px 36px;
    font-size: 13px;
    color: #f1f5f9;
    outline: none;
    transition: border-color 0.15s;
  }

  .search-field:focus {
    border-color: #8b5cf6;
  }

  .clear-search-btn {
    position: absolute;
    right: 10px;
    background: transparent;
    border: none;
    color: #94a3b8;
    font-size: 16px;
    cursor: pointer;
  }

  .filter-actions {
    display: flex;
    align-items: center;
    gap: 10px;
    flex-wrap: wrap;
  }

  .select-wrapper {
    position: relative;
    display: flex;
    align-items: center;
  }

  .select-icon {
    position: absolute;
    left: 10px;
    color: #64748b;
    pointer-events: none;
  }

  .filter-select {
    background: #0d0a18;
    border: 1px solid rgba(255, 255, 255, 0.08);
    border-radius: 8px;
    padding: 8px 12px 8px 32px;
    font-size: 13px;
    color: #f1f5f9;
    outline: none;
    cursor: pointer;
  }

  .filter-select:focus {
    border-color: #8b5cf6;
  }

  /* Chapters List */
  .pipeline-chapters-container {
    display: flex;
    flex-direction: column;
    gap: 12px;
  }

  .chapters-vertical-list {
    display: flex;
    flex-direction: column;
    gap: 14px;
  }

  /* Chapter Card */
  .chapter-pipeline-card {
    background: #0b0816;
    border: 1px solid rgba(255, 255, 255, 0.07);
    border-radius: 12px;
    padding: 16px 20px;
    display: flex;
    flex-direction: column;
    gap: 14px;
    transition: border-color 0.2s, background 0.2s, box-shadow 0.2s;
  }

  .chapter-pipeline-card:hover {
    border-color: rgba(139, 92, 246, 0.35);
    background: #0f0b1e;
    box-shadow: 0 4px 20px rgba(0, 0, 0, 0.3);
  }

  /* Card Header */
  .card-main-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 16px;
    flex-wrap: wrap;
  }

  .work-badge-cluster {
    display: flex;
    align-items: center;
    gap: 12px;
    min-width: 0;
  }

  .work-thumb-mini {
    width: 36px;
    height: 48px;
    border-radius: 6px;
    overflow: hidden;
    background: #141026;
    display: flex;
    align-items: center;
    justify-content: center;
    flex-shrink: 0;
    border: 1px solid rgba(255, 255, 255, 0.08);
  }

  .work-thumb-img {
    width: 100%;
    height: 100%;
    object-fit: cover;
  }

  .work-details-text {
    display: flex;
    flex-direction: column;
    gap: 2px;
    min-width: 0;
  }

  .work-title-row {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
  }

  .work-series-name {
    font-size: 13.5px;
    font-weight: 700;
    color: #e2e8f0;
  }

  .chapter-tag {
    font-size: 11.5px;
    font-weight: 800;
    color: #dfc28d;
    background: rgba(223, 194, 141, 0.12);
    padding: 2px 8px;
    border-radius: 4px;
    border: 1px solid rgba(223, 194, 141, 0.25);
  }

  .chapter-sub-heading {
    font-size: 13px;
    font-weight: 600;
    color: #94a3b8;
    margin: 0;
  }

  .card-top-actions {
    display: flex;
    align-items: center;
    gap: 12px;
    flex-shrink: 0;
  }

  .status-indicator-tag {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    font-size: 11.5px;
    font-weight: 700;
    padding: 3px 9px;
    border-radius: 6px;
  }

  .status-dot {
    width: 6px;
    height: 6px;
    border-radius: 50%;
  }

  .status-indicator-tag.status-in_progress {
    background: rgba(245, 158, 11, 0.12);
    color: #fbbf24;
    border: 1px solid rgba(245, 158, 11, 0.25);
  }
  .status-indicator-tag.status-in_progress .status-dot {
    background: #fbbf24;
  }

  .status-indicator-tag.status-ready {
    background: rgba(56, 189, 248, 0.12);
    color: #38bdf8;
    border: 1px solid rgba(56, 189, 248, 0.25);
  }
  .status-indicator-tag.status-ready .status-dot {
    background: #38bdf8;
  }

  .status-indicator-tag.status-published {
    background: rgba(16, 185, 129, 0.12);
    color: #34d399;
    border: 1px solid rgba(16, 185, 129, 0.25);
  }
  .status-indicator-tag.status-published .status-dot {
    background: #34d399;
  }

  .btn-open-workspace {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    background: rgba(139, 92, 246, 0.12);
    border: 1px solid rgba(139, 92, 246, 0.3);
    color: #c4b5fd;
    font-size: 12px;
    font-weight: 700;
    padding: 6px 12px;
    border-radius: 6px;
    cursor: pointer;
    transition: all 0.15s ease;
  }

  .btn-open-workspace:hover {
    background: #8b5cf6;
    color: #ffffff;
    border-color: #8b5cf6;
  }

  /* Compact 9-Stage Stepper */
  .stages-stepper-viewport {
    width: 100%;
    overflow-x: auto;
    padding: 8px 0;
  }

  .stages-stepper-track {
    display: flex;
    align-items: center;
    gap: 4px;
    min-width: 720px;
  }

  .stepper-step {
    display: flex;
    align-items: center;
    gap: 8px;
    flex: 1;
    position: relative;
  }

  .step-node-bubble {
    width: 22px;
    height: 22px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    flex-shrink: 0;
    background: #141026;
    border: 1.5px solid #334155;
    color: #64748b;
    transition: all 0.15s;
  }

  .stepper-step.is-done .step-node-bubble {
    background: rgba(16, 185, 129, 0.18);
    border-color: #10b981;
    color: #34d399;
  }

  .stepper-step.is-progress .step-node-bubble {
    background: rgba(245, 158, 11, 0.18);
    border-color: #f59e0b;
    color: #fbbf24;
    box-shadow: 0 0 10px rgba(245, 158, 11, 0.4);
  }

  .pulse-dot {
    width: 8px;
    height: 8px;
    border-radius: 50%;
    background: #fbbf24;
    animation: pulse 1.8s infinite;
  }

  .open-circle {
    width: 8px;
    height: 8px;
    border-radius: 50%;
    border: 2px solid #38bdf8;
  }

  .stepper-step.is-available .step-node-bubble {
    background: rgba(56, 189, 248, 0.12);
    border-color: #38bdf8;
    color: #38bdf8;
  }

  .stepper-step.is-rework .step-node-bubble {
    background: rgba(239, 68, 68, 0.18);
    border-color: #ef4444;
    color: #f87171;
  }

  .stepper-step.is-blocked .step-node-bubble {
    background: rgba(255, 255, 255, 0.03);
    border-color: rgba(255, 255, 255, 0.1);
    color: #475569;
  }

  .step-meta-box {
    display: flex;
    flex-direction: column;
    min-width: 0;
  }

  .step-name {
    font-size: 11px;
    font-weight: 800;
    color: #cbd5e1;
    letter-spacing: 0.02em;
    white-space: nowrap;
  }

  .stepper-step.is-done .step-name {
    color: #34d399;
  }

  .stepper-step.is-progress .step-name {
    color: #fbbf24;
  }

  .stepper-step.is-rework .step-name {
    color: #f87171;
  }

  .step-assignee {
    font-size: 10px;
    color: #c4b5fd;
    font-weight: 600;
    max-width: 70px;
  }

  .step-status-sub {
    font-size: 9.5px;
    color: #64748b;
  }

  .step-line {
    flex: 1;
    height: 2px;
    background: rgba(255, 255, 255, 0.08);
    margin: 0 4px;
    border-radius: 1px;
  }

  .step-line.line-filled {
    background: #10b981;
  }

  /* Card Footer Meta */
  .card-footer-meta {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 12px;
    border-top: 1px solid rgba(255, 255, 255, 0.04);
    padding-top: 10px;
    flex-wrap: wrap;
  }

  .meta-tags-left {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
  }

  .meta-tag {
    display: inline-flex;
    align-items: center;
    gap: 4px;
    font-size: 11px;
    color: #94a3b8;
    background: rgba(255, 255, 255, 0.03);
    padding: 3px 7px;
    border-radius: 4px;
  }

  .meta-tag.qc-tag {
    background: rgba(239, 68, 68, 0.12);
    color: #f87171;
    border: 1px solid rgba(239, 68, 68, 0.25);
    font-weight: 700;
  }

  .meta-tag.tasks-tag {
    background: rgba(139, 92, 246, 0.12);
    color: #c4b5fd;
    font-weight: 600;
  }

  .mobile-open-link {
    display: none;
    align-items: center;
    gap: 6px;
    font-size: 12px;
    font-weight: 700;
    color: #8b5cf6;
    background: transparent;
    border: none;
    cursor: pointer;
  }

  /* Empty State */
  .pipeline-empty-state {
    padding: 48px 24px;
    background: #090712;
    border: 1px dashed rgba(255, 255, 255, 0.08);
    border-radius: 12px;
    text-align: center;
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 12px;
  }

  .empty-icon-circle {
    width: 64px;
    height: 64px;
    border-radius: 50%;
    background: rgba(139, 92, 246, 0.1);
    display: flex;
    align-items: center;
    justify-content: center;
  }

  .empty-title {
    font-size: 16px;
    font-weight: 700;
    color: #f1f5f9;
    margin: 0;
  }

  .empty-desc {
    font-size: 13px;
    color: #94a3b8;
    max-width: 440px;
    margin: 0;
    line-height: 1.5;
  }

  @keyframes pulse {
    0% { transform: scale(0.95); opacity: 0.8; }
    50% { transform: scale(1.15); opacity: 1; }
    100% { transform: scale(0.95); opacity: 0.8; }
  }

  /* Mobile Responsiveness */
  @media (max-width: 768px) {
    .pipeline-view-root {
      padding: 14px;
      gap: 14px;
    }

    .pipeline-header {
      flex-direction: column;
      align-items: flex-start;
      gap: 12px;
    }

    .pipeline-controls-bar {
      flex-direction: column;
      align-items: stretch;
    }

    .search-box {
      max-width: 100%;
      min-width: 100%;
    }

    .filter-actions {
      width: 100%;
      justify-content: space-between;
    }

    .filter-select {
      flex: 1;
    }

    .chapter-pipeline-card {
      padding: 14px;
    }

    .card-top-actions .btn-open-workspace {
      display: none;
    }

    .mobile-open-link {
      display: inline-flex;
      width: 100%;
      justify-content: flex-end;
      padding-top: 4px;
    }
  }

