    transition: all 0.15s ease;
  }
  .stage-tab-btn:hover {
    color: #f1f5f9;
    background: rgba(255, 255, 255, 0.04);
  }
  .stage-tab-btn.is-active {
    background: rgba(6, 182, 212, 0.12);
    border-color: rgba(6, 182, 212, 0.35);
    color: #22d3ee;
    font-weight: 600;
  }
  .stage-tab-count {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    min-width: 1.15rem;
    padding: 1px 6px;
    height: 1.15rem;
    border-radius: 9999px;
    background: rgba(139, 92, 246, 0.22);
    border: 1px solid rgba(139, 92, 246, 0.35);
    color: #c4b5fd;
    font-size: 0.6875rem;
    font-weight: 700;
    line-height: 1;
  }
  .stage-tab-btn.is-active .stage-tab-count {
    background: rgba(6, 182, 212, 0.25);
    border-color: rgba(6, 182, 212, 0.45);
    color: #67e8f9;
  }

  /* 3. QUEUE MAIN SECTION */
  .queue-main-section {
    display: flex;
    flex-direction: column;
    gap: 1rem;
  }
  .queue-header-row {
    display: flex;
    align-items: center;
    justify-content: space-between;
  }
  .queue-heading-lockup {
    display: flex;
    align-items: center;
    gap: 0.65rem;
  }
  .queue-heading-icon {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 28px;
    height: 28px;
    border-radius: 8px;
    background: rgba(6, 182, 212, 0.12);
    color: #22d3ee;
    border: 1px solid rgba(6, 182, 212, 0.25);
  }
  .queue-heading-text {
    font-size: 1.05rem;
    font-weight: 600;
    color: #f8fafc;
    margin: 0;
  }
  .queue-heading-count {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    padding: 1px 7px;
    border-radius: 9999px;
    background: rgba(139, 92, 246, 0.22);
    border: 1px solid rgba(139, 92, 246, 0.35);
    color: #c4b5fd;
    font-size: 0.75rem;
    font-weight: 700;
    line-height: 1.2;
  }

  /* CLEAN EMPTY BOX */
  .clean-empty-box {
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    text-align: center;
    padding: 3.5rem 1.5rem;
    background: #111522;
    border: 1px dashed #232a3f;
    border-radius: 12px;
  }
  .empty-icon-circle {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 54px;
    height: 54px;
    border-radius: 50%;
    background: rgba(6, 182, 212, 0.1);
    color: #22d3ee;
    border: 1px solid rgba(6, 182, 212, 0.2);
    margin-bottom: 1rem;
  }
  .empty-heading {
    font-size: 1.05rem;
    font-weight: 600;
    color: #f1f5f9;
    margin: 0 0 0.4rem 0;
  }
  .empty-sub {
    font-size: 0.85rem;
    color: #94a3b8;
    max-width: 480px;
    margin: 0;
    line-height: 1.45;
  }

  /* CARDS STACK */
  .cards-stack {
    display: flex;
    flex-direction: column;
    gap: 0.9rem;
  }
  .pub-card {
    background: #121624;
    border: 1px solid #1e2436;
    border-radius: 12px;
    padding: 1.15rem 1.25rem;
    display: flex;
    flex-direction: column;
    gap: 1rem;
    transition: border-color 0.15s ease, box-shadow 0.15s ease;
  }
  .pub-card:hover {
    border-color: #2b354d;
  }
  .pub-card.is-expanded {
    border-color: rgba(6, 182, 212, 0.4);
    box-shadow: 0 4px 20px rgba(0, 0, 0, 0.35);
  }

  /* Card Top Row */
  .pub-card-header-bar {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 1.25rem;
    min-width: 0;
  }
  .card-left-identity {
    display: flex;
    align-items: center;
    gap: 1rem;
    min-width: 0;
    flex: 1;
  }
  .work-cover-box {
    width: 52px;
    height: 68px;
    border-radius: 8px;
    overflow: hidden;
    background: #1a2030;
    border: 1px solid #232a3f;
    flex-shrink: 0;
  }
  .cover-image {
    width: 100%;
    height: 100%;
    object-fit: cover;
  }
  .cover-placeholder {
    width: 100%;
    height: 100%;
    display: flex;
    align-items: center;
    justify-content: center;
    color: #64748b;
    font-size: 0.75rem;
    font-weight: 700;
  }

  .chapter-info-cluster {
    display: flex;
    flex-direction: column;
    gap: 0.3rem;
    min-width: 0;
  }
  .work-title {
    font-size: 0.9375rem;
    font-weight: 700;
    color: #ffffff;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
  }
  .chapter-identity {
    font-size: 0.85rem;
    font-weight: 600;
    color: #22d3ee;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
  }

  .card-meta-pills {
    display: flex;
    align-items: center;
    gap: 0.45rem;
    flex-wrap: wrap;
    margin-top: 0.15rem;
  }
  .meta-pill {
    display: inline-flex;
    align-items: center;
    gap: 0.3rem;
    padding: 0.15rem 0.5rem;
    border-radius: 5px;
    font-size: 0.72rem;
    font-weight: 600;
  }
  .meta-pill.is-valid {
    background: rgba(16, 185, 129, 0.12);
    border: 1px solid rgba(16, 185, 129, 0.3);
    color: #34d399;
  }
  .meta-pill.is-warning {
    background: rgba(245, 158, 11, 0.12);
    border: 1px solid rgba(245, 158, 11, 0.32);
    color: #fbbf24;
  }
  .meta-pill.is-conferred {
    background: rgba(6, 182, 212, 0.14);
    border: 1px solid rgba(6, 182, 212, 0.35);
    color: #22d3ee;
  }
  .pill-text-desktop {
    display: inline;
  }
  .pill-text-mobile {
    display: none;
  }
  @media (max-width: 900px) {
    .pill-text-desktop {
      display: none;
    }
    .pill-text-mobile {
      display: inline;
    }
  }
  .meta-pill.is-pkg {
    background: rgba(148, 163, 184, 0.1);
    border: 1px solid rgba(148, 163, 184, 0.2);
    color: #cbd5e1;
  }

  /* Card Actions Bar */
  .card-actions-bar {
    display: flex;
    align-items: center;
    gap: 0.65rem;
    flex-shrink: 0;
  }

  /* 1. Conferir Capítulo (Primary Action) */
  .btn-action-conferir {
    display: inline-flex;
    align-items: center;
    gap: 0.45rem;
    padding: 0.55rem 1rem;
    border-radius: 8px;
    background: rgba(6, 182, 212, 0.12);
    border: 1px solid rgba(6, 182, 212, 0.35);
    color: #22d3ee;
    font-size: 0.8125rem;
    font-weight: 600;
    cursor: pointer;
    transition: all 0.15s ease;
    min-height: 40px;
  }
  .btn-action-conferir:hover {
    background: rgba(6, 182, 212, 0.22);
    border-color: #06b6d4;
    color: #ffffff;
  }

  /* 2. Ver Detalhes Toggle */
  .btn-action-details {
    display: inline-flex;
    align-items: center;
    gap: 0.4rem;
    padding: 0.55rem 0.85rem;
    border-radius: 8px;
    background: #161b2a;
    border: 1px solid #232a3f;
    color: #94a3b8;
    font-size: 0.8125rem;
    font-weight: 500;
    cursor: pointer;
    transition: all 0.15s ease;
    min-height: 40px;
  }
  .btn-action-details:hover {
    color: #f1f5f9;
    border-color: #334155;
  }
  .chevron-rotator {
    display: inline-flex;
    transition: transform 0.2s ease;
  }
  .chevron-rotator.is-flipped {
    transform: rotate(180deg);
  }

  /* 3. Publicar no Catálogo / Bloqueado */
  .btn-action-publish {
    display: inline-flex;
    align-items: center;
    gap: 0.45rem;
    padding: 0.55rem 1.15rem;
    border-radius: 8px;
    font-size: 0.8125rem;
    font-weight: 600;
    cursor: pointer;
    transition: all 0.15s ease;
    margin-left: auto;
    min-height: 40px;
  }
  .btn-action-publish.is-ready {
    background: linear-gradient(135deg, #059669 0%, #10b981 100%);
    border: 1px solid #10b981;
    color: #ffffff;
    box-shadow: 0 2px 10px rgba(16, 185, 129, 0.25);
  }
  .btn-action-publish.is-ready:hover {
    background: linear-gradient(135deg, #047857 0%, #059669 100%);
    box-shadow: 0 4px 14px rgba(16, 185, 129, 0.4);
    transform: translateY(-1px);
  }
  .btn-action-publish.is-blocked {
    background: rgba(239, 68, 68, 0.08);
    border: 1px solid rgba(239, 68, 68, 0.28);
    color: #fca5a5;
    cursor: not-allowed;
    opacity: 0.85;
  }
  .badge-waiting-admin {
    display: inline-flex;
    align-items: center;
    gap: 0.35rem;
    padding: 0.4rem 0.75rem;
    border-radius: 6px;
    background: rgba(148, 163, 184, 0.08);
    border: 1px solid rgba(148, 163, 184, 0.2);
    color: #94a3b8;
    font-size: 0.75rem;
    margin-left: auto;
  }

  /* CARD EXPANDED CONTENT */
  .card-details-panel {
    padding-top: 1rem;
    border-top: 1px solid #1a2032;
    animation: fadeIn 0.2s ease;
  }
  .details-grid {
    display: grid;
    grid-template-columns: repeat(2, 1fr);
    gap: 0.85rem;
  }
  .details-panel-card {
    background: #0f131f;
    border: 1px solid #1b2133;
    border-radius: 10px;
    padding: 0.85rem 1rem;
    display: flex;
    flex-direction: column;
    gap: 0.65rem;
  }
  .details-panel-card.full-span {
    grid-column: 1 / -1;
  }
  .panel-card-title {
    display: flex;
    align-items: center;
    gap: 0.45rem;
    font-size: 0.8125rem;
    font-weight: 600;
    color: #cbd5e1;
    margin: 0;
  }

  .meta-kv-list {
    display: flex;
    flex-direction: column;
    gap: 0.35rem;
    margin: 0;
    font-size: 0.8rem;
  }
  .kv-row {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 0.5rem;
  }
  .kv-row dt { color: #64748b; }
  .kv-row dd { color: #e2e8f0; margin: 0; }

  .inline-stage-tag {
    display: inline-flex;
    padding: 0.1rem 0.45rem;
    border-radius: 4px;
    font-size: 0.72rem;
    font-weight: 600;
  }
  .inline-stage-tag.cyan {
    background: rgba(6, 182, 212, 0.15);
    color: #22d3ee;
    border: 1px solid rgba(6, 182, 212, 0.3);
  }

  .primary-pkg-box {
    display: flex;
    align-items: center;
    gap: 0.65rem;
    background: #141926;
    border: 1px solid #20273c;
    border-radius: 8px;
    padding: 0.55rem 0.75rem;
  }
  .primary-pkg-box.is-incomplete {
    border-color: rgba(245, 158, 11, 0.35);
    background: rgba(245, 158, 11, 0.05);
  }
  .pkg-icon-wrap {
    display: flex;
    align-items: center;
    justify-content: center;
  }
  .pkg-txt {
    display: flex;
    flex-direction: column;
    gap: 0.15rem;
    min-width: 0;
  }
  .pkg-name {
    font-size: 0.8125rem;
    font-weight: 600;
    color: #f1f5f9;
    word-break: break-word;
    overflow-wrap: anywhere;
    line-height: 1.35;
  }
  .status-indicator-inline {
    display: inline-flex;
    align-items: center;
    gap: 0.35rem;
    font-size: 0.8rem;
    font-weight: 600;
  }
  .status-indicator-inline.amber {
    color: #fbbf24;
  }
  .status-indicator-inline.emerald {
    color: #34d399;
  }
  .status-indicator-inline.cyan {
    color: #22d3ee;
  }
  .status-indicator-inline.slate {
    color: #94a3b8;
  }
  .pkg-meta-line {
    font-size: 0.72rem;
    color: #94a3b8;
    display: flex;
    align-items: center;
    gap: 0.35rem;
  }
  .deliverables-count-strip {
    font-size: 0.75rem;
    color: #64748b;
    margin-top: 0.2rem;
  }
  .no-files-notice {
    font-size: 0.8rem;
    color: #64748b;
    margin: 0;
  }

  .destiny-box {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 1rem;
    flex-wrap: wrap;
  }
  .destiny-text {
    font-size: 0.8125rem;
    color: #cbd5e1;
    line-height: 1.4;
    flex: 1;
  }
  .destiny-text p { margin: 0; }
  .blocked-publish-notice {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    background: rgba(245, 158, 11, 0.08);
    border: 1px solid rgba(245, 158, 11, 0.25);
    border-radius: 8px;
    padding: 0.55rem 0.85rem;
    color: #fcd34d;
    font-size: 0.78rem;
    flex-wrap: wrap;
  }
  .btn-open-sim-test {
    background: transparent;
    border: 1px solid #fcd34d;
    color: #fef08a;
    padding: 0.25rem 0.55rem;
    border-radius: 5px;
    font-size: 0.72rem;
    font-weight: 600;
    cursor: pointer;
  }
  .btn-action-publish.in-panel {
    margin-left: 0;
  }

  /* 4. MODAL / BOTTOM SHEET */
  .modal-backdrop {
    position: fixed;
    inset: 0;
    background: rgba(0, 0, 0, 0.75);
    backdrop-filter: blur(4px);
    display: flex;
    align-items: center;
    justify-content: center;
    z-index: 9999;
    padding: 1.25rem;
    overflow-y: auto;
  }
  .publish-modal-card {
    background: #121624;
    border: 1px solid #232b40;
    border-radius: 16px;
    width: 100%;
    max-width: 640px;
    box-shadow: 0 16px 40px rgba(0, 0, 0, 0.6);
    display: flex;
    flex-direction: column;
    max-height: 90vh;
    overflow: hidden;
    animation: modalPop 0.25s ease;
  }
  .modal-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 1.15rem 1.35rem;
    border-bottom: 1px solid #1e2436;
    background: #161b2b;
  }
  .modal-header-left {
    display: flex;
    align-items: center;
    gap: 0.85rem;
  }
  .modal-icon-badge {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 38px;
    height: 38px;
    border-radius: 10px;
    background: rgba(16, 185, 129, 0.12);
    border: 1px solid rgba(16, 185, 129, 0.25);
  }
  .modal-title {
    font-size: 1.05rem;
    font-weight: 700;
    color: #ffffff;
    margin: 0;
  }
  .modal-subtitle {
    font-size: 0.78rem;
    color: #94a3b8;
    margin: 0.15rem 0 0 0;
  }
  .btn-modal-close {
    background: transparent;
    border: none;
    color: #94a3b8;
    cursor: pointer;
    padding: 6px;
    border-radius: 6px;
    display: flex;
  }
  .btn-modal-close:hover {
    color: #ffffff;
    background: rgba(255, 255, 255, 0.06);
  }

  .modal-form {
    display: flex;
    flex-direction: column;
    overflow: hidden;
    flex: 1;
  }
  .modal-scrollable-body {
    padding: 1.15rem 1.35rem;
    overflow-y: auto;
    display: flex;
    flex-direction: column;
    gap: 1.15rem;
  }
  .modal-form-block {
    border: 1px solid #1e2436;
    border-radius: 12px;
    padding: 1rem;
    margin: 0;
    background: #151928;
  }
  .block-legend {
    display: flex;
    align-items: center;
    gap: 0.45rem;
    font-size: 0.8125rem;
    font-weight: 700;
    color: #22d3ee;
    padding: 0 0.4rem;
  }
  .legend-number {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 18px;
    height: 18px;
    border-radius: 50%;
    background: rgba(6, 182, 212, 0.2);
    color: #22d3ee;
    font-size: 0.72rem;
  }

  .form-fields-grid {
    display: grid;
    grid-template-columns: repeat(2, 1fr);
    gap: 0.85rem;
    margin-top: 0.5rem;
  }
  .form-group {
    display: flex;
    flex-direction: column;
    gap: 0.25rem;
  }
  .form-group.full-col { grid-column: 1 / -1; }
  .form-group.half-col { grid-column: span 1; }

  .field-label {
    font-size: 0.78rem;
    font-weight: 600;
    color: #cbd5e1;
    display: flex;
    align-items: center;
    gap: 0.2rem;
  }
  .required-star { color: #f43f5e; }
  .field-hint {
    font-size: 0.72rem;
    color: #64748b;
  }
  .field-input, .field-select {
    background: #111420;
    border: 1px solid #232a3f;
    border-radius: 8px;
    padding: 0.5rem 0.75rem;
    color: #ffffff;
    font-size: 0.85rem;
    outline: none;
  }
  .field-input:focus, .field-select:focus {
    border-color: #06b6d4;
    box-shadow: 0 0 0 2px rgba(6, 182, 212, 0.2);
  }

  .material-summary-card {
    background: #111420;
    border: 1px solid #1e2436;
    border-radius: 8px;
    padding: 0.75rem;
    display: flex;
    flex-direction: column;
    gap: 0.35rem;
    margin-top: 0.5rem;
  }
  .summary-line {
    display: flex;
    align-items: center;
    justify-content: space-between;
    font-size: 0.78rem;
  }
  .summary-key { color: #64748b; }
  .summary-val { color: #e2e8f0; }

  /* Security Alert Boxes */
  .security-alert-box {
    border-radius: 10px;
    padding: 0.75rem 0.95rem;
    display: flex;
    flex-direction: column;
    gap: 0.4rem;
    margin-top: 0.5rem;
  }
  .security-alert-box.is-valid {
    background: rgba(16, 185, 129, 0.08);
    border: 1px solid rgba(16, 185, 129, 0.25);
  }
  .security-alert-box.is-warning {
    background: rgba(245, 158, 11, 0.08);
    border: 1px solid rgba(245, 158, 11, 0.28);
  }
  .security-alert-box.is-error {
    background: rgba(239, 68, 68, 0.08);
    border: 1px solid rgba(239, 68, 68, 0.3);
  }
  .security-alert-box.server-error {
    background: rgba(239, 68, 68, 0.15);
    border-color: #ef4444;
  }
  .alert-header {
    display: flex;
    align-items: center;
    gap: 0.45rem;
  }
  .alert-title {
    font-size: 0.8125rem;
    font-weight: 700;
    margin: 0;
  }
  .security-alert-box.is-valid .alert-title { color: #34d399; }
  .security-alert-box.is-warning .alert-title { color: #fbbf24; }
  .security-alert-box.is-error .alert-title { color: #f87171; }
  .alert-desc {
    font-size: 0.78rem;
    color: #94a3b8;
    margin: 0;
    line-height: 1.35;
  }
  .confirm-duplicate-label {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    font-size: 0.78rem;
    color: #cbd5e1;
    cursor: pointer;
    margin-top: 0.35rem;
    padding-top: 0.35rem;
    border-top: 1px solid rgba(255, 255, 255, 0.08);
  }
  .confirm-checkbox {
    accent-color: #10b981;
    cursor: pointer;
  }

  /* Simulation toggle card */
  .simulation-toggle-card {
    background: rgba(16, 185, 129, 0.06);
    border: 1px solid rgba(16, 185, 129, 0.22);
    border-radius: 10px;
    padding: 0.75rem 0.95rem;
    margin-top: 0.5rem;
    transition: all 0.2s ease;
  }
  .simulation-toggle-card.is-active {
    background: rgba(16, 185, 129, 0.1);
    border-color: rgba(16, 185, 129, 0.4);
  }
  .simulation-toggle-label {
    display: flex;
    align-items: flex-start;
    gap: 0.65rem;
    cursor: pointer;
  }
  .simulation-checkbox {
    accent-color: #10b981;
    margin-top: 0.15rem;
    cursor: pointer;
  }
  .simulation-text-wrap {
    display: flex;
    flex-direction: column;
    gap: 0.15rem;
  }
  .simulation-title-row {
    display: flex;
    align-items: center;
    gap: 0.45rem;
  }
  .simulation-title {
    font-size: 0.8125rem;
    font-weight: 700;
    color: #ecfdf5;
  }
  .simulation-badge {
    font-size: 0.65rem;
    font-weight: 700;
    text-transform: uppercase;
    padding: 0.08rem 0.4rem;
    border-radius: 4px;
    background: rgba(16, 185, 129, 0.2);
    color: #34d399;
    border: 1px solid rgba(16, 185, 129, 0.3);
  }
  .simulation-desc {
    font-size: 0.75rem;
    color: #94a3b8;
    margin: 0;
    line-height: 1.35;
  }

  /* Modal Footer */
  .modal-footer {
    display: flex;
    flex-direction: column;
    gap: 0.85rem;
    padding: 1rem 1.35rem;
    border-top: 1px solid #1e2436;
    background: #161b2b;
  }
  .cta-summary-note {
