    color: #ffffff;
    font-size: 0.82rem;
    font-weight: 600;
    padding: 0.5rem 0.9rem;
    border-radius: 8px;
    text-decoration: none;
    transition: all 0.15s ease;
    border: 1px solid rgba(34, 197, 94, 0.4);
    min-height: 38px;
    box-sizing: border-box;
  }

  .btn-read-chapter:hover {
    background: #16a34a;
    box-shadow: 0 2px 10px rgba(34, 197, 94, 0.3);
  }

  .btn-read-chapter.is-demo-disabled {
    background: #1e293b;
    border: 1px dashed rgba(148, 163, 184, 0.3);
    color: #94a3b8;
    cursor: not-allowed;
    opacity: 0.85;
  }

  .btn-read-chapter.is-demo-disabled:hover {
    background: #1e293b;
    box-shadow: none;
  }

  .btn-toggle-details {
    display: inline-flex;
    align-items: center;
    gap: 0.35rem;
    background: #1e293b;
    border: 1px solid #334155;
    color: #cbd5e1;
    font-size: 0.8rem;
    font-weight: 500;
    padding: 0.5rem 0.75rem;
    border-radius: 8px;
    cursor: pointer;
    transition: all 0.15s ease;
    min-height: 38px;
    box-sizing: border-box;
  }

  .btn-toggle-details:hover {
    background: #334155;
    color: #ffffff;
  }

  .btn-toggle-details.is-active {
    background: #334155;
    border-color: #64748b;
    color: #ffffff;
  }

  /* -------------------------------------------------------------
     5. EXPANDED DETAILS ACCORDION (Item 5)
     ------------------------------------------------------------- */
  .card-expanded-panel {
    background: rgba(15, 23, 42, 0.95);
    border-top: 1px solid #1e293b;
    padding: 1rem 1.25rem;
    display: flex;
    flex-direction: column;
    gap: 1rem;
    animation: fadeIn 0.15s ease;
  }

  @keyframes fadeIn {
    from { opacity: 0; transform: translateY(-4px); }
    to { opacity: 1; transform: translateY(0); }
  }

  /* TIER 1: Informações principais */
  .tier1-main-info {
    display: flex;
    flex-direction: column;
    gap: 0.65rem;
  }

  .tier-section-badge {
    display: inline-flex;
    align-items: center;
    gap: 0.35rem;
    font-size: 0.74rem;
    font-weight: 700;
    color: #38bdf8;
    text-transform: uppercase;
    letter-spacing: 0.05em;
  }

  .tier-badge-ico {
    color: #38bdf8;
  }

  .main-info-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));
    gap: 0.75rem 1.25rem;
    background: rgba(30, 41, 59, 0.35);
    border: 1px solid rgba(51, 65, 85, 0.4);
    border-radius: 8px;
    padding: 0.85rem 1rem;
  }

  .info-kv-cell {
    display: flex;
    flex-direction: column;
    gap: 0.15rem;
  }

  .info-kv-label {
    font-size: 0.72rem;
    color: #64748b;
    font-weight: 500;
    text-transform: uppercase;
    letter-spacing: 0.03em;
  }

  .info-kv-value {
    font-size: 0.82rem;
    color: #f1f5f9;
    font-weight: 500;
  }

  .highlight-value {
    color: #f8fafc;
  }

  .rel-time-sub {
    color: #94a3b8;
    font-size: 0.75rem;
    margin-left: 0.25rem;
  }

  .friendly-catalog-link {
    display: inline-flex;
    align-items: center;
    gap: 0.3rem;
    color: #38bdf8;
    text-decoration: none;
    font-weight: 500;
    transition: color 0.12s ease;
  }

  .friendly-catalog-link:hover {
    color: #7dd3fc;
    text-decoration: underline;
  }

  .status-pill-ok {
    display: inline-flex;
    align-items: center;
    gap: 0.3rem;
    color: #4ade80;
    font-size: 0.78rem;
    font-weight: 600;
  }

  .status-pill-demo {
    display: inline-flex;
    align-items: center;
    gap: 0.3rem;
    color: #facc15;
    font-size: 0.78rem;
    font-weight: 600;
  }

  .demo-disabled-note {
    font-size: 0.78rem;
    color: #94a3b8;
    font-style: italic;
  }

  /* TIER 2: Informações técnicas (Collapsible Sub-Accordion) */
  .tier2-technical-wrapper {
    border: 1px solid rgba(51, 65, 85, 0.5);
    border-radius: 8px;
    overflow: hidden;
    background: rgba(15, 23, 42, 0.5);
  }

  .tier2-toggle-btn {
    width: 100%;
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 0.75rem;
    padding: 0.55rem 0.85rem;
    background: rgba(30, 41, 59, 0.5);
    border: none;
    color: #cbd5e1;
    font-size: 0.78rem;
    font-weight: 500;
    cursor: pointer;
    transition: background 0.15s ease;
    text-align: left;
  }

  .tier2-toggle-btn:hover {
    background: rgba(51, 65, 85, 0.6);
  }

  .tier2-toggle-btn.is-open {
    border-bottom: 1px solid rgba(51, 65, 85, 0.4);
  }

  .toggle-btn-left {
    display: flex;
    align-items: center;
    gap: 0.45rem;
  }

  .tier-ico {
    color: #a855f7;
    flex-shrink: 0;
  }

  .toggle-title {
    font-weight: 600;
    color: #e2e8f0;
  }

  .toggle-sub {
    font-size: 0.72rem;
    color: #64748b;
  }

  .toggle-btn-right {
    display: flex;
    align-items: center;
    gap: 0.35rem;
  }

  .toggle-action-hint {
    font-size: 0.72rem;
    color: #94a3b8;
  }

  .tech-chevron {
    color: #94a3b8;
    transition: transform 0.2s ease;
  }

  .tech-chevron.is-flipped {
    transform: rotate(180deg);
  }

  .tier2-technical-content {
    padding: 0.75rem 0.85rem;
    background: rgba(15, 23, 42, 0.4);
    animation: fadeIn 0.15s ease;
  }

  .tech-grid {
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
  }

  .tech-kv-row {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 0.75rem;
    font-size: 0.78rem;
  }

  .tech-kv-label {
    color: #64748b;
    font-weight: 500;
    flex-shrink: 0;
  }

  .tech-kv-value {
    color: #e2e8f0;
    font-weight: 500;
    display: flex;
    align-items: center;
    justify-content: flex-end;
  }

  .tech-fallback-val {
    color: #94a3b8;
    font-style: italic;
  }

  /* UUID 1-Click Copy Group */
  .uuid-copy-group {
    display: inline-flex;
    align-items: center;
    gap: 0.35rem;
    max-width: 100%;
  }

  .uuid-code-text {
    font-family: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;
    font-size: 0.74rem;
    color: #93c5fd;
    background: rgba(15, 23, 42, 0.8);
    border: 1px solid rgba(59, 130, 246, 0.3);
    padding: 0.15rem 0.45rem;
    border-radius: 4px;
    max-width: 260px;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
  }

  .btn-copy-uuid {
    display: inline-flex;
    align-items: center;
    gap: 0.25rem;
    background: rgba(30, 41, 59, 0.8);
    border: 1px solid rgba(71, 85, 105, 0.5);
    color: #cbd5e1;
    padding: 0.2rem 0.4rem;
    border-radius: 4px;
    cursor: pointer;
    font-size: 0.7rem;
    transition: all 0.15s ease;
    flex-shrink: 0;
  }

  .btn-copy-uuid:hover {
    background: #334155;
    color: #ffffff;
    border-color: #60a5fa;
  }

  .copy-success-ico {
    color: #22c55e;
  }

  .copied-pill {
    color: #4ade80;
    font-weight: 600;
    font-size: 0.68rem;
  }

  .conf-pill-ok {
    display: inline-flex;
    align-items: center;
    gap: 0.3rem;
    color: #4ade80;
    font-size: 0.76rem;
    font-weight: 500;
  }

  .conf-pill-neutral {
    color: #94a3b8;
    font-size: 0.76rem;
  }

  /* -------------------------------------------------------------
     6. PAGINATION BAR
     ------------------------------------------------------------- */
  .pagination-bar {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 1rem;
    padding: 0.85rem 0.25rem 0;
    border-top: 1px solid rgba(51, 65, 85, 0.4);
    flex-wrap: wrap;
  }

  .pagination-info {
    font-size: 0.8rem;
    color: #94a3b8;
  }

  .page-current {
    font-weight: 700;
    color: #f1f5f9;
  }

  .pagination-range {
    color: #64748b;
    margin-left: 0.35rem;
  }

  .pagination-buttons {
    display: flex;
    align-items: center;
    gap: 0.35rem;
  }

  .page-nav-btn {
    display: inline-flex;
    align-items: center;
    gap: 0.3rem;
    background: #1e293b;
    border: 1px solid #334155;
    color: #cbd5e1;
    font-size: 0.78rem;
    font-weight: 500;
    padding: 0.4rem 0.65rem;
    border-radius: 6px;
    cursor: pointer;
    transition: all 0.15s ease;
  }

  .page-nav-btn:hover:not(:disabled) {
    background: #334155;
    color: #ffffff;
  }

  .page-nav-btn:disabled {
    opacity: 0.4;
    cursor: not-allowed;
  }

  .page-number-strip {
    display: flex;
    align-items: center;
    gap: 0.25rem;
  }

  .page-number-btn {
    background: transparent;
    border: 1px solid transparent;
    color: #94a3b8;
    font-size: 0.78rem;
    font-weight: 600;
    width: 32px;
    height: 32px;
    border-radius: 6px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    cursor: pointer;
    transition: all 0.15s ease;
  }

  .page-number-btn:hover {
    background: #1e293b;
    color: #f1f5f9;
  }

  .page-number-btn.is-active {
    background: #22c55e;
    color: #ffffff;
    font-weight: 700;
  }

  .page-ellipsis {
    color: #64748b;
    padding: 0 0.2rem;
    font-size: 0.8rem;
  }

  /* -------------------------------------------------------------
     7. COMPACT EMPTY STATE
     ------------------------------------------------------------- */
  .empty-history-box {
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    text-align: center;
    background: #0f172a;
    border: 1px dashed #334155;
    border-radius: 12px;
    padding: 2.5rem 1.5rem;
    gap: 0.65rem;
    max-width: 520px;
    margin: 1.5rem auto;
  }

  .empty-icon-circle {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 48px;
    height: 48px;
    border-radius: 50%;
    background: rgba(51, 65, 85, 0.4);
    color: #94a3b8;
    margin-bottom: 0.25rem;
  }

  .empty-title {
    font-size: 1.05rem;
    font-weight: 600;
    color: #f1f5f9;
    margin: 0;
  }

  .empty-desc {
    font-size: 0.82rem;
    color: #94a3b8;
    line-height: 1.45;
    margin: 0;
  }

  .btn-empty-clear {
    background: #1e293b;
    border: 1px solid #334155;
    color: #60a5fa;
    font-size: 0.78rem;
    font-weight: 600;
    padding: 0.45rem 0.9rem;
    border-radius: 6px;
    cursor: pointer;
    margin-top: 0.5rem;
    transition: all 0.15s ease;
  }

  .btn-empty-clear:hover {
    background: #334155;
    color: #93c5fd;
  }

  /* -------------------------------------------------------------
     MOBILE OPTIMIZATIONS (ANDROID: 320px - 430px) (Item 8)
     ------------------------------------------------------------- */
  @media (max-width: 768px) {
    .desktop-only {
      display: none !important;
    }

    .mobile-only {
      display: inline !important;
    }

    .homologation-utility-bar {
      padding: 0.25rem 0.5rem;
      border-radius: 6px;
    }

    .homologation-inner-row {
      gap: 0.5rem;
      white-space: nowrap;
    }

    .btn-scenarios-toggle {
      padding: 0.2rem 0.45rem;
      font-size: 0.72rem;
      white-space: nowrap;
      gap: 0.3rem;
    }

    .preview-env-badge {
      font-size: 0.72rem;
      gap: 0.35rem;
      white-space: nowrap;
    }

    .publicado-view-root {
      padding: 0 0.5rem 4.5rem;
      gap: 0.85rem;
    }

    .publicado-header-bar {
      flex-direction: column;
      align-items: stretch;
      gap: 0.75rem;
    }

    .publicado-controls-cluster {
      flex-direction: column;
      align-items: stretch;
      gap: 0.5rem;
    }

    .compact-search-input,
    .compact-work-select,
    .compact-sort-select {
      width: 100%;
      min-width: 0;
      height: 42px; /* Minimum ergonomic touch target */
      font-size: 0.88rem;
    }

    .search-input-shell,
    .work-filter-shell,
    .sort-select-shell {
      width: 100%;
    }

    /* Summary Card on Mobile */
    .card-summary-row {
      flex-direction: column;
      align-items: stretch;
      gap: 0.75rem;
      padding: 0.75rem;
    }

    /* Main Info Group: Cover on left, Title & details on right (Item 3) */
    .card-main-info-group {
      display: flex;
      align-items: flex-start;
      gap: 0.75rem;
      width: 100%;
    }

    /* Work Cover on Mobile (44×62px) */
    .cover-thumb-wrapper {
      width: 44px;
      height: 62px;
      border-radius: 6px;
      flex-shrink: 0;
    }

    .card-body-col {
      flex: 1;
      min-width: 0;
      display: flex;
      flex-direction: column;
      gap: 0.2rem;
    }

    .work-and-status-row {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 0.4rem;
      flex-wrap: wrap;
    }

    .chapter-display-title {
      font-size: 0.94rem;
      white-space: normal;
      word-break: break-word;
      line-height: 1.3;
    }

    .meta-inline-strip {
      flex-wrap: wrap;
      gap: 0.25rem 0.45rem;
      font-size: 0.73rem;
    }

    .card-actions-cluster {
      width: 100%;
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 0.5rem;
    }

    .btn-read-chapter,
    .btn-toggle-details {
      width: 100%;
      justify-content: center;
      min-height: 44px; /* Ergonomic 44px touch target */
      font-size: 0.84rem;
    }

    .card-expanded-panel {
      padding: 0.85rem;
      gap: 0.85rem;
    }

    .main-info-grid {
      grid-template-columns: 1fr;
      gap: 0.65rem;
      padding: 0.75rem;
    }

    .tech-kv-row {
      flex-direction: column;
      align-items: flex-start;
      gap: 0.2rem;
    }

    .tech-kv-value {
      justify-content: flex-start;
      width: 100%;
    }

    .uuid-copy-group {
      width: 100%;
      justify-content: space-between;
    }

    .uuid-code-text {
      max-width: 200px;
    }

    .pagination-bar {
      flex-direction: column;
      align-items: center;
      gap: 0.75rem;
    }

    .pagination-buttons {
      width: 100%;
      justify-content: space-between;
    }

    .nav-btn-text {
      display: none;
    }

    .page-nav-btn {
      min-height: 40px;
      padding: 0.4rem 0.8rem;
    }
  }

  /* Ultra-compact screens (320px - 360px) */
  @media (max-width: 360px) {
    .stage-main-title {
      font-size: 1.25rem;
    }

    .card-actions-cluster {
      grid-template-columns: 1fr;
      gap: 0.45rem;
    }

    .uuid-code-text {
      max-width: 160px;
    }

    .scenarios-popover-menu {
      width: 230px;
    }
  }

