  .qc-approve-check-list {
    display: flex;
    flex-direction: column;
    gap: 8px;
    background: rgba(255, 255, 255, 0.02);
    border: 1px solid rgba(255, 255, 255, 0.06);
    border-radius: 8px;
    padding: 12px;
  }

  .check-row {
    display: flex;
    align-items: center;
    gap: 8px;
    font-size: 0.8125rem;
    color: #cbd5e1;
  }

  .check-row.is-fail {
    color: #f87171;
  }

  :global(.check-icon) {
    color: #10b981;
    flex-shrink: 0;
  }

  :global(.check-icon.fail) {
    color: #f87171;
  }

  .btn-confirm-approve {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    background: #10b981;
    border: 1px solid #059669;
    color: #ffffff;
    padding: 8px 18px;
    border-radius: 8px;
    font-size: 0.8125rem;
    font-weight: 700;
    cursor: pointer;
  }

  .btn-confirm-approve:disabled {
    opacity: 0.45;
    cursor: not-allowed;
    background: rgba(255, 255, 255, 0.08);
    border-color: rgba(255, 255, 255, 0.12);
    color: #71717a;
    box-shadow: none;
  }

  .btn-confirm-approve:hover:not(:disabled) {
    background: #059669;
  }

  /* Toast Notification */
  .qc-toast {
    position: fixed;
    bottom: 24px;
    left: 50%;
    transform: translateX(-50%);
    background: #1e1e28;
    border: 1px solid #a855f7;
    color: #ffffff;
    padding: 10px 18px;
    border-radius: 24px;
    font-size: 0.875rem;
    font-weight: 600;
    display: flex;
    align-items: center;
    gap: 8px;
    box-shadow: 0 8px 24px rgba(0, 0, 0, 0.6);
    z-index: 200;
    animation: qc-toast-in 0.2s ease-out;
  }

  :global(.toast-icon) {
    color: #10b981;
  }

  @keyframes qc-toast-in {
    from {
      opacity: 0;
      transform: translate(-50%, 12px);
    }
    to {
      opacity: 1;
      transform: translate(-50%, 0);
    }
  }

