  }

  .task-compact-card.is-rework {
    border-color: rgba(245, 158, 11, 0.45);
    background: linear-gradient(135deg, rgba(28, 20, 16, 0.75) 0%, rgba(20, 21, 30, 0.98) 100%);
  }

