  /* ========================================================
     4. ACESSO RÁPIDO AO STUDIO: 4 TILES (Solves desktop empty void)
     ======================================================== */
  .shortcuts-section {
    padding-top: 0.15rem;
    min-width: 0;
  }

  .shortcuts-grid {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 0.55rem;
  }

  .shortcut-tile {
    background: #141520;
    border: 1px solid rgba(255, 255, 255, 0.07);
    border-radius: 10px;
    padding: 0.6rem 0.65rem;
    display: flex;
    align-items: center;
    gap: 0.55rem;
    cursor: pointer;
    text-align: left;
    transition: background 0.15s ease, border-color 0.15s ease, transform 0.1s ease, box-shadow 0.15s ease;
    min-height: 52px;
  }

  @media (min-width: 640px) {
    .shortcut-tile {
      padding: 0.65rem 0.8rem;
      gap: 0.65rem;
    }
  }

  .shortcut-tile:hover {
    background: #181928;
    border-color: rgba(139, 92, 246, 0.35);
    transform: translateY(-1px);
    box-shadow: 0 4px 14px rgba(0, 0, 0, 0.3), 0 0 10px rgba(139, 92, 246, 0.08);
  }

  .shortcut-tile.shortcut-prod:hover {
    border-color: rgba(168, 85, 247, 0.45);
    box-shadow: 0 4px 14px rgba(0, 0, 0, 0.3), 0 0 10px rgba(168, 85, 247, 0.12);
  }

  .shortcut-tile.shortcut-queue:hover {
    border-color: rgba(99, 102, 241, 0.45);
    box-shadow: 0 4px 14px rgba(0, 0, 0, 0.3), 0 0 10px rgba(99, 102, 241, 0.12);
  }

  .shortcut-tile.shortcut-mural:hover {
    border-color: rgba(245, 158, 11, 0.45);
    box-shadow: 0 4px 14px rgba(0, 0, 0, 0.3), 0 0 10px rgba(245, 158, 11, 0.12);
  }

  .shortcut-tile.shortcut-cal:hover {
    border-color: rgba(6, 182, 212, 0.45);
    box-shadow: 0 4px 14px rgba(0, 0, 0, 0.3), 0 0 10px rgba(6, 182, 212, 0.12);
  }

  .shortcut-tile:active {
    transform: scale(0.98);
  }

  .shortcut-icon-bubble {
    width: 32px;
    height: 32px;
    border-radius: 8px;
    background: rgba(255, 255, 255, 0.04);
    display: flex;
    align-items: center;
    justify-content: center;
    flex-shrink: 0;
  }

  .shortcut-text {
    display: flex;
    flex-direction: column;
    gap: 0.05rem;
    min-width: 0;
    overflow: hidden;
  }

  .shortcut-name {
    font-size: 0.79rem;
    font-weight: 700;
    letter-spacing: -0.015em;
    color: #f4f4f5;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
  }

  @media (min-width: 640px) {
    .shortcut-name {
      font-size: 0.85rem;
      letter-spacing: 0;
    }
  }

  .shortcut-hint {
    font-size: 0.72rem;
    color: #94a3b8;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
  }

  @media (max-width: 639px) {
    .shortcuts-grid {
      gap: 0.45rem;
    }
    .shortcut-tile {
      min-height: 40px;
      padding: 0.42rem 0.6rem;
      gap: 0.5rem;
    }
    .shortcut-icon-bubble {
      width: 26px;
      height: 26px;
      border-radius: 6px;
    }
    .shortcut-icon-bubble :global(svg) {
      width: 14px;
      height: 14px;
    }
    .shortcut-name {
      font-size: 0.76rem;
    }
    .shortcut-hint {
      display: none;
    }
  }

  /* ========================================================
     DESKTOP SCALE CALIBRATION (Linear/Notion Studio Grade)
     Enhances legibility and proportions on >= 1024px
     ======================================================== */
  @media (min-width: 1024px) {
    .header-title {
      font-size: 1.45rem;
    }
    .section-heading {
      font-size: 1.18rem;
    }
    .section-caption {
      font-size: 0.84rem;
    }
    .task-compact-card {
      padding: 0.95rem 1.25rem;
      gap: 1.15rem;
      min-height: 86px;
    }
    .task-visual-col,
    .task-stage-icon-fallback {
      width: 50px;
      height: 67px;
      border-radius: 8px;
    }
    .task-work-name {
      font-size: 1.10rem;
      line-height: 1.35;
    }
    .meta-pill {
      font-size: 0.82rem;
      padding: 0.16rem 0.55rem;
    }
    .btn-continue-task {
      font-size: 0.86rem;
      padding: 0.46rem 0.95rem;
      min-height: 38px;
    }
    .avail-stage-name {
      font-size: 0.94rem;
    }
    .avail-stage-count-text {
      font-size: 0.80rem;
    }
    .available-stage-pill {
      min-height: 54px;
      padding: 0.75rem 1rem;
    }
    .clear-title {
      font-size: 0.94rem;
    }
    .clear-desc {
      font-size: 0.82rem;
    }
    .alert-compact-line {
      min-height: 46px;
      padding: 0.65rem 0.95rem;
    }
    .alert-line-text {
      font-size: 0.84rem;
    }
    .shortcut-tile {
      min-height: 62px;
      padding: 0.75rem 0.95rem;
      gap: 0.75rem;
    }
    .shortcut-icon-bubble {
      width: 36px;
      height: 36px;
      border-radius: 9px;
    }
    .shortcut-name {
      font-size: 0.90rem;
    }
    .shortcut-hint {
      font-size: 0.76rem;
    }
  }

  /* Accessibility & System Preferences */
  button:focus-visible,
  [role="button"]:focus-visible {
    outline: 2px solid #a855f7;
    outline-offset: 2px;
  }

  @media (prefers-reduced-motion: reduce) {
    *,
    *::before,
    *::after {
      animation-duration: 0.01ms !important;
      animation-iteration-count: 1 !important;
      transition-duration: 0.01ms !important;
      scroll-behavior: auto !important;
    }
  }

