  }

  .btn-cancel-staged:hover {
    background: rgba(255, 255, 255, 0.15);
    color: #f1f5f9;
  }

  @media (prefers-reduced-motion: reduce) {
    .logo-preview-img,
    .banner-preview-img {
      animation: none !important;
      transition: none !important;
    }
  }

