    align-items: center;
    justify-content: center;
    background: radial-gradient(circle, rgba(168, 85, 247, 0.15) 0%, rgba(20, 16, 32, 0.8) 100%);
  }

  .fallback-emoji {
    font-size: 1.5rem;
  }

  :global(.task-fallback-icon) {
    color: #a855f7;
  }

  /* Middle Details */
  .card-details-col {
    flex: 1 1 0%;
    min-width: 0;
    display: flex;
    flex-direction: column;
    gap: 7px;
  }

  .card-title-row {
    display: flex;
    align-items: center;
    gap: 8px;
  }

  .task-work-name {
    font-size: 1.3125rem; /* ~21px */
    font-weight: 750;
    color: #ffffff;
    margin: 0;
    line-height: 1.25;
    white-space: normal;
    display: -webkit-box;
    -webkit-line-clamp: 2;
    -webkit-box-orient: vertical;
    overflow: hidden;
    letter-spacing: -0.015em;
  }

  .card-meta-row {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
  }

  .meta-pill {
    display: inline-flex;
    align-items: center;
    gap: 5px;
    padding: 3px 10px;
    border-radius: 6px;
    font-size: 0.84375rem; /* ~13.5px */
    font-weight: 600;
    line-height: 1.4;
  }

  .meta-pill.chapter {
    background: rgba(255, 255, 255, 0.06);
    border: 1px solid rgba(255, 255, 255, 0.09);
    color: #e2e8f0;
    font-weight: 600;
  }

  .meta-pill.stage {
    background: color-mix(in srgb, var(--stage-c, #8b5cf6) 18%, transparent);
    color: color-mix(in srgb, var(--stage-c, #8b5cf6) 95%, #ffffff);
    border: 1px solid color-mix(in srgb, var(--stage-c, #8b5cf6) 38%, transparent);
    font-weight: 650;
  }

  .meta-pill.stage .dot {
    width: 7px;
    height: 7px;
    border-radius: 50%;
    background: var(--stage-c, #8b5cf6);
    box-shadow: 0 0 5px color-mix(in srgb, var(--stage-c, #8b5cf6) 60%, transparent);
  }

  .meta-pill.urgent {
    background: rgba(244, 63, 94, 0.15);
    color: #fb7185;
    border: 1px solid rgba(244, 63, 94, 0.3);
  }

  .meta-pill.high {
    background: rgba(245, 158, 11, 0.15);
    color: #fbbf24;
    border: 1px solid rgba(245, 158, 11, 0.3);
  }

  .meta-pill.rework {
    background: rgba(245, 158, 11, 0.2);
    color: #fbbf24;
    border: 1px solid rgba(245, 158, 11, 0.4);
    font-weight: 600;
  }

  .meta-pill.deadline {
    background: rgba(255, 255, 255, 0.05);
    color: #94a3b8;
  }

  .meta-pill.deadline.is-overdue {
    background: rgba(239, 68, 68, 0.14);
    color: #f87171;
    border: 1px solid rgba(239, 68, 68, 0.3);
    font-weight: 600;
  }

  .category-context-notice {
    display: inline-flex;
    align-items: center;
    gap: 8px;
    padding: 8px 14px;
    background: rgba(168, 85, 247, 0.08);
    border: 1px solid rgba(168, 85, 247, 0.2);
    border-radius: 8px;
    font-size: 0.8125rem;
    color: #cbd5e1;
    margin-bottom: 4px;
  }

  .category-context-notice :global(.notice-icon) {
    color: #c084fc;
    flex-shrink: 0;
  }

  .meta-pill.stale-inactivity {
    background: rgba(245, 158, 11, 0.08);
    color: #f59e0b;
    border: 1px solid rgba(245, 158, 11, 0.22);
    font-size: 0.8125rem; /* ~13px */
    font-weight: 500;
    padding: 3px 9px;
  }

  .meta-pill.waiting-status {
    background: rgba(148, 163, 184, 0.1);
    color: #cbd5e1;
  }

  .meta-pill.completed-pill {
    background: rgba(16, 185, 129, 0.15);
    color: #34d399;
    border: 1px solid rgba(16, 185, 129, 0.3);
  }

  .meta-text-muted {
    font-size: 0.8125rem;
    color: #94a3b8;
  }

  /* Actions Region (Desktop V7.4.2 Integrated Footer Row) */
  .card-actions-col {
    display: flex;
    align-items: center;
    gap: 12px;
    width: 100%;
    padding-top: 14px;
    margin-top: 2px;
    border-top: 1px solid rgba(255, 255, 255, 0.07);
    box-sizing: border-box;
  }

  .card-actions-col .action-form-full {
    flex: 1.5 1 0%;
    display: flex;
  }

  .btn-action-continue,
  .btn-action-claim {
    flex: 1.5 1 0%;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 7px;
    height: 46px;
    min-height: 46px;
    padding: 0 20px;
    background: linear-gradient(135deg, #9333ea 0%, #7c3aed 100%);
    border: 1px solid rgba(255, 255, 255, 0.16);
    border-radius: 8px;
    font-size: 0.9375rem; /* 15px */
    font-weight: 650;
    color: #ffffff;
    cursor: pointer;
    transition: transform 0.12s ease, filter 0.15s ease;
    width: 100%;
  }

  .btn-action-continue:hover,
  .btn-action-claim:hover {
    filter: brightness(1.12);
    transform: translateY(-1px);
  }

  :global(.btn-arrow-icon) {
    transition: transform 0.12s ease;
  }
  .btn-action-continue:hover :global(.btn-arrow-icon) {
    transform: translateX(3px);
  }

  .btn-toggle-expand,
  .btn-timeline-ghost {
    flex: 1 1 0%;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 6px;
    height: 46px;
    min-height: 46px;
    padding: 0 16px;
    background: rgba(255, 255, 255, 0.05);
    border: 1px solid rgba(255, 255, 255, 0.1);
    border-radius: 8px;
    font-size: 0.90625rem; /* 14.5px */
    font-weight: 550;
    color: #e2e8f0;
    cursor: pointer;
    transition: all 0.15s ease;
  }

  .btn-toggle-expand:hover,
  .btn-timeline-ghost:hover {
    background: rgba(255, 255, 255, 0.08);
    color: #ffffff;
    border-color: rgba(255, 255, 255, 0.18);
  }

  .btn-toggle-expand.is-expanded {
    background: rgba(168, 85, 247, 0.16);
    border-color: rgba(168, 85, 247, 0.4);
    color: #c084fc;
  }

  .btn-timeline-ghost.full-mobile {
    width: 100%;
  }

  /* Inline Expandable Panel */
  .card-inline-panel {
    display: flex;
    flex-direction: column;
    gap: 14px;
    padding: 16px;
    border-top: 1px solid rgba(255, 255, 255, 0.06);
    background: rgba(14, 11, 22, 0.65);
  }

  .rework-alert-banner {
    display: flex;
    align-items: flex-start;
    gap: 10px;
    padding: 10px 14px;
    border-radius: 8px;
    background: rgba(245, 158, 11, 0.12);
    border: 1px solid rgba(245, 158, 11, 0.3);
    color: #fde68a;
    font-size: 0.8125rem;
  }

  .rework-alert-banner strong {
    color: #fbbf24;
  }

  .rework-alert-banner p {
    margin: 2px 0 0;
    color: #fef3c7;
  }

  .panel-section {
    display: flex;
    flex-direction: column;
    gap: 8px;
  }

  .section-title {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    font-size: 0.75rem;
    font-weight: 600;
    color: #cbd5e1;
    text-transform: uppercase;
    letter-spacing: 0.04em;
  }

  .deps-download-list {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
  }

  .dep-download-chip {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    padding: 6px 12px;
    border-radius: 6px;
    background: rgba(255, 255, 255, 0.06);
    border: 1px solid rgba(255, 255, 255, 0.08);
    font-size: 0.75rem;
    color: #93c5fd;
    text-decoration: none;
    transition: background 0.15s ease;
  }

  .dep-download-chip:hover {
    background: rgba(59, 130, 246, 0.15);
  }

  .panel-footer-actions {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 12px;
    padding-top: 8px;
    border-top: 1px solid rgba(255, 255, 255, 0.04);
  }

  .left-actions,
  .right-actions {
    display: flex;
    align-items: center;
    gap: 8px;
  }

  .btn-ghost-sm {
    display: inline-flex;
    align-items: center;
    gap: 5px;
    height: 32px;
    padding: 0 10px;
    background: transparent;
    border: 1px solid rgba(255, 255, 255, 0.08);
    border-radius: 6px;
    font-size: 0.75rem;
    color: #94a3b8;
    cursor: pointer;
  }

  .btn-ghost-sm:hover {
    background: rgba(255, 255, 255, 0.06);
    color: #f1f5f9;
  }

  .btn-complete-task {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    height: 34px;
    padding: 0 14px;
    background: #10b981;
    border: none;
    border-radius: 6px;
    font-size: 0.8125rem;
    font-weight: 600;
    color: #ffffff;
    cursor: pointer;
  }

  .btn-complete-task:disabled {
    opacity: 0.45;
    cursor: not-allowed;
  }

  /* Empty State */
  .empty-state-box {
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    text-align: center;
    padding: 48px 24px;
    background: rgba(18, 14, 28, 0.5);
    border: 1px dashed rgba(255, 255, 255, 0.1);
    border-radius: 12px;
    margin: 12px 0;
  }

  .empty-icon-wrap {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 64px;
    height: 64px;
    border-radius: 50%;
    margin-bottom: 16px;
  }

  .empty-icon-wrap.emerald {
    background: rgba(16, 185, 129, 0.12);
    color: #34d399;
  }

  .empty-icon-wrap.purple {
    background: rgba(168, 85, 247, 0.12);
    color: #c084fc;
  }

  .empty-icon-wrap.blue {
    background: rgba(59, 130, 246, 0.12);
    color: #60a5fa;
  }

  .empty-state-box h4 {
    font-size: 1.0625rem;
    font-weight: 600;
    color: #f1f5f9;
    margin: 0 0 6px;
  }

  .empty-state-box p {
    font-size: 0.875rem;
    color: #94a3b8;
    margin: 0 0 18px;
    max-width: 440px;
  }

  .btn-empty-action {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    height: 38px;
    padding: 0 16px;
    background: rgba(168, 85, 247, 0.15);
    border: 1px solid rgba(168, 85, 247, 0.3);
    border-radius: 8px;
    font-size: 0.8125rem;
    font-weight: 600;
    color: #c084fc;
    cursor: pointer;
    transition: all 0.15s ease;
  }

  .btn-empty-action:hover {
    background: rgba(168, 85, 247, 0.25);
    color: #ffffff;
  }

  .load-more-row {
    display: flex;
    justify-content: center;
    padding: 16px 0;
  }

  .btn-load-more {
    height: 38px;
    padding: 0 20px;
    background: rgba(255, 255, 255, 0.05);
    border: 1px solid rgba(255, 255, 255, 0.08);
    border-radius: 8px;
    font-size: 0.8125rem;
    color: #cbd5e1;
    cursor: pointer;
  }

  .btn-load-more:hover {
    background: rgba(255, 255, 255, 0.1);
    color: #f8fafc;
  }

  /* Modals */
  .modal-backdrop {
    position: fixed;
    inset: 0;
    background: rgba(0, 0, 0, 0.8);
    backdrop-filter: blur(6px);
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 16px;
    z-index: 100;
  }

  .modal-card {
    background: #141022;
    border: 1px solid rgba(255, 255, 255, 0.12);
    border-radius: 12px;
    width: 100%;
    max-width: 520px;
    max-height: 90vh;
    overflow-y: auto;
    display: flex;
    flex-direction: column;
    box-shadow: 0 20px 50px rgba(0, 0, 0, 0.5);
  }

  .modal-card.wide {
    max-width: 780px;
  }

  .modal-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 16px 20px;
    border-bottom: 1px solid rgba(255, 255, 255, 0.08);
  }

  .modal-title-wrap {
    display: flex;
    align-items: center;
    gap: 8px;
  }

  .modal-title-wrap h3 {
    font-size: 1rem;
    font-weight: 600;
    color: #f8fafc;
    margin: 0;
  }

  .btn-close-modal {
    background: transparent;
    border: none;
    color: #94a3b8;
    cursor: pointer;
    padding: 4px;
    border-radius: 4px;
  }

  .modal-body {
    padding: 20px;
    display: flex;
    flex-direction: column;
    gap: 16px;
  }

  .modal-instruction {
    font-size: 0.875rem;
    color: #94a3b8;
    margin: 0;
    line-height: 1.5;
  }

  .modal-field {
    display: flex;
    flex-direction: column;
    gap: 6px;
  }

  .modal-field label {
    font-size: 0.75rem;
    font-weight: 600;
    color: #cbd5e1;
    text-transform: uppercase;
  }

  .modal-select,
  .modal-textarea {
    width: 100%;
    padding: 10px 12px;
    background: rgba(20, 16, 32, 0.8);
    border: 1px solid rgba(255, 255, 255, 0.1);
    border-radius: 8px;
    font-size: 0.875rem;
    color: #f1f5f9;
    outline: none;
    box-sizing: border-box;
  }

  .modal-select:focus,
  .modal-textarea:focus {
    border-color: rgba(168, 85, 247, 0.5);
  }

  .modal-footer {
    display: flex;
    align-items: center;
    justify-content: flex-end;
    gap: 10px;
    padding: 14px 20px;
    border-top: 1px solid rgba(255, 255, 255, 0.08);
    background: rgba(10, 7, 18, 0.5);
  }

  .btn-cancel {
    height: 36px;
    padding: 0 16px;
    background: transparent;
    border: 1px solid rgba(255, 255, 255, 0.1);
    border-radius: 6px;
    font-size: 0.8125rem;
    color: #94a3b8;
    cursor: pointer;
  }

  .btn-danger-action {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    height: 36px;
    padding: 0 16px;
    background: #ef4444;
    border: none;
    border-radius: 6px;
    font-size: 0.8125rem;
    font-weight: 600;
    color: #ffffff;
    cursor: pointer;
  }

  .btn-primary-action {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    height: 36px;
    padding: 0 16px;
    background: #a855f7;
    border: none;
    border-radius: 6px;
    font-size: 0.8125rem;
    font-weight: 600;
    color: #ffffff;
    cursor: pointer;
  }

  /* Mobile Sheet Drawer */
  .modal-sheet-drawer {
    position: fixed;
    bottom: 0;
    left: 0;
    right: 0;
    background: #141022;
    border-top: 1px solid rgba(255, 255, 255, 0.12);
    border-radius: 16px 16px 0 0;
    max-height: 85vh;
    overflow-y: auto;
    display: flex;
    flex-direction: column;
    padding: 0;
    animation: slideUpSheet 0.25s cubic-bezier(0.16, 1, 0.3, 1);
  }

  @keyframes slideUpSheet {
    from { transform: translateY(100%); }
    to { transform: translateY(0); }
  }

  .sheet-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 16px 20px;
    border-bottom: 1px solid rgba(255, 255, 255, 0.08);
  }

  .sheet-title-lockup {
    display: flex;
    align-items: center;
    gap: 8px;
  }

  .sheet-title-lockup h3 {
    margin: 0;
    font-size: 1rem;
    font-weight: 600;
    color: #f8fafc;
  }

  .sheet-body {
    padding: 20px;
    display: flex;
    flex-direction: column;
    gap: 16px;
  }

  .sheet-field {
    display: flex;
    flex-direction: column;
    gap: 6px;
  }

  .sheet-field label {
    font-size: 0.75rem;
    font-weight: 600;
    color: #cbd5e1;
    text-transform: uppercase;
  }

  .sheet-footer {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 12px;
    padding: 14px 20px 24px;
    border-top: 1px solid rgba(255, 255, 255, 0.08);
  }

  .sheet-footer .btn-cancel,
  .sheet-footer .btn-primary-action {
    flex: 1 1 0%;
  }

  /* Table for Timeline */
  .modal-sub-block {
    display: flex;
    flex-direction: column;
    gap: 10px;
  }

  .modal-sub-block h4 {
    margin: 0;
    font-size: 0.875rem;
    color: #e2e8f0;
  }

  .files-table-wrapper {
    overflow-x: auto;
    border: 1px solid rgba(255, 255, 255, 0.08);
    border-radius: 8px;
  }

  .files-table {
    width: 100%;
    border-collapse: collapse;
    font-size: 0.75rem;
    text-align: left;
  }

  .files-table th {
    padding: 8px 12px;
    background: rgba(255, 255, 255, 0.04);
    color: #94a3b8;
    font-weight: 600;
    border-bottom: 1px solid rgba(255, 255, 255, 0.08);
  }

  .files-table td {
    padding: 8px 12px;
    border-bottom: 1px solid rgba(255, 255, 255, 0.04);
    color: #cbd5e1;
  }

  .version-tag {
    display: inline-block;
    padding: 2px 6px;
    border-radius: 4px;
    background: rgba(255, 255, 255, 0.06);
    font-weight: 600;
  }

  .version-tag.current {
    background: rgba(16, 185, 129, 0.2);
    color: #34d399;
  }

  .btn-icon-link {
    display: inline-flex;
    align-items: center;
    padding: 4px 8px;
    color: #93c5fd;
    text-decoration: none;
    border-radius: 4px;
    background: rgba(59, 130, 246, 0.1);
  }

  .timeline-list {
    display: flex;
    flex-direction: column;
    gap: 8px;
    max-height: 200px;
    overflow-y: auto;
  }

  .timeline-entry {
    display: flex;
    align-items: flex-start;
    gap: 10px;
    font-size: 0.8125rem;
  }

  .timeline-dot {
    width: 8px;
    height: 8px;
    border-radius: 50%;
    background: #a855f7;
    margin-top: 5px;
  }

  .timeline-info {
    flex: 1 1 0%;
  }

  .timeline-row {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 8px;
  }

  .timeline-date {
    color: #64748b;
    font-size: 0.6875rem;
  }

  .timeline-actor {
    margin: 2px 0 0;
    color: #94a3b8;
    font-size: 0.75rem;
  }

  .desktop-only-inline {
    display: inline;
  }

  /* 5. Responsive Breakpoints */
  /* Intermediate Desktop / Tablet (769px to 1149px): Single balanced column */
  @media (min-width: 769px) and (max-width: 1149px) {
    .cards-vertical-list {
      grid-template-columns: 1fr;
      max-width: 780px;
    }
  }

  @media (max-width: 768px) {
    .tasks-tab-root {
      gap: 12px;
    }

    .queue-header-bar {
      padding: 12px 14px;
      min-height: 68px;
      margin-bottom: 0px;
    }

    .header-badge {
      display: none;
    }

    .tab-title {
      font-size: 1.25rem;
      line-height: 1.2;
    }

    .active-tasks-pill {
      font-size: 0.75rem;
      padding: 2px 8px;
    }

    .desktop-only-desc {
      display: none;
    }
    .mobile-only-desc {
      display: inline;
    }
    .desktop-pill-text {
      display: none;
    }
    .mobile-pill-text {
      display: inline;
    }

    .tab-desc {
      font-size: 0.8125rem;
      color: #94a3b8;
    }

    .desktop-search,
    .desktop-filters {
      display: none;
    }

    .mobile-filter-bar {
      display: flex;
      align-items: center;
      gap: 8px;
      width: 100%;
      justify-content: flex-start;
    }

    .btn-mobile-search-toggle {
      display: inline-flex;
      align-items: center;
      justify-content: center;
      gap: 7px;
      height: 38px;
      padding: 0 16px;
      background: rgba(255, 255, 255, 0.04);
      border: 1px solid rgba(255, 255, 255, 0.08);
      border-radius: 20px;
      font-size: 0.8125rem;
      font-weight: 500;
      color: #cbd5e1;
      cursor: pointer;
      flex: 0 0 auto;
      transition: all 0.15s ease;
    }

    .btn-mobile-search-toggle:hover {
      background: rgba(255, 255, 255, 0.07);
      border-color: rgba(255, 255, 255, 0.14);
      color: #ffffff;
    }

    .btn-mobile-filter-toggle {
      display: inline-flex;
      align-items: center;
      justify-content: center;
      gap: 6px;
      height: 38px;
      padding: 0 14px;
      background: rgba(255, 255, 255, 0.03);
      border: 1px solid rgba(255, 255, 255, 0.07);
      border-radius: 20px;
      font-size: 0.8125rem;
      font-weight: 500;
      color: #94a3b8;
      cursor: pointer;
      flex: 0 0 auto;
      transition: all 0.15s ease;
    }

    .btn-mobile-filter-toggle:hover {
      background: rgba(255, 255, 255, 0.06);
      color: #cbd5e1;
    }

    .btn-mobile-filter-toggle.has-active {
      background: rgba(168, 85, 247, 0.15);
      border-color: rgba(168, 85, 247, 0.35);
      color: #e9d5ff;
    }

    .mobile-search-active-pill {
      display: inline-flex;
      align-items: center;
      gap: 6px;
