  /* Command Dock: Search + Filters */
  .command-dock {
    display: flex;
    flex-direction: column;
    gap: 1rem;
    background: rgba(13, 17, 30, 0.75);
    border: 1px solid rgba(255, 255, 255, 0.06);
    border-radius: 16px;
    padding: 0.85rem 1rem;
  }

  .search-field {
    position: relative;
    display: flex;
    align-items: center;
  }

  :global(.search-icon) {
    position: absolute;
    left: 1rem;
    color: #64748b;
    pointer-events: none;
  }

  .search-input {
    width: 100%;
    background: rgba(18, 24, 43, 0.9);
    border: 1px solid rgba(255, 255, 255, 0.08);
    border-radius: 12px;
    padding: 0.75rem 2.75rem 0.75rem 2.85rem;
    color: #ffffff;
    font-size: 0.92rem;
