  .spotlight-banner-overlay {
    position: absolute;
    inset: 0;
    background: linear-gradient(180deg, rgba(10, 13, 24, 0.15) 0%, transparent 40%, rgba(10, 13, 24, 0.75) 100%);
    pointer-events: none;
  }

  /* Spotlight Body & Identity Header (Abaixo do Banner - Proporção Intermediária Clean) */
  .spotlight-body {
