  }

  .seal-partner {
    display: inline-flex;
    align-items: center;
    gap: 0.35rem;
    background: rgba(14, 165, 233, 0.18);
    border: 1px solid rgba(14, 165, 233, 0.45);
    border-radius: 6px;
    padding: 0.15rem 0.55rem;
    font-size: 0.68rem;
