  /* ==========================================================================
     RECRUITMENT SHOWCASE BOX (COMPACTO E EQUILIBRADO)
     ========================================================================== */
  .recruitment-showcase-box {
    background: linear-gradient(135deg, rgba(20, 26, 44, 0.85) 0%, rgba(13, 17, 30, 0.95) 100%);
    border: 1px solid rgba(16, 185, 129, 0.25);
    border-radius: 14px;
    padding: 1rem 1.25rem;
    position: relative;
    overflow: hidden;
  }

  .recruitment-showcase-box::before {
    content: "";
    position: absolute;
    top: 0;
    left: 0;
    width: 3px;
    height: 100%;
    background: linear-gradient(180deg, #10b981 0%, #06b6d4 100%);
  }

  .recruitment-showcase-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    margin-bottom: 0.75rem;
  }

  .recruitment-header-left {
    display: flex;
    align-items: center;
    gap: 0.75rem;
  }

  .beacon-icon-wrap {
    width: 28px;
    height: 28px;
    border-radius: 8px;
    background: rgba(16, 185, 129, 0.15);
    border: 1px solid rgba(16, 185, 129, 0.3);
    color: #34d399;
    display: flex;
    align-items: center;
    justify-content: center;
