  /* Profile Banner */
  .profile-banner-wrap {
    aspect-ratio: 16 / 5;
    width: 100%;
    position: relative;
    background: #141724;
    overflow: hidden;
  }

  .profile-banner-img {
    width: 100%;
    height: 100%;
    object-fit: cover;
  }

  .profile-banner-fallback {
    width: 100%;
    height: 100%;
    background:
      radial-gradient(ellipse at 80% 20%, rgba(139, 92, 246, 0.28), transparent 60%),
      radial-gradient(ellipse at 20% 80%, rgba(223, 194, 141, 0.18), transparent 50%),
      linear-gradient(135deg, #181b2e 0%, #0c0e18 100%);
    position: relative;
    border-bottom: 1px solid rgba(255, 255, 255, 0.06);
  }

  .profile-banner-fallback::after {
    content: '';
    position: absolute;
    inset: 0;
    background: repeating-linear-gradient(
      45deg,
      rgba(255, 255, 255, 0.015) 0,
      rgba(255, 255, 255, 0.015) 1px,
