  }

  .cosmetic-title {
    font-size: 0.92rem;
    font-weight: 700;
    color: #ffffff;
    margin: 0;
  }

  .cosmetic-desc {
    font-size: 0.75rem;
    color: #94a3b8;
    line-height: 1.35;
    margin: 0;
