  /* Responsive Media Queries */
  @media (max-width: 860px) {
    .stats-grid {
      grid-template-columns: repeat(3, minmax(0, 1fr));
    }
  }

  @media (max-width: 640px) {
    .profile-page {
      padding: 0.75rem 0.6rem 3.5rem;
    }

    .profile-card {
      border-radius: 16px;
    }

    .profile-body {
      padding: 0 1.1rem 2rem;
    }

    .profile-banner-wrap {
      aspect-ratio: 16 / 6;
    }

    .identity-row {
      align-items: center;
      margin-top: -42px;
      margin-bottom: 1.15rem;
      gap: 0.75rem;
    }

    .avatar-holder :global(.user-avatar-root) {
      box-shadow: 0 10px 26px rgba(0, 0, 0, 0.42);
    }

    .action-buttons {
      flex: 1;
      justify-content: flex-end;
      min-width: 0;
    }

    .btn-profile-action {
      min-height: 42px;
      justify-content: center;
      padding: 0.6rem 0.85rem;
      font-size: 0.82rem;
      white-space: nowrap;
    }

    .profile-tabs-header {
      gap: 0.25rem;
      margin-inline: -0.25rem;
      padding-inline: 0.25rem;
      scroll-snap-type: x proximity;
    }

    .profile-tab-btn {
      min-height: 44px;
      padding: 0.7rem 0.85rem;
      font-size: 0.86rem;
      scroll-snap-align: start;
    }

    .info-block {
      margin-bottom: 1.35rem;
    }

    .name-line {
      align-items: flex-start;
      gap: 0.5rem 0.6rem;
      margin-bottom: 0.5rem;
    }

    .display-name {
      width: 100%;
      font-size: clamp(1.45rem, 7vw, 1.75rem);
      line-height: 1.08;
    }

    .meta-line {
      align-items: flex-start;
      gap: 0.35rem 0.5rem;
      flex-wrap: wrap;
      line-height: 1.35;
    }

    .meta-dot {
      display: none;
    }

    .social-counts-row {
      gap: 0.55rem;
      margin-top: 1rem;
    }

    .social-count-item {
      flex: 1;
      min-width: 0;
      padding: 0.6rem 0.45rem;
      text-align: center;
      border-radius: 10px;
      background: rgba(255, 255, 255, 0.035);
    }

    .scan-badges-row {
      gap: 0.4rem;
      margin-top: 0.75rem;
    }

    .scan-staff-badge {
      max-width: 100%;
      padding: 0.3rem 0.55rem;
      font-size: 0.7rem;
    }

    .xp-strip {
      margin-inline: -0.1rem;
      padding: 0.9rem;
    }

    .stats-grid {
      grid-template-columns: repeat(2, minmax(0, 1fr));
      gap: 0.6rem;
    }

    /* Make the interactive Conquistas card span 2 cols on mobile for ample breathing room */
    .stats-grid > button:nth-child(3) {
      grid-column: span 2;
    }

    .stat-card {
      padding: 0.85rem 0.5rem;
    }

    .stat-card-num {
      font-size: 1.15rem;
    }

    .stat-unlocked {
      font-size: 1.15rem;
    }

    .stat-sep,
    .stat-total {
      font-size: 0.85rem;
    }

    .featured-content-body {
      flex-direction: column;
      text-align: center;
      gap: 0.85rem;
    }

    .featured-title-row {
      justify-content: center;
    }

    .featured-meta-row {
      justify-content: center;
    }

    .cosmetics-catalog-grid {
      grid-template-columns: repeat(auto-fill, minmax(140px, 1fr));
      gap: 0.75rem;
    }

    .achievements-catalog-grid {
      grid-template-columns: 1fr;
    }
  }

  .scan-badges-row {
    display: flex;
    flex-wrap: wrap;
    gap: 0.5rem;
    margin-top: 0.5rem;
  }

  .scan-staff-badge {
    display: inline-flex;
    align-items: center;
    gap: 0.4rem;
    padding: 0.25rem 0.65rem;
    background: rgba(139, 92, 246, 0.12);
    border: 1px solid rgba(139, 92, 246, 0.3);
    border-radius: 9999px;
    font-size: 0.76rem;
    color: #e2e8f0;
    text-decoration: none;
    transition: all 0.2s ease;
  }

  .scan-staff-badge:hover {
    background: rgba(139, 92, 246, 0.22);
    border-color: rgba(139, 92, 246, 0.5);
    transform: translateY(-1px);
  }

  .scan-staff-badge.owner {
    background: rgba(223, 194, 141, 0.15);
    border-color: rgba(223, 194, 141, 0.4);
    color: #fef08a;
  }

  .scan-badge-logo {
    width: 14px;
    height: 14px;
    border-radius: 50%;
    object-fit: cover;
  }

  .scan-badge-role {
    font-weight: 700;
  }

  .scan-badge-dot {
    opacity: 0.5;
  }

  .scan-badge-name {
    font-weight: 600;
  }

  .heart-icon {
    color: #f43f5e;
  }

  .works-cards-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(180px, 1fr));
    gap: 1.25rem;
  }

  .readings-list-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
    gap: 1rem;
  }

  .reading-history-card {
    display: flex;
    gap: 0.85rem;
    background: rgba(15, 18, 30, 0.6);
    border: 1px solid rgba(255, 255, 255, 0.07);
    border-radius: 12px;
    padding: 0.75rem;
    transition: all 0.2s ease;
  }

  .reading-history-card:hover {
    border-color: rgba(181, 154, 245, 0.3);
    transform: translateY(-2px);
  }

  .reading-cover-wrap {
    position: relative;
    width: 60px;
    height: 84px;
    border-radius: 8px;
    overflow: hidden;
    flex-shrink: 0;
    background: #090a12;
  }

  .reading-cover-img {
    width: 100%;
    height: 100%;
    object-fit: cover;
  }

  .reading-cover-placeholder {
    width: 100%;
    height: 100%;
    display: flex;
    align-items: center;
    justify-content: center;
    background: #191c32;
    font-size: 11px;
    font-weight: 800;
    color: #b59af5;
  }

  .reading-adult-tag {
    position: absolute;
    top: 4px;
    left: 4px;
    background: #dc2626;
    color: #ffffff;
    font-size: 9px;
    font-weight: 800;
    padding: 1px 4px;
    border-radius: 3px;
  }

  .reading-details {
    display: flex;
    flex-direction: column;
    justify-content: center;
    gap: 0.3rem;
    min-width: 0;
  }

  .reading-work-title {
    font-size: 0.92rem;
    font-weight: 700;
    color: #f1f5f9;
    text-decoration: none;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
  }

  .reading-work-title:hover {
    color: #dfc28d;
  }

  .reading-ch-row {
    display: flex;
    align-items: center;
    gap: 0.5rem;
  }

  .reading-chapter-badge {
    display: inline-flex;
    align-items: center;
    gap: 0.3rem;
    font-size: 0.78rem;
    font-weight: 600;
    color: #c4b5fd;
    background: rgba(139, 92, 246, 0.15);
    border: 1px solid rgba(139, 92, 246, 0.3);
    padding: 0.15rem 0.5rem;
    border-radius: 6px;
    text-decoration: none;
  }

  .reading-chapter-badge:hover {
    background: rgba(139, 92, 246, 0.25);
  }

  .reading-page-info {
    font-size: 0.75rem;
    color: #94a3b8;
  }

  .reading-timestamp {
    display: inline-flex;
    align-items: center;
    gap: 0.3rem;
    font-size: 0.74rem;
    color: #64748b;
  }

  .self-privacy-hint {
    display: inline-flex;
    align-items: center;
    gap: 0.5rem;
    padding: 0.5rem 1rem;
    background: rgba(234, 179, 8, 0.1);
    border: 1px solid rgba(234, 179, 8, 0.25);
    border-radius: 8px;
    color: #fde047;
    font-size: 0.82rem;
    margin-bottom: 1.25rem;
  }

  .empty-tab-state {
    padding: 3.5rem 1.5rem;
    text-align: center;
    background: rgba(255, 255, 255, 0.02);
    border: 1px dashed rgba(255, 255, 255, 0.08);
    border-radius: 16px;
    color: #64748b;
  }

  .empty-tab-state h4 {
    color: #f1f5f9;
    margin: 0.75rem 0 0.25rem;
    font-size: 1.05rem;
  }

  .empty-tab-state p {
    font-size: 0.85rem;
    margin: 0;
