    display: flex;
    align-items: center;
    gap: 0.5rem;
    flex-wrap: wrap;
  }

  .team-name {
    font-size: 1.15rem;
    font-weight: 800;
    color: #f8fafc;
    margin: 0;
  }

  .team-main-role {
    font-size: 0.88rem;
    font-weight: 600;
    color: #c4b5fd;
  }

  .team-main-role.owner {
    color: #fbbf24;
  }

  .team-positions-row {
    display: flex;
    flex-direction: column;
    gap: 0.4rem;
  }

  .team-positions-label {
    font-size: 0.76rem;
