    color: #64748b;
  }

  .btn-team-link {
    display: inline-flex;
    align-items: center;
    gap: 0.35rem;
    font-size: 0.82rem;
    font-weight: 600;
    color: #dfc28d;
    text-decoration: none;
    padding: 0.35rem 0.75rem;
    border-radius: 8px;
    background: rgba(223, 194, 141, 0.1);
    border: 1px solid rgba(223, 194, 141, 0.2);
