  .btn-team-link:hover {
    background: rgba(223, 194, 141, 0.2);
    color: #ffffff;
  }

  .text-amber {
    color: #fbbf24;
  }

  .text-red {
    color: #f87171;
  }

  .text-gold {
    color: #dfc28d;
  }

